function zGemedComplementaryTargetPath(metricKey, periodType = "monthly") {
  const key = String(metricKey || "")
    .replace(/[^a-z0-9.]+/gi, "_")
    .replace(/_+/g, "_")
    .replace(/^_+|_+$/g, "");
  return `complementary.zgemed.${key}${periodType === "cumulative" ? ".cumulative" : ""}`;
}

