const performanceSummaryFamilyLabels = {
  pilotage_direction: "Pilotage Direction",
  activite: "Activité",
  productivites: "Productivités",
  heures: "Heures",
  absenteisme: "Absentéisme",
  preparation_detaillee: "Préparation détaillée",
  economie_qualite: "Économie et qualité",
  affectations_dispersion: "Affectations et dispersion"
};

const performanceSourcePriorityByFamily = {
  ipo: ["GPO"],
  productivites_officielles: ["GPO"],
  activite: ["Z_GEMED", "SUIVI_GA"],
  heures: ["GPO", "SUIVI_GA", "GA_DETAIL_AGGREGATED"],
  absenteisme: ["GPO", "CGTAB"],
  preparation_detaillee: ["T_BAG"],
  economie_qualite: ["Z_GEMED"],
  affectations_dispersion: ["GA_DETAIL_AGGREGATED"]
};

function normalizePerformanceLabel(value) {
  return normalizeText(value).replace(/\s+/g, " ").trim();
}

function performanceImportSettings() {
  if (!state.settings || typeof state.settings !== "object") state.settings = ensureSettings({});
  if (!state.settings.performanceImport || typeof state.settings.performanceImport !== "object") state.settings.performanceImport = { mappings: {} };
  if (!state.settings.performanceImport.mappings || typeof state.settings.performanceImport.mappings !== "object") state.settings.performanceImport.mappings = {};
  return state.settings.performanceImport;
}

function performanceImportCatalogEntry(label) {
  const normalized = normalizePerformanceLabel(label);
  return performanceImportTargetCatalog.find(entry => normalizePerformanceLabel(entry.label) === normalized || ensureArray(entry.aliases).some(alias => normalizePerformanceLabel(alias) === normalized)) || null;
}

function performanceImportRememberMapping(sourceLabel, targetId) {
  const key = normalizePerformanceLabel(sourceLabel);
  if (!key || !targetId) return;
  const settings = performanceImportSettings();
  settings.mappings[key] = targetId;
  persistSettings();
}

function performanceImportMappingForLabel(sourceLabel) {
  const key = normalizePerformanceLabel(sourceLabel);
  if (!key) return null;
  const stored = performanceImportSettings().mappings[key];
  if (stored) {
    const catalogEntry = performanceImportTargetCatalog.find(entry => entry.id === stored);
    if (catalogEntry) return catalogEntry;
  }
  return performanceImportCatalogEntry(sourceLabel);
}

function performanceImportTargetOptions() {
  return [
    { id: "ignore", label: "Ne pas importer", type: "ignore", unit: "" },
    ...performanceImportTargetCatalog
  ];
}

function performanceImportTargetById(targetId) {
  return performanceImportTargetOptions().find(entry => entry.id === targetId) || null;
}

function performanceImportTargetFromPath(path) {
  const normalizedPath = String(path || "").trim();
  if (!normalizedPath) return null;
  return performanceImportTargetOptions().find(entry => entry.path === normalizedPath) || null;
}

function performanceImportConfidenceMeta(score) {
  const value = Number(score || 0);
  const label = value >= 85 ? "élevée" : value >= 60 ? "moyenne" : "faible";
  return { score: value, label, text: `${label} (${value}%)` };
}

function performanceImportStatusLabel(status) {
  return {
    mapped: "Mappé",
    mapped_complementary: "Donnée complémentaire",
    manual: "Mappage manuel",
    manual_complementary: "Complémentaire manuel",
    conflict: "Conflit",
    different: "Différente",
    low_confidence: "À confirmer",
    unmapped: "Non mappée",
    ignored: "Ignorée"
  }[status] || status || "À confirmer";
}

function performanceImportConfidenceScore(row) {
  const indicator = normalizePerformanceLabel(row.indicator);
  if (!indicator || row.action === "ignore") return 0;
  if (Number.isFinite(Number(row.sourceConfidenceScore))) return Number(row.sourceConfidenceScore);
  if (row.targetType === "existing") return 92;
  if (row.targetType === "complementary") return row.targetId === "complementary.generic" ? 62 : 74;
  if (row.unit && /colis|heure|%|pourcentage|€|euro|kg/i.test(row.unit)) return 58;
  return 40;
}

function performanceImportDestinationFromRow(row) {
  const candidate = performanceImportMappingForLabel(row.indicator);
  if (candidate) return candidate;
  const normalized = normalizePerformanceLabel(row.indicator);
  if (!normalized) return null;
  if (normalized.includes("direction operationnelle")) return performanceImportTargetById("complementary.gemed.direction_operationnelle");
  if (normalized.includes("ressources humaines")) return performanceImportTargetById("complementary.gemed.ressources_humaines");
  if (normalized.includes("finance gestion") || normalized.includes("finance / gestion")) return performanceImportTargetById("complementary.gemed.finance_gestion");
  if (normalized.includes("litige")) return performanceImportTargetById("quality.litiges");
  if (normalized.includes("reception")) return performanceImportTargetById("productivity.reception");
  if (normalized.includes("manutention")) return performanceImportTargetById("productivity.manutention");
  if (normalized.includes("chargement")) return performanceImportTargetById("productivity.chargement");
  if (normalized.includes("transit") || normalized.includes("transport")) return performanceImportTargetById("productivity.transit");
  if (normalized.includes("preparation") || normalized.includes("prepare")) return performanceImportTargetById("productivity.preparation");
  if (normalized.includes("colis") || normalized.includes("supports charges") || normalized.includes("palettes receptionnees") || normalized.includes("palettes recep")) return performanceImportTargetById("activity.colis_total");
  return performanceImportTargetById("complementary.generic");
}

function isZGemedSourceLabel(value = "") {
  return /z[\s_-]*gemed/i.test(String(value || ""));
}

function zGemedMetricDefinition(label = "") {
  const normalized = normalizePerformanceLabel(label);
  return zGemedMetricDefinitions.find(def => [def.label, ...ensureArray(def.aliases)].some(alias => normalizePerformanceLabel(alias) === normalized)) || null;
}

function zGemedResolvedMapping(label = "", periodType = "monthly") {
  const definition = zGemedMetricDefinition(label);
  if (!definition) return null;
  if (definition.targetType === "existing" && periodType === "monthly") {
    return {
      metricKey: definition.metricKey,
      category: definition.category,
      label: definition.label,
      unit: definition.unit,
      path: definition.targetPath,
      targetId: definition.targetId,
      targetType: "existing",
      targetLabel: definition.targetLabel || definition.label,
      confidence: "élevée"
    };
  }
  const targetId = zGemedComplementaryTargetPath(definition.metricKey, periodType === "cumulative" ? "cumulative" : "monthly");
  return {
    metricKey: definition.metricKey,
    category: definition.category,
    label: definition.label,
    unit: definition.unit,
    path: targetId,
    targetId,
    targetType: "complementary",
    targetLabel: periodType === "cumulative" && definition.cumulativeTargetLabel ? definition.cumulativeTargetLabel : definition.label,
    confidence: definition.targetType === "existing" ? "élevée" : "moyenne"
  };
}

function perfMetric() {
  return { historical: "", budget: "", actual: "", comment: "", causes: "", actions: "" };
}

function perfDefaultPeriod(year = new Date().getFullYear(), month = new Date().getMonth() + 1) {
  const jobs = Object.fromEntries(perfJobs.map(job => [job, { ...perfMetric(), hoursBudgetGap: "", hoursHistoricalGap: "", status: "green", cdiProductivity: "", cddProductivity: "", ettProductivity: "", totalProductivity: "", cdiHoursShare: "", cddHoursShare: "", ettHoursShare: "", bicReference: "", supplyAverage: "" }]));
  return {
    id: newId("performance"), year: Number(year), month: Number(month), status: "Brouillon", updatedAt: isoToday(),
    activity: { historical: "", budget: "", actual: "", comment: "", highlights: "", causes: "", projection: "" },
    ipo: { total: perfMetric(), variable: perfMetric(), mixEffect: "", directProductivityGap: "", businessMixEffect: "", indirectHoursGap: "", indirectHoursCrush: "", ipoPointCost: "", analysis: "", rootCauses: "", trend: "", projection: "" },
    productivity: jobs,
    hours: { total: perfMetric(), direct: perfMetric(), indirect: { ...perfMetric(), totalShare: "" }, overtime: "", night: "", sundays: "", holidays: "", analysis: "", causes: "", levers: "" },
    absenteeism: { total: perfMetric(), details: Object.fromEntries(perfAbsences.map(k => [k, { ...perfMetric(), hours: "" }])), comment: "", causes: "", impacts: "", hrActions: "", projection: "" },
    quality: { indicators: Object.fromEntries(perfQuality.map(k => [k, perfMetric()])), highlights: "", causes: "", correctiveActions: "" },
    palletHeight: { historical: "", objective: "", budget: "", actual: "", trend: "", comment: "", causes: "", actions: "" },
    synthesis: "", linkedManagers: [], linkedProjects: [], linkedFolders: [], linkedActions: [], linkedDecisions: [], linkedJournal: [], linkedDocuments: [], importSources: [], complementaryKpis: [],
    importReady: { excel: false, cgtab: false, guidePerformance: false, ga: false, gemed: false, tbag: false }
  };
}

function normalizePerformance(item) {
  const base = perfDefaultPeriod(item.year || new Date().getFullYear(), item.month || (new Date().getMonth() + 1));
  const merged = { ...base, ...item };
  merged.activity = { ...base.activity, ...(item.activity || {}) };
  merged.ipo = { ...base.ipo, ...(item.ipo || {}), total: { ...base.ipo.total, ...(item.ipo?.total || {}) }, variable: { ...base.ipo.variable, ...(item.ipo?.variable || {}) } };
  merged.productivity = Object.fromEntries(perfJobs.map(job => [job, { ...base.productivity[job], ...(item.productivity?.[job] || {}) }]));
  merged.hours = { ...base.hours, ...(item.hours || {}), total: { ...base.hours.total, ...(item.hours?.total || {}) }, direct: { ...base.hours.direct, ...(item.hours?.direct || {}) }, indirect: { ...base.hours.indirect, ...(item.hours?.indirect || {}) } };
  merged.absenteeism = { ...base.absenteeism, ...(item.absenteeism || {}), total: { ...base.absenteeism.total, ...(item.absenteeism?.total || {}) }, details: Object.fromEntries(perfAbsences.map(k => [k, { ...base.absenteeism.details[k], ...(item.absenteeism?.details?.[k] || {}) }])) };
  merged.quality = { ...base.quality, ...(item.quality || {}), indicators: Object.fromEntries(perfQuality.map(k => [k, { ...base.quality.indicators[k], ...(item.quality?.indicators?.[k] || {}) }])) };
  merged.palletHeight = { ...base.palletHeight, ...(item.palletHeight || {}) };
  return { ...merged, linkedManagers: ensureArray(merged.linkedManagers), linkedProjects: ensureArray(merged.linkedProjects), linkedFolders: ensureArray(merged.linkedFolders), linkedActions: ensureArray(merged.linkedActions), linkedDecisions: ensureArray(merged.linkedDecisions), linkedJournal: ensureArray(merged.linkedJournal), linkedDocuments: ensureArray(merged.linkedDocuments), importSources: ensureArray(merged.importSources), complementaryKpis: ensureArray(merged.complementaryKpis) };
}

function perfNum(v) {
  const n = Number(String(v || "").replace(",", "."));
  return Number.isFinite(n) ? n : 0;
}

function perfHas(v) {
  return String(v ?? "").trim() !== "";
}

function perfGap(actual, ref) {
  if (!perfHas(actual) || !perfHas(ref)) return { value: "", pct: "" };
  const a = perfNum(actual), r = perfNum(ref), gap = a - r;
  return { value: gap, pct: r ? gap / r * 100 : "" };
}

function perfFmt(v, suffix = "") {
  if (v === "" || v === null || Number.isNaN(v)) return "À compléter";
  return `${Number(v).toLocaleString("fr-FR", { maximumFractionDigits: 1 })}${suffix}`;
}

function perfStatus(metric) {
  const gap = perfGap(metric.actual, metric.budget).pct;
  if (gap === "") return "green";
  const abs = Math.abs(gap);
  if (abs >= 10) return "red";
  if (abs >= 5) return "orange";
  return "green";
}

function perfPeriodLabel(p) {
  return `${perfMonths[(Number(p.month) || 1) - 1]} ${p.year}`;
}

function perfKey(value) {
  return String(value || "").normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/[^a-z0-9]/gi, "").slice(0, 12).toLowerCase() || "metric";
}

function perfSelected() {
  return byId("performance", performanceSelectedId) || state.performance[0] || null;
}

function performanceDashboardSettings() {
  if (!state.settings || typeof state.settings !== "object") state.settings = ensureSettings({});
  if (!state.settings.performanceDashboard || typeof state.settings.performanceDashboard !== "object") state.settings.performanceDashboard = { objectives: {} };
  if (!state.settings.performanceDashboard.objectives || typeof state.settings.performanceDashboard.objectives !== "object") state.settings.performanceDashboard.objectives = {};
  return state.settings.performanceDashboard;
}

function performanceObjectiveStore() {
  return performanceDashboardSettings().objectives;
}

function performanceKpiIdFromLabel(label, prefix = "kpi") {
  const key = normalizePerformanceLabel(label).replace(/\s+/g, "_");
  return key ? `${prefix}.${key}` : `${prefix}.inconnu`;
}

function performancePeriodTitle(period) {
  const [month, year] = String(period || "").split("/").map(Number);
  return month && year ? `${perfMonths[month - 1]} ${year}` : (period || "Période à confirmer");
}

function performancePeriodSortValue(period) {
  const [month, year] = String(period || "").split("/").map(Number);
  return (Number(year) || 0) * 100 + (Number(month) || 0);
}

function performanceSourceKey(value = "") {
  const text = normalizeText(value);
  if (text.includes("gpo")) return "GPO";
  if (text.includes("z gemed") || text.includes("z_gemed") || text.includes("gemed")) return "Z_GEMED";
  if (text.includes("suivi ga")) return "SUIVI_GA";
  if (text.includes("ga detail") || text.includes("detail salarie") || text.includes("detail ga")) return "GA_DETAIL_AGGREGATED";
  if (text.includes("cgtab")) return "CGTAB";
  if (text.includes("t bag") || text.includes("t_bag") || text.includes("tbag")) return "T_BAG";
  if (text.includes("deos") || text.includes("saisie")) return "DEOS";
  return String(value || "").trim() || "DEOS";
}

function performanceSourceLabel(sourceKey = "") {
  return {
    GPO: "GPO",
    Z_GEMED: "Z GEMED",
    SUIVI_GA: "Suivi GA",
    GA_DETAIL_AGGREGATED: "GA détail agrégé",
    CGTAB: "CGTAB agrégé",
    T_BAG: "T-Bag",
    DEOS: "Saisie DEOS"
  }[sourceKey] || sourceKey || "Source inconnue";
}

function performanceOfficialSourceForFamily(priorityKey = "") {
  const priority = performanceSourcePriorityByFamily[priorityKey] || [];
  return priority[0] || "";
}

function performancePriorityKeyForImportRow(row = {}) {
  const metricKey = String(row.metricKey || row.targetId || "").toLowerCase();
  const category = normalizePerformanceLabel(row.category || "");
  const destinationPath = String(row.destinationPath || "");
  if (metricKey.startsWith("ipo.") || destinationPath.startsWith("ipo.")) return "ipo";
  if (metricKey.startsWith("productivity.") || destinationPath.startsWith("productivity.")) return "productivites_officielles";
  if (metricKey.startsWith("hours.") || destinationPath.startsWith("hours.")) return "heures";
  if (metricKey.startsWith("absenteeism.") || destinationPath.startsWith("absenteeism.")) return "absenteisme";
  if (metricKey.startsWith("tbag.preparation.")) return "preparation_detaillee";
  if (metricKey.startsWith("ga_detail.")) return "affectations_dispersion";
  if (/resultat|ebit|demarque|cout/.test(metricKey) || /resultat|ebit|demarque|cout/.test(category)) return "economie_qualite";
  return "activite";
}

function performanceSourceAuthority(row = {}) {
  const source = performanceSourceKey(row.source || row.sourceType || "Import");
  const priorityKey = performancePriorityKeyForImportRow(row);
  const metricKey = String(row.metricKey || row.targetId || "").toLowerCase();
  const gpoCorePilotage = source === "GPO" && (metricKey === "quality.total_gains_pertes" || metricKey === "pallet.height");
  const officialSource = gpoCorePilotage ? "GPO" : performanceOfficialSourceForFamily(priorityKey);
  const isExistingTarget = row.targetType === "existing" && row.destinationPath && !String(row.destinationPath).startsWith("complementary.");
  const sourceIsOfficial = gpoCorePilotage || !officialSource || source === officialSource;
  return { source, priorityKey, officialSource, isExistingTarget, sourceIsOfficial };
}

function performanceAnalyticalFallbackPath(row = {}) {
  const source = performanceSourceKey(row.source || row.sourceType || "Import") || "source";
  const metricKey = String(row.metricKey || row.targetId || normalizePerformanceLabel(row.destinationLabel || row.indicator) || "metric")
    .replace(/[^a-z0-9.]+/gi, "_")
    .replace(/_+/g, "_")
    .replace(/^_+|_+$/g, "");
  const src = source.toLowerCase().replace(/[^a-z0-9]+/g, "_").replace(/^_+|_+$/g, "") || "source";
  return `complementary.authority.${src}.${metricKey}`;
}

function enforcePerformanceSourceAuthority(row = {}) {
  const authority = performanceSourceAuthority(row);
  if (!authority.isExistingTarget || authority.sourceIsOfficial) return row;

  const analyticalPath = performanceAnalyticalFallbackPath(row);
  return {
    ...row,
    destinationPath: analyticalPath,
    destinationLabel: `${row.destinationLabel || row.indicator} — analytique ${performanceSourceLabel(authority.source)}`,
    destinationId: analyticalPath,
    targetId: analyticalPath,
    targetType: "complementary",
    scope: row.scope || "analysisOnly",
    confidence: row.confidence === "élevée" ? "moyenne" : (row.confidence || "moyenne"),
    sourceAuthority: "secondary",
    officialSource: authority.officialSource,
    authorityReason: `Source secondaire : ${performanceSourceLabel(authority.source)}. Source officielle : ${performanceSourceLabel(authority.officialSource)}.`
  };
}
function performanceMetricFamilyPriorityKey(metricDef = {}) {
  const key = String(metricDef.metricKey || "").toLowerCase();
  if (key.startsWith("ipo.")) return "ipo";
  if (key.startsWith("productivity.")) return "productivites_officielles";
  if (metricDef.family === "activite") return "activite";
  if (metricDef.family === "heures") return "heures";
  if (metricDef.family === "absenteisme") return "absenteisme";
  if (metricDef.family === "preparation_detaillee") return "preparation_detaillee";
  if (metricDef.family === "economie_qualite") return "economie_qualite";
  if (metricDef.family === "affectations_dispersion") return "affectations_dispersion";
  return "activite";
}

function performanceRowsForPeriod(period = "") {
  const rows = [];
  state.performance_imports.forEach(item => {
    ensureArray(item.indicators).forEach(row => {
      if (String(row.period || "") !== String(period || "")) return;
      rows.push(row);
    });
  });
  return rows;
}

function performanceMatchesMetricDef(row = {}, metricDef = {}) {
  const rowPath = String(row.destinationPath || "").trim();
  const rowMetricKey = String(row.metricKey || "").trim().toLowerCase();
  const rowLabel = normalizePerformanceLabel(row.indicator || row.label || row.destinationLabel || "");
  const aliases = [metricDef.label, ...(metricDef.aliases || [])].map(normalizePerformanceLabel).filter(Boolean);
  if (metricDef.targetPath && rowPath && (rowPath === metricDef.targetPath || `${rowPath}.actual` === metricDef.targetPath)) return true;
  if (metricDef.metricKey && rowMetricKey && rowMetricKey === String(metricDef.metricKey).toLowerCase()) return true;
  // V5.28P : les alias très courts (ex. « AT ») ne doivent jamais matcher
  // par simple sous-chaîne (« préparation » contient les lettres « at »).
  return aliases.some(alias => {
    if (!alias) return false;
    if (rowLabel === alias) return true;
    if (alias.length <= 3) {
      const tokens = rowLabel.split(/[^a-z0-9à-ÿ]+/i).filter(Boolean);
      return tokens.includes(alias);
    }
    return rowLabel.includes(alias);
  });
}

function performancePrimaryValueForMetric(periodRecord, metricDef) {
  if (!periodRecord || !metricDef.metricPath) return null;
  const metric = perfPath(periodRecord, metricDef.metricPath);
  if (!metric) return null;
  const valueField = metricDef.valueField || "actual";
  const value = metric[valueField];
  if (!perfHas(value)) return null;
  return {
    value,
    budget: perfHas(metric.budget) ? metric.budget : "",
    historical: perfHas(metric.historical) ? metric.historical : "",
    unit: metricDef.unit || "",
    source: "DEOS",
    sourceLabel: "Saisie DEOS",
    confidence: "moyenne",
    sourceRef: metric.comment || "",
    periodType: "monthly"
  };
}

function performanceCandidateWarnings(candidate, metricDef) {
  const warnings = [];
  if (!perfHas(candidate?.value)) warnings.push("Donnée manquante");
  const sourceKey = candidate?.source || "";
  const priorityKey = performanceMetricFamilyPriorityKey(metricDef);
  const priority = performanceSourcePriorityByFamily[priorityKey] || [];
  if (priority.length && sourceKey && !priority.includes(sourceKey)) warnings.push("Source secondaire");
  if ((priorityKey === "ipo" || priorityKey === "productivites_officielles") && sourceKey === "Z_GEMED") warnings.push("Ancienne donnée non prioritaire");
  if (sourceKey === "CGTAB" || sourceKey === "GA_DETAIL_AGGREGATED") warnings.push("Confidentialité agrégée");
  if (performanceIsValueSuspect({ value: candidate?.value, unit: candidate?.unit || metricDef.unit || "" })) warnings.push("Valeur suspecte");
  const expected = performanceNormalizedUnit(metricDef.unit || "");
  const actual = performanceNormalizedUnit(candidate?.unit || "");
  if (expected && actual && expected !== actual) warnings.push("Unité à vérifier");
  if (!perfHas(candidate?.historical)) warnings.push("Historique insuffisant");
  return [...new Set(warnings)];
}

function performanceMetricCandidates(metricDef, period, periodRecord, importRows) {
  const candidates = [];
  importRows.filter(row => performanceMatchesMetricDef(row, metricDef)).forEach(row => {
    const value = row.actual ?? row.value;
    candidates.push({
      value,
      budget: row.budget ?? "",
      historical: row.historical ?? "",
      unit: row.unit || metricDef.unit || "",
      source: performanceSourceKey(row.source || row.sourceType || "Import"),
      sourceLabel: performanceSourceLabel(performanceSourceKey(row.source || row.sourceType || "Import")),
      confidence: row.confidence || "moyenne",
      sourceRef: row.sourceRef || row.sourceCell || "",
      periodType: row.periodType || "monthly"
    });
  });
  const primary = performancePrimaryValueForMetric(periodRecord, metricDef);
  if (primary) candidates.push(primary);
  const unique = [];
  const seen = new Set();
  candidates.forEach(candidate => {
    const key = `${candidate.source}|${candidate.value}|${candidate.budget}|${candidate.historical}|${candidate.unit}`;
    if (seen.has(key)) return;
    seen.add(key);
    unique.push(candidate);
  });
  return unique;
}

function getPreferredPerformanceValue(metricKey, period) {
  const metricDef = performanceSummaryMetricDefinitions.find(def => def.metricKey === metricKey);
  if (!metricDef) {
    return {
      value: "",
      budget: "",
      historical: "",
      unit: "",
      source: "",
      sourceLabel: "Source inconnue",
      confidence: "faible",
      alternatives: [],
      warnings: ["Donnée manquante"]
    };
  }
  const periodRecord = getPerformanceByPeriod(period);
  const importRows = performanceRowsForPeriod(period);
  const candidates = performanceMetricCandidates(metricDef, period, periodRecord, importRows);
  const priorityKey = performanceMetricFamilyPriorityKey(metricDef);
  const priority = performanceSourcePriorityByFamily[priorityKey] || [];
  let selected = null;
  for (const sourceKey of priority) {
    selected = candidates.find(candidate => candidate.source === sourceKey && perfHas(candidate.value));
    if (selected) break;
  }
  if (!selected && !priority.length) selected = candidates.find(candidate => perfHas(candidate.value)) || null;
  const requiresOfficial = priorityKey === "ipo" || priorityKey === "productivites_officielles";
  if (!selected && !requiresOfficial) selected = candidates.find(candidate => perfHas(candidate.value)) || null;
  if (!selected) {
    const alternatives = candidates.map(candidate => ({ ...candidate, warnings: performanceCandidateWarnings(candidate, metricDef) }));
    return {
      value: "",
      budget: "",
      historical: "",
      unit: metricDef.unit || "",
      source: priority[0] || "",
      sourceLabel: priority[0] === "GPO" ? "Donnée GPO non disponible" : "Donnée non disponible",
      confidence: "faible",
      alternatives,
      warnings: [...new Set(["Donnée manquante", ...(requiresOfficial ? ["Donnée GPO non disponible"] : [])])]
    };
  }
  const alternatives = candidates
    .filter(candidate => candidate !== selected)
    .map(candidate => ({ ...candidate, warnings: performanceCandidateWarnings(candidate, metricDef) }));
  const priorityIndex = priority.indexOf(selected.source);
  const confidence = priorityIndex === 0 ? "élevée" : priorityIndex > 0 ? "moyenne" : "faible";
  const warnings = [...new Set([...performanceCandidateWarnings(selected, metricDef), ...(alternatives.length ? ["Sources différentes"] : [])])];
  return {
    value: selected.value,
    budget: selected.budget,
    historical: selected.historical,
    unit: selected.unit || metricDef.unit || "",
    source: selected.source,
    sourceLabel: selected.sourceLabel,
    confidence,
    alternatives,
    warnings
  };
}

function performanceSummaryMetricStatus(metricKey, period, preferredValue) {
  if (!perfHas(preferredValue.value)) {
    return { label: "Donnée manquante", tone: "missing", badges: preferredValue.warnings || ["Donnée manquante"] };
  }
  const pseudoRecord = {
    kpiId: metricKey,
    category: metricKey.startsWith("ipo.") ? "IPO" : "",
    value: preferredValue.value,
    objective: preferredValue.budget,
    unit: preferredValue.unit,
    targetPath: "",
    label: metricKey,
    qualityFlags: []
  };
  const objective = performanceObjectiveDefinition(pseudoRecord);
  if (!objective.configured) {
    return { label: "Non évalué", tone: "none", badges: [...new Set(["Seuil à définir", ...(preferredValue.warnings || [])])] };
  }
  const status = performanceStatus(pseudoRecord);
  if (status.tone === "red") return { label: "Critique", tone: "critical", badges: preferredValue.warnings || [] };
  if (status.tone === "orange") return { label: "Vigilance", tone: "warning", badges: preferredValue.warnings || [] };
  if (status.tone === "green") return { label: "Conforme", tone: "ok", badges: preferredValue.warnings || [] };
  return { label: "Non évalué", tone: "none", badges: preferredValue.warnings || [] };
}

function performanceSummaryFormatValue(value, unit, metricKey = "") {
  if (!perfHas(value)) return "Donnée non disponible";
  const numeric = Number(value);
  if (!Number.isFinite(numeric)) return String(value);
  const normalizedUnit = String(unit || "").toLowerCase();
  if (normalizedUnit === "%" || normalizedUnit === "pourcentage") {
    const ratioValue = numeric >= 0 && numeric <= 1 ? numeric * 100 : numeric;
    return `${ratioValue.toLocaleString("fr-FR", { minimumFractionDigits: 0, maximumFractionDigits: 2 })} %`;
  }
  const digits = /hours|heures|\bh\b/.test(normalizedUnit) ? 2 : (metricKey.startsWith("ipo.") ? 2 : 1);
  const formatted = numeric.toLocaleString("fr-FR", { minimumFractionDigits: 0, maximumFractionDigits: digits });
  return unit ? `${formatted} ${unit}` : formatted;
}

// V5.28Q : un écart entre deux pourcentages est exprimé en points de pourcentage.
// Il ne faut pas retransformer 0,8 point en 80 %.
function performanceSummaryFormatDelta(value, unit, metricKey = "") {
  if (!perfHas(value)) return "Donnée non disponible";
  const numeric = Number(value);
  if (!Number.isFinite(numeric)) return String(value);
  const normalizedUnit = String(unit || "").toLowerCase();
  if (normalizedUnit === "%" || normalizedUnit === "pourcentage") {
    return `${numeric.toLocaleString("fr-FR", { minimumFractionDigits: 0, maximumFractionDigits: 2 })} pt`;
  }
  return performanceSummaryFormatValue(value, unit, metricKey);
}

function performanceSummaryBuildRows(period) {
  return performanceSummaryMetricDefinitions.map(def => {
    const preferred = getPreferredPerformanceValue(def.metricKey, period);
    const status = performanceSummaryMetricStatus(def.metricKey, period, preferred);
    const value = perfHas(preferred.value) ? Number(preferred.value) : "";
    const budget = perfHas(preferred.budget) ? Number(preferred.budget) : "";
    const historical = perfHas(preferred.historical) ? Number(preferred.historical) : "";
    const gap = (Number.isFinite(value) && Number.isFinite(budget)) ? value - budget : "";
    const trend = (Number.isFinite(value) && Number.isFinite(historical)) ? value - historical : "";
    return {
      metricKey: def.metricKey,
      label: def.label,
      family: def.family,
      unit: preferred.unit || def.unit || "",
      value,
      budget,
      historical,
      gap,
      trend,
      source: preferred.source,
      sourceLabel: preferred.sourceLabel,
      confidence: preferred.confidence,
      alternatives: preferred.alternatives,
      warnings: status.badges,
      statusLabel: status.label,
      statusTone: status.tone
    };
  });
}

function performancePrimaryTargetOptions() {
  return performanceImportTargetCatalog.filter(entry => entry.type === "existing");
}

function performanceOptionList(values) {
  return [...new Set(values.filter(Boolean))].sort((a, b) => String(a).localeCompare(String(b), "fr", { sensitivity: "base" }));
}

function performanceNormalizedUnit(value) {
  return normalizePerformanceLabel(String(value || "")).replace(/\s+/g, "");
}

function performanceSourceMatchesComment(comment, labels) {
  const target = String(comment || "").split("->")[1] || "";
  const normalizedTarget = normalizePerformanceLabel(target);
  return labels.some(label => {
    const normalizedLabel = normalizePerformanceLabel(label);
    return normalizedLabel && (normalizedTarget === normalizedLabel || normalizedTarget.includes(normalizedLabel) || normalizedLabel.includes(normalizedTarget));
  });
}

function performanceMatchingImportRows(record) {
  const labels = [record.label, record.sourceLabel, ...(record.destinationLabels || [])].filter(Boolean).map(normalizePerformanceLabel);
  return state.performance_imports.flatMap(item => ensureArray(item.indicators).filter(row => {
    const rowPeriod = String(row.period || item.period || "").trim();
    if (String(record.period || "") !== rowPeriod) return false;
    if (record.scope === "principal") {
      if (record.targetPath && String(row.destinationPath || "") === String(record.targetPath || "")) return true;
      const rowTarget = normalizePerformanceLabel(row.destinationLabel || "");
      return labels.some(label => label && rowTarget === label);
    }
    const rowIndicator = normalizePerformanceLabel(row.indicator || "");
    return rowIndicator === normalizePerformanceLabel(record.sourceLabel || record.label || "") || String(row.targetId || row.destinationId || "") === String(record.targetId || "");
  }).map(row => ({
    source: row.source || item.sourceType || item.sourceFile || "Import",
    value: row.value,
    unit: row.unit || "",
    sourceFile: item.sourceFile || "",
    importDate: item.importDate || "",
    row
  })));
}

function performanceRecordSource(period, targetPath, labels) {
  const imported = performanceMatchingImportRows({ period, targetPath, label: labels?.[0] || "", sourceLabel: labels?.[0] || "", destinationLabels: ensureArray(labels), scope: "principal" });
  const importedSources = performanceOptionList(imported.map(item => item.source));
  if (importedSources.length) return importedSources.join(" · ");
  const perf = getPerformanceByPeriod(period);
  const legacySources = ensureArray(perf?.importSources).filter(source => {
    if (String(source.period || "") !== String(period || "")) return false;
    return performanceSourceMatchesComment(source.comment, ensureArray(labels));
  }).map(source => source.source || source.file || "Import");
  return performanceOptionList(legacySources).join(" · ") || "Saisie / DEOS";
}

function performanceBuildPrimaryRecords() {
  const periods = state.performance.slice().sort((a, b) => a.year - b.year || a.month - b.month);
  return periods.flatMap(perf => performancePrimaryKpiCatalog.map(def => {
    const metric = perfPath(perf, def.metricPath);
    const value = metric?.[def.valueField || "actual"];
    if (!perfHas(value)) return null;
    const period = performancePeriodKey(perf);
    return {
      scope: "principal",
      kpiId: def.id,
      label: def.label,
      sourceLabel: def.label,
      destinationLabels: def.destinationLabels || [def.label],
      category: def.category,
      period,
      periodTitle: performancePeriodTitle(period),
      periodSort: performancePeriodSortValue(period),
      value,
      unit: def.unit || "",
      expectedUnit: def.unit || "",
      objective: perfHas(metric?.[def.objectiveField || "budget"]) ? metric[def.objectiveField || "budget"] : "",
      source: performanceRecordSource(period, def.targetPath, def.destinationLabels || [def.label]),
      targetPath: def.targetPath,
      metricPath: def.metricPath,
      targetId: def.id,
      targetType: "existing",
      sourceRef: "",
      qualityFlags: []
    };
  }).filter(Boolean));
}

function performanceBuildComplementaryRecords() {
  const periods = state.performance.slice().sort((a, b) => a.year - b.year || a.month - b.month);
  return periods.flatMap(perf => ensureArray(perf.complementaryKpis).map(row => {
    const period = row.period || performancePeriodKey(perf);
    const label = String(row.indicator || row.destinationLabel || "KPI complémentaire").trim();
    return {
      scope: "complementary",
      kpiId: row.targetId && row.targetId !== "complementary.generic" ? row.targetId : performanceKpiIdFromLabel(label, "complementary"),
      label,
      sourceLabel: label,
      destinationLabels: [row.destinationLabel || "KPI complémentaire", label],
      category: row.category || "KPI complémentaires",
      period,
      periodType: row.periodType || "monthly",
      periodTitle: performancePeriodTitle(period),
      periodSort: performancePeriodSortValue(period),
      value: row.actual ?? row.value,
      unit: row.unit || "",
      expectedUnit: row.unit || "",
      objective: "",
      source: row.source || "Import",
      targetPath: String(row.destinationPath || row.targetId || ""),
      metricPath: row.metricKey || "",
      targetId: row.targetId || "complementary.generic",
      targetType: "complementary",
      sourceRef: row.sourceRef || row.sourceCell || "",
      qualityFlags: []
    };
  }));
}

function performanceIsValueSuspect(record) {
  const num = Number(record.value);
  if (!Number.isFinite(num)) return true;
  const unit = String(record.unit || "").toLowerCase();
  if (unit === "%" && (num < -100 || num > 100)) return true;
  if (/(colis|u\.)/.test(unit) && num < 0) return true;
  if (/\bh\b/.test(unit) && num < 0) return true;
  if (Math.abs(num) > 100000000) return true;
  return false;
}

function performanceAnnotateRecords(records) {
  const groupedByPeriod = new Map();
  const unitsByKpi = new Map();
  records.forEach(record => {
    const key = `${record.scope}|${record.kpiId}|${record.period}`;
    const current = groupedByPeriod.get(key) || [];
    current.push(record);
    groupedByPeriod.set(key, current);
    const unitKey = record.kpiId;
    const units = unitsByKpi.get(unitKey) || new Set();
    if (record.unit) units.add(record.unit);
    unitsByKpi.set(unitKey, units);
  });
  return records.map(record => {
    const flags = [...ensureArray(record.qualityFlags)];
    if (!record.period) flags.push("Période absente");
    if (!record.unit) flags.push("Unité absente");
    if (performanceIsValueSuspect(record)) flags.push("Valeur suspecte");
    if (record.expectedUnit && record.scope === "principal") {
      const importedUnits = performanceOptionList(performanceMatchingImportRows(record).map(item => item.unit).filter(Boolean));
      if (importedUnits.length && importedUnits.some(unit => performanceNormalizedUnit(unit) !== performanceNormalizedUnit(record.expectedUnit))) flags.push("Unité à vérifier");
    }
    if (record.scope === "complementary" && (!record.targetId || record.targetId === "complementary.generic")) flags.push("KPI non mappé");
    const group = groupedByPeriod.get(`${record.scope}|${record.kpiId}|${record.period}`) || [];
    const importRows = performanceMatchingImportRows(record);
    const comparisonValues = [...group.map(item => item.value), ...importRows.map(item => item.value)].filter(v => perfHas(v)).map(v => Number(v));
    const distinctValues = [...new Set(comparisonValues.filter(Number.isFinite).map(v => v.toString()))];
    if (group.length > 1 || importRows.length > 1) flags.push("Doublon potentiel");
    if (distinctValues.length > 1) flags.push("Conflit entre deux valeurs");
    const units = unitsByKpi.get(record.kpiId) || new Set();
    if (units.size > 1) flags.push("Unité incompatible");
    const objectiveValue = perfHas(record.objective) ? Number(record.objective) : "";
    const recordValue = perfHas(record.value) ? Number(record.value) : "";
    const hasRule = performanceObjectiveDefinition(record).configured;
    if (record.category === "IPO" && perfHas(record.objective) && !hasRule) {
      if ((Number.isFinite(recordValue) && Number.isFinite(objectiveValue) && recordValue < 0 && objectiveValue > 0) ||
          (Number.isFinite(recordValue) && Number.isFinite(objectiveValue) && Math.abs(objectiveValue) > 0 && (Math.abs(recordValue / objectiveValue) >= 10 || Math.abs(recordValue / objectiveValue) <= 0.1))) {
        flags.push("Valeur à vérifier");
      }
    }
    return { ...record, qualityFlags: [...new Set(flags)] };
  });
}

function performanceAllRecords() {
  return performanceAnnotateRecords([...performanceBuildPrimaryRecords(), ...performanceBuildComplementaryRecords()]);
}

function performanceFilterOptions(records) {
  return {
    periods: performanceOptionList(records.map(record => record.period)).sort((a, b) => performancePeriodSortValue(b) - performancePeriodSortValue(a)),
    kpis: performanceOptionList(records.map(record => record.label)),
    categories: performanceOptionList(records.map(record => record.category)),
    sources: performanceOptionList(records.map(record => record.source))
  };
}

function performanceApplyFilters(records) {
  return records.filter(record => {
    if (performanceDashboardFilters.period !== "all" && record.period !== performanceDashboardFilters.period) return false;
    if (performanceDashboardFilters.category !== "all" && record.category !== performanceDashboardFilters.category) return false;
    if (performanceDashboardFilters.source !== "all" && record.source !== performanceDashboardFilters.source) return false;
    if (performanceDashboardFilters.scope !== "all" && record.scope !== performanceDashboardFilters.scope) return false;
    if (performanceDashboardFilters.kpi !== "all" && record.label !== performanceDashboardFilters.kpi) return false;
    return true;
  });
}

function performanceLatestRecordByKpi(records) {
  const latest = new Map();
  records.forEach(record => {
    const current = latest.get(record.kpiId);
    if (!current || record.periodSort > current.periodSort) latest.set(record.kpiId, record);
  });
  return [...latest.values()].sort((a, b) => a.category.localeCompare(b.category, "fr", { sensitivity: "base" }) || a.label.localeCompare(b.label, "fr", { sensitivity: "base" }));
}

function performancePreviousRecord(records, record) {
  return records.filter(item => item.kpiId === record.kpiId && item.periodSort < record.periodSort && (!record.unit || !item.unit || item.unit === record.unit)).sort((a, b) => b.periodSort - a.periodSort)[0] || null;
}

function performanceFormatSignedValue(value, unit = "") {
  if (value === "" || value === null || value === undefined || Number.isNaN(Number(value))) return "À compléter";
  const num = Number(value);
  const prefix = num > 0 ? "+" : "";
  return `${prefix}${perfFmt(num)}${unit ? ` ${unit}` : ""}`;
}

function performanceDeltaUnit(record = {}) {
  if (isIpoMetricDescriptor({ metricKey: record.kpiId || record.metricKey, destinationPath: record.targetPath, label: record.label, category: record.category })) return "points";
  return record.unit || "";
}

function performanceHasObjective(record) {
  const definition = performanceObjectiveDefinition(record);
  return definition.mode === "range"
    ? perfHas(definition.min) || perfHas(definition.max)
    : perfHas(definition.objective);
}

function performanceGapIsReliable(record) {
  return !ensureArray(record.qualityFlags).includes("Valeur à vérifier");
}

function performanceObjectiveDefinition(record) {
  const config = performanceObjectiveStore()[record.kpiId] || {};
  const baseObjective = perfHas(config.objective) ? config.objective : record.objective;
  const baseMin = perfHas(config.min) ? config.min : "";
  const baseMax = perfHas(config.max) ? config.max : "";
  const mode = config.mode || "";
  const configured = Boolean(mode && ((mode === "range" && (perfHas(baseMin) || perfHas(baseMax))) || (mode !== "range" && perfHas(baseObjective))));
  return {
    mode,
    objective: perfHas(baseObjective) ? Number(baseObjective) : "",
    min: perfHas(baseMin) ? Number(baseMin) : "",
    max: perfHas(baseMax) ? Number(baseMax) : "",
    unit: config.unit || record.unit || "",
    vigilance: perfHas(config.vigilance) ? Number(config.vigilance) : "",
    critical: perfHas(config.critical) ? Number(config.critical) : "",
    configured
  };
}

function performanceObjectiveGap(record) {
  const definition = performanceObjectiveDefinition(record);
  if (definition.mode === "range") {
    if (definition.min === "" && definition.max === "") return "";
    const value = Number(record.value);
    if (!Number.isFinite(value)) return "";
    if (definition.min !== "" && value < definition.min) return value - definition.min;
    if (definition.max !== "" && value > definition.max) return value - definition.max;
    return 0;
  }
  if (!perfHas(definition.objective) || !perfHas(record.value)) return "";
  return Number(record.value) - Number(definition.objective);
}

function performanceStatus(record) {
  const definition = performanceObjectiveDefinition(record);
  if (!perfHas(record.value)) return { key: "not_configured", label: "Non configuré", tone: "slate" };
  if (!definition.configured && performanceHasObjective(record)) return { key: "thresholds_pending", label: "Seuils à configurer", tone: "orange" };
  if (!definition.configured) return { key: "not_configured", label: "Non configuré", tone: "slate" };
  const value = Number(record.value);
  if (!Number.isFinite(value)) return { key: "not_configured", label: "Non configuré", tone: "slate" };
  if (definition.mode === "higher") {
    if (definition.critical !== "" && value < definition.critical) return { key: "critical", label: "Critique", tone: "red" };
    if (definition.vigilance !== "" && value < definition.vigilance) return { key: "follow", label: "À suivre", tone: "orange" };
    if (definition.objective !== "" && value >= definition.objective) return { key: "controlled", label: "Maîtrisé", tone: "green" };
    return { key: "follow", label: "À suivre", tone: "orange" };
  }
  if (definition.mode === "lower") {
    if (definition.critical !== "" && value > definition.critical) return { key: "critical", label: "Critique", tone: "red" };
    if (definition.vigilance !== "" && value > definition.vigilance) return { key: "follow", label: "À suivre", tone: "orange" };
    if (definition.objective !== "" && value <= definition.objective) return { key: "controlled", label: "Maîtrisé", tone: "green" };
    return { key: "follow", label: "À suivre", tone: "orange" };
  }
  if (definition.mode === "target") {
    const gap = Math.abs(performanceObjectiveGap(record));
    if (definition.critical !== "" && gap > definition.critical) return { key: "critical", label: "Critique", tone: "red" };
    if (definition.vigilance !== "" && gap > definition.vigilance) return { key: "follow", label: "À suivre", tone: "orange" };
    if (gap === 0) return { key: "controlled", label: "Maîtrisé", tone: "green" };
    return { key: "follow", label: "À suivre", tone: "orange" };
  }
  if (definition.mode === "range") {
    const insideMin = definition.min === "" || value >= definition.min;
    const insideMax = definition.max === "" || value <= definition.max;
    if (insideMin && insideMax) return { key: "controlled", label: "Maîtrisé", tone: "green" };
    const gap = Math.abs(performanceObjectiveGap(record));
    if (definition.critical !== "" && gap > definition.critical) return { key: "critical", label: "Critique", tone: "red" };
    return { key: "follow", label: "À suivre", tone: "orange" };
  }
  return { key: "not_configured", label: "Non configuré", tone: "slate" };
}

function performanceStatusBadge(record) {
  const status = performanceStatus(record);
  return `<span class="performance-status performance-status-${status.tone}">${esc(status.label)}</span>`;
}

function performanceFlagsBadges(flags) {
  if (!flags.length) return `<span class="muted">Aucun signal</span>`;
  return flags.map(flag => `<span class="performance-flag">${esc(flag)}</span>`).join("");
}

function performanceDashboardFilterBar(records) {
  const options = performanceFilterOptions(records);
  const families = Object.entries(performanceSummaryFamilyLabels);
  const kpiOptions = performanceSummaryMetricDefinitions.map(def => ({ key: def.metricKey, label: def.label }));
  const sourceKeys = ["all", "GPO", "Z_GEMED", "SUIVI_GA", "CGTAB", "T_BAG", "GA_DETAIL_AGGREGATED", "DEOS"];
  const periodOptions = options.periods
    .map(period => `<option value="${esc(period)}" ${performanceDashboardFilters.period === period ? "selected" : ""}>${esc(performancePeriodTitle(period))}</option>`)
    .join("");
  const familyOptions = families
    .map(([key, label]) => `<option value="${esc(key)}" ${performanceDashboardFilters.family === key ? "selected" : ""}>${esc(label)}</option>`)
    .join("");
  const kpiSelectOptions = kpiOptions
    .map(kpi => `<option value="${esc(kpi.key)}" ${performanceDashboardFilters.kpi === kpi.key ? "selected" : ""}>${esc(kpi.label)}</option>`)
    .join("");
  const sourceOptions = sourceKeys
    .map(key => `<option value="${esc(key)}" ${performanceDashboardFilters.source === key ? "selected" : ""}>${esc(key === "all" ? "Source : toutes" : performanceSourceLabel(key))}</option>`)
    .join("");
  return `
    <div class="performance-filter-wrap">
      <div class="performance-filter-row">
        <select class="performance-filter-control" onchange="setPerformanceDashboardFilter('period', this.value)">
          <option value="all">Période : toutes</option>${periodOptions}
        </select>
        <select class="performance-filter-control" onchange="setPerformanceDashboardFilter('family', this.value)">
          <option value="all">Famille : toutes</option>${familyOptions}
        </select>
        <select class="performance-filter-control" onchange="setPerformanceDashboardFilter('kpi', this.value)">
          <option value="all">KPI : tous</option>${kpiSelectOptions}
        </select>
        <select class="performance-filter-control" onchange="setPerformanceDashboardFilter('source', this.value)">${sourceOptions}</select>
        <select class="performance-filter-control" onchange="setPerformanceDashboardFilter('view', this.value)">
          <option value="all" ${performanceDashboardFilters.view === "all" ? "selected" : ""}>Vue : complète</option>
          <option value="direction" ${performanceDashboardFilters.view === "direction" ? "selected" : ""}>Vue : direction</option>
        </select>
        <label class="performance-filter-anomaly">
          <input type="checkbox" ${performanceDashboardFilters.anomalies === "on" ? "checked" : ""} onchange="setPerformanceDashboardFilter('anomalies', this.checked ? 'on' : 'off')">
          Anomalies uniquement
        </label>
        <button class="secondary" onclick="resetPerformanceDashboardFilters()">Réinitialiser les filtres</button>
      </div>
    </div>
  `;
}

function performanceSummaryRowsFiltered(period) {
  const allRows = performanceSummaryBuildRows(period);
  return allRows.filter(row => {
    if (performanceDashboardFilters.family !== "all" && row.family !== performanceDashboardFilters.family) return false;
    if (performanceDashboardFilters.kpi !== "all" && row.metricKey !== performanceDashboardFilters.kpi) return false;
    if (performanceDashboardFilters.source !== "all" && row.source !== performanceDashboardFilters.source) return false;
    if (performanceDashboardFilters.anomalies === "on" && !ensureArray(row.warnings).length) return false;
    return true;
  });
}

function performanceStatusBadgeV519(row) {
  return `<span class="performance-kpi-status performance-kpi-status-${esc(row.statusTone)}">${esc(row.statusLabel)}</span>`;
}

function performanceWarningsBadgesV519(row) {
  const badges = ensureArray(row.warnings);
  if (!badges.length) return `<span class="performance-badge performance-badge-ok">Aucune alerte</span>`;
  return badges.map(flag => `<span class="performance-badge">${esc(flag)}</span>`).join("");
}

function performanceDirectionCards(period) {
  const cardOrder = ["ipo.total", "activity.colis_total", "productivity.preparation", "hours.indirect", "absenteeism.total", "economy.cout_total_par_colis"];
  const rows = performanceSummaryRowsFiltered(period).filter(row => cardOrder.includes(row.metricKey));
  const ordered = cardOrder.map(key => rows.find(row => row.metricKey === key)).filter(Boolean).slice(0, 6);
  if (!ordered.length) return `<div class="empty">Aucune carte Direction disponible avec les filtres en cours.</div>`;
  const cards = ordered.map(row => `
    <article class="performance-summary-direction-card">
      <header>
        <h3>${esc(row.label)}</h3>
        ${performanceStatusBadgeV519(row)}
      </header>
      <div class="performance-summary-direction-value">${esc(performanceSummaryFormatValue(row.value, row.unit, row.metricKey))}</div>
      <div class="performance-summary-direction-meta">Source : ${esc(row.sourceLabel || performanceSourceLabel(row.source))}</div>
      <div class="performance-summary-direction-lines">
        <div>Objectif/Budget : ${esc(performanceSummaryFormatValue(row.budget, row.unit, row.metricKey))}</div>
        <div>Écart : ${esc(performanceSummaryFormatDelta(row.gap, row.unit, row.metricKey))}</div>
        <div>Tendance : ${esc(performanceSummaryFormatDelta(row.trend, row.unit, row.metricKey))}</div>
      </div>
      <div class="performance-summary-direction-badges">${performanceWarningsBadgesV519(row)}</div>
      <button class="secondary" onclick="openPerformanceSummaryDetail('${esc(row.metricKey)}')">Voir le détail</button>
    </article>
  `).join("");
  return `<div class="performance-summary-direction-grid">${cards}</div>`;
}

function performanceSummaryCards(records) {
  const period = performanceDashboardFilters.period !== "all"
    ? performanceDashboardFilters.period
    : (records.slice().sort((a, b) => performancePeriodSortValue(b.period) - performancePeriodSortValue(a.period))[0]?.period || performancePeriodKey(perfSelected() || {}));
  return performanceDirectionCards(period);
}

function resetPerformanceDashboardFilters() {
  performanceDashboardFilters.period = "all";
  performanceDashboardFilters.family = "all";
  performanceDashboardFilters.kpi = "all";
  performanceDashboardFilters.source = "all";
  performanceDashboardFilters.view = "all";
  performanceDashboardFilters.anomalies = "off";
  renderPerformance();
}

function performanceResolveSelectedKpi(records) {
  const explicit = performanceDashboardFilters.kpi !== "all" ? records.find(record => record.label === performanceDashboardFilters.kpi) : null;
  if (explicit) {
    performanceDashboardSelectedKpi = explicit.kpiId;
    return explicit.kpiId;
  }
  if (records.some(record => record.kpiId === performanceDashboardSelectedKpi)) return performanceDashboardSelectedKpi;
  performanceDashboardSelectedKpi = records[0]?.kpiId || "";
  return performanceDashboardSelectedKpi;
}

function performanceCompatibleSeries(records) {
  const units = performanceOptionList(records.map(record => record.unit));
  if (units.length <= 1) return { unit: units[0] || "", records, warning: "" };
  const latestUnit = records.slice().sort((a, b) => b.periodSort - a.periodSort).find(record => record.unit)?.unit || units[0];
  return { unit: latestUnit, records: records.filter(record => record.unit === latestUnit), warning: `Unités incompatibles détectées (${units.join(", ")}). Courbe limitée à ${latestUnit || "l’unité principale"}.` };
}

function performanceTrendSvg(records) {
  if (!records.length) return `<div class="empty">Aucune donnée disponible pour ce KPI.</div>`;
  if (records.length === 1) return `<div class="performance-chart-single">Une seule donnée disponible : ${esc(records[0].periodTitle)} · ${esc(perfFmt(records[0].value))}${records[0].unit ? ` ${esc(records[0].unit)}` : ""}</div>`;
  const width = 720;
  const height = 260;
  const paddingX = 48;
  const paddingY = 24;
  const plotWidth = width - paddingX * 2;
  const plotHeight = height - 64;
  const objectiveValues = records.map(record => {
    const definition = performanceObjectiveDefinition(record);
    if (definition.mode === "range") return perfHas(definition.max) ? Number(definition.max) : (perfHas(definition.min) ? Number(definition.min) : null);
    return perfHas(definition.objective) ? Number(definition.objective) : null;
  }).filter(Number.isFinite);
  const values = [...records.map(record => Number(record.value)).filter(Number.isFinite), ...objectiveValues];
  const min = Math.min(...values);
  const max = Math.max(...values);
  const spread = max - min || Math.max(Math.abs(max), 1);
  const lower = min - spread * 0.12;
  const upper = max + spread * 0.12;
  const yFor = value => paddingY + ((upper - value) / (upper - lower || 1)) * plotHeight;
  const xFor = index => paddingX + (plotWidth * index) / Math.max(records.length - 1, 1);
  const valuePolyline = records.map((record, index) => `${xFor(index)},${yFor(Number(record.value))}`).join(" ");
  const objectivePolyline = records.map((record, index) => {
    const definition = performanceObjectiveDefinition(record);
    const currentObjective = definition.mode === "range"
      ? (perfHas(definition.max) ? Number(definition.max) : (perfHas(definition.min) ? Number(definition.min) : null))
      : (perfHas(definition.objective) ? Number(definition.objective) : null);
    return currentObjective === null ? null : `${xFor(index)},${yFor(currentObjective)}`;
  }).filter(Boolean).join(" ");
  const zeroLine = lower <= 0 && upper >= 0 ? yFor(0) : height - 40;
  return `<svg class="performance-trend-svg" viewBox="0 0 ${width} ${height}" role="img" aria-label="Évolution du KPI"><line x1="${paddingX}" y1="${zeroLine}" x2="${width - paddingX}" y2="${zeroLine}" class="performance-axis"></line><polyline fill="none" class="performance-line" points="${valuePolyline}"></polyline>${objectivePolyline ? `<polyline fill="none" class="performance-line performance-line-objective" points="${objectivePolyline}"></polyline>` : ""}${records.map((record, index) => `<g><circle cx="${xFor(index)}" cy="${yFor(Number(record.value))}" r="4" class="performance-point"></circle><text x="${xFor(index)}" y="${height - 18}" text-anchor="middle" class="performance-label">${esc(record.periodTitle)}</text></g>`).join("")}</svg>`;
}

function performanceObjectiveForm(record) {
  if (!record) return `<div class="empty">Aucun KPI sélectionné.</div>`;
  const objective = performanceObjectiveDefinition(record);
  return `<div class="performance-objective-card"><h3>Objectif et seuils</h3><input id="perfObjectiveKpiId" type="hidden" value="${esc(record.kpiId)}"><div class="form-grid"><select id="perfObjectiveMode"><option value="" ${!objective.mode ? "selected" : ""}>Aucun statut configuré</option><option value="higher" ${objective.mode === "higher" ? "selected" : ""}>Plus haut est meilleur</option><option value="lower" ${objective.mode === "lower" ? "selected" : ""}>Plus bas est meilleur</option><option value="target" ${objective.mode === "target" ? "selected" : ""}>Cible exacte</option><option value="range" ${objective.mode === "range" ? "selected" : ""}>Plage cible</option></select><input id="perfObjectiveValue" value="${perfHas(objective.objective) ? esc(objective.objective) : ""}" placeholder="Objectif"><input id="perfObjectiveMin" value="${perfHas(objective.min) ? esc(objective.min) : ""}" placeholder="Min plage"><input id="perfObjectiveMax" value="${perfHas(objective.max) ? esc(objective.max) : ""}" placeholder="Max plage"><input id="perfObjectiveUnit" value="${esc(objective.unit || record.unit || "")}" placeholder="Unité"><input id="perfObjectiveVigilance" value="${perfHas(objective.vigilance) ? esc(objective.vigilance) : ""}" placeholder="Seuil vigilance"><input id="perfObjectiveCritical" value="${perfHas(objective.critical) ? esc(objective.critical) : ""}" placeholder="Seuil critique"></div><div class="row-actions"><button class="action" onclick="savePerformanceDashboardObjective()">Enregistrer</button><button class="secondary" onclick="resetPerformanceDashboardObjective()">Réinitialiser</button></div></div>`;
}

function performanceAnalysisPanel(records) {
  const filtered = performanceApplyFilters(records);
  const selectedKpiId = performanceResolveSelectedKpi(filtered);
  const selectableKpis = performanceLatestRecordByKpi(filtered);
  const series = filtered.filter(record => record.kpiId === selectedKpiId).sort((a, b) => a.periodSort - b.periodSort);
  const compatible = performanceCompatibleSeries(series);
  const current = series.slice().sort((a, b) => b.periodSort - a.periodSort)[0] || null;
  return `<div class="performance-analysis-shell"><div class="performance-analysis-toolbar"><select onchange="setPerformanceAnalysisKpi(this.value)">${selectableKpis.map(record => `<option value="${esc(record.kpiId)}" ${record.kpiId === selectedKpiId ? "selected" : ""}>${esc(record.label)}</option>`).join("")}</select><span class="muted">${current ? `${esc(current.label)} · ${esc(current.category)}` : "Aucun KPI sélectionné"}</span></div><div class="performance-analysis-grid"><div class="performance-analysis-panel"><h3>Courbe d'évolution</h3>${compatible.warning ? `<p class="muted">${esc(compatible.warning)}</p>` : ""}${current ? performanceTrendSvg(compatible.records) : `<div class="empty">Aucune donnée disponible.</div>`}</div><div class="performance-analysis-panel"><h3>Configuration</h3>${performanceObjectiveForm(current)}</div></div><div class="performance-analysis-panel"><h3>Historique du KPI</h3><div class="performance-history-table"><table class="perf-table"><thead><tr><th>Période</th><th>Valeur</th><th>Objectif</th><th>Écart</th><th>Source</th><th>Qualité</th></tr></thead><tbody>${series.length ? series.map(record => {
    const objective = performanceObjectiveDefinition(record);
    const objectiveLabel = objective.mode === "range"
      ? `${perfHas(objective.min) ? perfFmt(objective.min) : "-"} / ${perfHas(objective.max) ? perfFmt(objective.max) : "-"}${objective.unit ? ` ${objective.unit}` : ""}`
      : (perfHas(objective.objective) ? `${perfFmt(objective.objective)}${objective.unit ? ` ${objective.unit}` : ""}` : "À compléter");
    const gap = performanceObjectiveGap(record);
    return `<tr><td>${esc(record.periodTitle)}</td><td>${esc(perfFmt(record.value))}${record.unit ? ` ${esc(record.unit)}` : ""}</td><td>${esc(objectiveLabel)}</td><td>${gap === "" ? "À compléter" : !performanceGapIsReliable(record) ? "À vérifier" : esc(performanceFormatSignedValue(gap, objective.unit || performanceDeltaUnit(record)))}</td><td>${esc(record.source || "Saisie / DEOS")}</td><td>${performanceFlagsBadges(record.qualityFlags)}</td></tr>`;
  }).join("") : `<tr><td colspan="6">Aucune donnée disponible.</td></tr>`}</tbody></table></div></div></div>`;
}

function performanceComplementarySection(records) {
  const filtered = performanceApplyFilters(records);
  const complementary = filtered.filter(record => record.scope === "complementary");
  const latestComplementary = performanceLatestRecordByKpi(complementary);
  return `<div class="card full-span"><div class="row"><div><h2>KPI complémentaires</h2><p class="muted">Restitution dédiée des KPI hors catalogue principal. Le remappage ci-dessous prépare les prochains imports sans réécrire l'historique.</p></div><div class="row-actions"><button class="secondary" onclick="togglePerformanceComplementarySection()">${performanceComplementaryExpanded ? "Masquer" : "Afficher"}</button></div></div>${performanceComplementaryExpanded ? `<div class="performance-history-table"><table class="perf-table"><thead><tr><th>Libellé source</th><th>Dernière valeur</th><th>Période</th><th>Historique</th><th>Source</th><th>Remappage futur</th><th>Qualité</th></tr></thead><tbody>${latestComplementary.length ? latestComplementary.map(record => {
    const historyCount = complementary.filter(item => item.kpiId === record.kpiId).length;
    const suggested = performanceImportMappingForLabel(record.sourceLabel);
    const options = [{ id: "complementary.generic", label: "KPI complémentaire" }, ...performancePrimaryTargetOptions()].map(option => `<option value="${esc(option.id)}" ${(suggested?.id || record.targetId || "complementary.generic") === option.id ? "selected" : ""}>${esc(option.label)}</option>`).join("");
    return `<tr><td>${esc(record.sourceLabel)}</td><td>${esc(perfFmt(record.value))}${record.unit ? ` ${esc(record.unit)}` : ""}</td><td>${esc(record.periodTitle)}</td><td>${historyCount} période(s)</td><td>${esc(record.source || "Import")}</td><td><select onchange="setComplementaryKpiMapping(this.dataset.label, this.value)" data-label="${esc(record.sourceLabel)}">${options}</select></td><td>${performanceFlagsBadges(record.qualityFlags)}</td></tr>`;
  }).join("") : `<tr><td colspan="7">Aucun KPI complémentaire avec les filtres en cours.</td></tr>`}</tbody></table></div>` : `<div class="muted">${latestComplementary.length} KPI complémentaire(s) disponible(s).</div>`}</div>`;
}

function performanceLatestImportMeta(period) {
  const selected = state.performance_imports
    .filter(item => importMatchesPeriod(item, period))
    .sort((a, b) => String(b.importDate || "").localeCompare(String(a.importDate || "")))[0] || null;
  if (!selected) return { source: "Aucune", date: "Non disponible" };
  return { source: performanceImportSourceLabel(selected), date: selected.importDate || "Non disponible" };
}

function performanceSummaryRowsForPeriod(period) {
  const rows = performanceSummaryRowsFiltered(period);
  if (performanceDashboardFilters.view === "direction") {
    const directionSet = new Set(["ipo.total", "activity.colis_total", "productivity.preparation", "hours.indirect", "absenteeism.total", "economy.cout_total_par_colis"]);
    return rows.filter(row => directionSet.has(row.metricKey));
  }
  return rows;
}

function performanceSummarySectionTable(period, familyKey, rows) {
  const familyRows = rows.filter(row => row.family === familyKey);
  const collapsed = Boolean(performanceSectionCollapsed[familyKey]);
  const header = `
    <header class="performance-summary-family-header">
      <h3>${esc(performanceSummaryFamilyLabels[familyKey])}</h3>
      <div class="row-actions">
        <span class="muted">${familyRows.length} KPI</span>
        <button class="secondary" onclick="togglePerformanceSummarySection('${esc(familyKey)}')">${collapsed ? "Déplier" : "Replier"}</button>
      </div>
    </header>
  `;
  if (collapsed) return `<section class="performance-summary-family">${header}</section>`;
  const bodyRows = familyRows.length
    ? familyRows.map(row => `
      <tr>
        <td>${esc(row.label)}</td>
        <td>${esc(performanceSummaryFormatValue(row.value, row.unit, row.metricKey))}</td>
        <td>${esc(performanceSummaryFormatValue(row.budget, row.unit, row.metricKey))}</td>
        <td>${esc(performanceSummaryFormatValue(row.historical, row.unit, row.metricKey))}</td>
        <td>${esc(performanceSummaryFormatDelta(row.gap, row.unit, row.metricKey))}</td>
        <td>${esc(performanceSummaryFormatDelta(row.trend, row.unit, row.metricKey))}</td>
        <td>${esc(row.sourceLabel || performanceSourceLabel(row.source))}</td>
        <td>${performanceStatusBadgeV519(row)}</td>
        <td>${performanceWarningsBadgesV519(row)}</td>
        <td><button class="secondary" onclick="openPerformanceSummaryDetail('${esc(row.metricKey)}')">Détail</button></td>
      </tr>
    `).join("")
    : `<tr><td colspan="10">Aucune donnée pour cette famille.</td></tr>`;
  return `
    <section class="performance-summary-family">
      ${header}
      <div class="performance-summary-table-wrap">
        <table class="performance-summary-table">
          <thead>
            <tr><th>KPI</th><th>Réel</th><th>Objectif</th><th>Historique</th><th>Écart</th><th>Tendance</th><th>Source</th><th>Statut</th><th>Alertes</th><th>Détail</th></tr>
          </thead>
          <tbody>${bodyRows}</tbody>
        </table>
      </div>
    </section>
  `;
}

function performanceSummaryDetailPanel(period, rows) {
  if (!performanceSummaryDetailMetricKey) return "";
  const row = rows.find(item => item.metricKey === performanceSummaryDetailMetricKey);
  if (!row) return "";
  const alternatives = row.alternatives.length
    ? row.alternatives.map(alt => `
      <div class="item">
        <strong>${esc(performanceSourceLabel(alt.source))}</strong>
        <span class="muted">${esc(performanceSummaryFormatValue(alt.value, alt.unit || row.unit, row.metricKey))}</span>
        <span class="meta">${esc((alt.warnings || []).join(" · ") || "Aucun signal")}</span>
      </div>
    `).join("")
    : `<div class="empty">Aucune alternative disponible.</div>`;
  return `
    <div class="performance-summary-detail-backdrop" onclick="closePerformanceSummaryDetail()">
      <div class="performance-summary-detail-panel" onclick="event.stopPropagation()">
        <div class="performance-summary-detail-head">
          <h3>Détail KPI · ${esc(row.label)}</h3>
          <button class="icon-close" onclick="closePerformanceSummaryDetail()">×</button>
        </div>
        <div class="performance-summary-detail-grid">
          <div><strong>Valeur principale</strong><p>${esc(performanceSummaryFormatValue(row.value, row.unit, row.metricKey))}</p></div>
          <div><strong>Source officielle</strong><p>${esc(row.sourceLabel || performanceSourceLabel(row.source))}</p></div>
          <div><strong>Budget</strong><p>${esc(performanceSummaryFormatValue(row.budget, row.unit, row.metricKey))}</p></div>
          <div><strong>Historique</strong><p>${esc(performanceSummaryFormatValue(row.historical, row.unit, row.metricKey))}</p></div>
          <div><strong>Écart</strong><p>${esc(performanceSummaryFormatDelta(row.gap, row.unit, row.metricKey))}</p></div>
          <div><strong>Tendance</strong><p>${esc(performanceSummaryFormatDelta(row.trend, row.unit, row.metricKey))}</p></div>
          <div><strong>Période</strong><p>${esc(performancePeriodTitle(period))}</p></div>
          <div><strong>Qualité</strong><p>${esc(row.confidence || "moyenne")}</p></div>
        </div>
        <div class="performance-summary-detail-badges">${performanceWarningsBadgesV519(row)}</div>
        <h4>Valeurs alternatives par source</h4>
        <div class="performance-summary-detail-alt">${alternatives}</div>
      </div>
    </div>
  `;
}

function performanceSummaryFamilies(period, rows) {
  return Object.keys(performanceSummaryFamilyLabels).map(key => performanceSummarySectionTable(period, key, rows)).join("");
}

function performanceOverviewSection() {
  const allRecords = performanceAllRecords();
  const selectedPeriod = performanceDashboardFilters.period !== "all"
    ? performanceDashboardFilters.period
    : (allRecords.slice().sort((a, b) => performancePeriodSortValue(b.period) - performancePeriodSortValue(a.period))[0]?.period || performancePeriodKey(perfSelected() || {}));
  const importMeta = performanceLatestImportMeta(selectedPeriod);
  const rows = performanceSummaryRowsForPeriod(selectedPeriod);
  return `
    <div class="card full-span performance-summary-root">
      <div class="performance-summary-headline">
        <div>
          <h2>Synthèse Performance</h2>
          <p class="muted">Période ${esc(performancePeriodTitle(selectedPeriod))} · Dernière source ${esc(importMeta.source)} · Import ${esc(importMeta.date)}</p>
        </div>
        <div class="row-actions">
          <button class="secondary" onclick="startPerformanceImport()">Importer des données</button>
          <button class="secondary" onclick="resetPerformanceDashboardFilters()">Réinitialiser les filtres</button>
        </div>
      </div>
      ${performanceDashboardFilterBar(allRecords)}
      <div class="performance-summary-direction-block">
        <h3>Synthèse Direction</h3>
        ${performanceSummaryCards(allRecords)}
      </div>
      <div class="performance-summary-families">${performanceSummaryFamilies(selectedPeriod, rows)}</div>
      ${performanceSummaryDetailPanel(selectedPeriod, rows)}
    </div>
  `;
}

function setPerformanceDashboardFilter(name, value) {
  performanceDashboardFilters[name] = value || "all";
  if (name === "kpi") performanceDashboardSelectedKpi = "";
  renderPerformance();
}

function togglePerformanceSummarySection(sectionKey) {
  performanceSectionCollapsed[sectionKey] = !performanceSectionCollapsed[sectionKey];
  renderPerformance();
}

function openPerformanceSummaryDetail(metricKey) {
  performanceSummaryDetailMetricKey = metricKey || "";
  renderPerformance();
}

function closePerformanceSummaryDetail() {
  performanceSummaryDetailMetricKey = "";
  renderPerformance();
}

function setPerformanceAnalysisKpi(kpiId) {
  performanceDashboardSelectedKpi = kpiId || "";
  renderPerformance();
}

function savePerformanceDashboardObjective() {
  const kpiId = document.getElementById("perfObjectiveKpiId")?.value || "";
  if (!kpiId) return;
  const mode = document.getElementById("perfObjectiveMode")?.value || "";
  const objective = document.getElementById("perfObjectiveValue")?.value.trim() || "";
  const min = document.getElementById("perfObjectiveMin")?.value.trim() || "";
  const max = document.getElementById("perfObjectiveMax")?.value.trim() || "";
  const unit = document.getElementById("perfObjectiveUnit")?.value.trim() || "";
  const vigilance = document.getElementById("perfObjectiveVigilance")?.value.trim() || "";
  const critical = document.getElementById("perfObjectiveCritical")?.value.trim() || "";
  const store = performanceObjectiveStore();
  if (!mode && !objective && !min && !max && !unit && !vigilance && !critical) delete store[kpiId];
  else store[kpiId] = { mode, objective, min, max, unit, vigilance, critical };
  persistSettings();
  renderPerformance();
}

function resetPerformanceDashboardObjective() {
  const kpiId = document.getElementById("perfObjectiveKpiId")?.value || "";
  if (!kpiId) return;
  delete performanceObjectiveStore()[kpiId];
  persistSettings();
  renderPerformance();
}

function togglePerformanceComplementarySection() {
  performanceComplementaryExpanded = !performanceComplementaryExpanded;
  renderPerformance();
}

function setComplementaryKpiMapping(sourceLabel, targetId) {
  if (!sourceLabel) return;
  performanceImportRememberMapping(sourceLabel, targetId || "complementary.generic");
  renderPerformance();
}

function renderPerformance() {
  document.getElementById("viewTitle").textContent = "Performance";
  document.querySelectorAll(".nav").forEach(btn => btn.classList.toggle("active", btn.dataset.view === "performance"));
  if (performanceImportWizard) return renderPerformanceImportWizard();
  if (!state.performance.length) {
    appHtml(`<div class="card hero performance-hero"><div class="row"><div><h2>Performance</h2><p class="muted">Pilotage mensuel et annuel des indicateurs du site.</p></div><div class="row-actions"><button class="action" onclick="newPerformanceMonth()">Nouveau mois</button><button class="secondary" onclick="startPerformanceImport()">Importer mes données</button></div></div></div><div class="card empty">Aucune période enregistrée.</div>${performanceImportHistory()}`);
    return;
  }
  if (!performanceSelectedId || !byId("performance", performanceSelectedId)) performanceSelectedId = state.performance[0].id;
  const p = perfSelected();
  const years = [...new Set(state.performance.map(x => x.year))].sort((a, b) => b - a);
  const periods = state.performance.filter(x => Number(x.year) === Number(p.year)).sort((a, b) => a.month - b.month);
  appHtml(`<div class="card hero performance-hero"><div class="row"><div><h2>Performance</h2><p class="muted">Pilotage mensuel et annuel, saisie manuelle et calculs automatiques.</p></div><div class="row-actions"><button class="action" onclick="newPerformanceMonth()">Nouveau mois</button><button class="secondary" onclick="duplicatePerformancePrevious()">Dupliquer le mois précédent</button><button class="secondary" onclick="startPerformanceRdp('${p.id}')">Générer une synthèse RDP</button><button class="secondary" onclick="startPerformanceImport()">Importer mes données</button></div></div><div class="performance-selectors"><select onchange="selectPerformanceYear(this.value)">${years.map(y => `<option ${Number(p.year) === Number(y) ? "selected" : ""}>${y}</option>`).join("")}</select><select onchange="openPerformance(this.value)">${periods.map(m => `<option value="${m.id}" ${p.id === m.id ? "selected" : ""}>${esc(perfPeriodLabel(m))}</option>`).join("")}</select></div></div>${performanceEdit ? performanceForm(p) : performanceView(p)}`);
}

function openPerformance(id) {
  performanceSelectedId = id;
  performanceEdit = false;
  renderPerformance();
}

function selectPerformanceYear(year) {
  const period = state.performance.find(p => Number(p.year) === Number(year));
  if (period) performanceSelectedId = period.id;
  renderPerformance();
}

function newPerformanceMonth() {
  const p = perfDefaultPeriod(new Date().getFullYear(), new Date().getMonth() + 1);
  state.performance.unshift(p);
  performanceSelectedId = p.id;
  performanceEdit = true;
  persist("performance");
  renderPerformance();
}

function duplicatePerformancePrevious() {
  const current = perfSelected();
  if (!current) return newPerformanceMonth();
  const prevMonth = current.month === 1 ? 12 : current.month - 1;
  const prevYear = current.month === 1 ? current.year - 1 : current.year;
  const prev = state.performance.find(p => Number(p.month) === prevMonth && Number(p.year) === prevYear);
  if (!prev) return alert("Aucun mois précédent disponible.");
  const copy = normalizePerformance(JSON.parse(JSON.stringify(prev)));
  copy.id = current.id;
  copy.year = current.year;
  copy.month = current.month;
  copy.status = "Brouillon";
  copy.updatedAt = isoToday();
  state.performance[indexById("performance", current.id)] = copy;
  performanceSelectedId = current.id;
  performanceEdit = true;
  persist("performance");
  renderPerformance();
}

// V5.28Q : la vue historique et la synthèse Direction utilisent la même résolution
// de source que le tableau de pilotage supérieur. Cela évite qu'une ancienne valeur
// locale masque un Budget/Historique GPO pourtant disponible.
function performanceLatestImportedMetricRow(metricKey, period, preferredSource = "GPO") {
  const wantedKey = String(metricKey || "").trim().toLowerCase();
  const wantedPeriod = String(period || "").trim();
  const candidates = [];
  ensureArray(state.performance_imports).forEach(item => {
    ensureArray(item.indicators).forEach(row => {
      if (String(row.period || "").trim() !== wantedPeriod) return;
      if (String(row.metricKey || "").trim().toLowerCase() !== wantedKey) return;
      candidates.push({ row, importDate: String(item.importDate || ""), source: performanceSourceKey(row.source || item.sourceType || item.source || "") });
    });
  });
  candidates.sort((a, b) => b.importDate.localeCompare(a.importDate));
  return (candidates.find(item => item.source === preferredSource) || candidates[0] || {}).row || null;
}

function performanceApplyImportedTriplet(metric, row) {
  if (!metric || typeof metric !== "object" || !row) return;
  const actual = row.actual ?? row.value;
  if (perfHas(actual)) metric.actual = actual;
  if (perfHas(row.budget)) metric.budget = row.budget;
  if (perfHas(row.historical)) metric.historical = row.historical;
  if (perfHas(row.objective)) metric.objective = row.objective;
}

function performanceResolvedRecordForView(p) {
  const resolved = normalizePerformance(JSON.parse(JSON.stringify(p || {})));
  const period = performancePeriodKey(resolved);
  const mappings = [
    ["activity.colis_total", "activity"],
    ["ipo.total", "ipo.total"],
    ["ipo.variable", "ipo.variable"],
    ["productivity.preparation", "productivity.Préparation"],
    ["productivity.reception", "productivity.Réception"],
    ["productivity.manutention", "productivity.Manutention"],
    ["productivity.chargement", "productivity.Chargement"],
    ["productivity.transit", "productivity.Transit"],
    ["hours.total", "hours.total"],
    ["hours.direct", "hours.direct"],
    ["hours.indirect", "hours.indirect"],
    ["absenteeism.total", "absenteeism.total"],
    ["absenteeism.maladie", "absenteeism.details.Maladie"],
    ["absenteeism.accident_travail", "absenteeism.details.Accidents du travail"],
    ["quality.total_gains_pertes", "quality.indicators.Total Gains & Pertes"],
    ["pallet.height", "palletHeight"]
  ];
  mappings.forEach(([metricKey, path]) => {
    const preferred = getPreferredPerformanceValue(metricKey, period);
    if (!preferred || !perfHas(preferred.value)) return;
    const metric = perfPath(resolved, path);
    if (!metric || typeof metric !== "object") return;
    metric.actual = preferred.value;
    if (perfHas(preferred.budget)) metric.budget = preferred.budget;
    if (perfHas(preferred.historical)) metric.historical = preferred.historical;
  });

  // V5.28R : G&P et hauteur palette sont des KPI GPO de pilotage mais ne font
  // pas partie du tableau de synthèse multi-sources. On relit donc explicitement
  // leur dernier triplet GPO afin que la fiche mensuelle ne perde ni Budget ni Histo.
  performanceApplyImportedTriplet(
    perfPath(resolved, "quality.indicators.Total Gains & Pertes"),
    performanceLatestImportedMetricRow("quality.total_gains_pertes", period, "GPO")
  );
  performanceApplyImportedTriplet(
    perfPath(resolved, "palletHeight"),
    performanceLatestImportedMetricRow("pallet.height", period, "GPO")
  );
  return resolved;
}

function performanceView(p) {
  const viewP = performanceResolvedRecordForView(p);
  const actions = state.actions.filter(a => (a.linkedPerformance || []).includes(p.id) || (p.link || "").includes(perfPeriodLabel(p)));
  const decisions = state.decisions.filter(d => (d.linkedPerformance || []).includes(p.id));
  const documents = state.documents.filter(d => (d.linkedPerformance || []).includes(p.id));
  return `<div class="card"><div class="row"><div><h2>${esc(perfPeriodLabel(p))}</h2><span class="muted">Statut : ${esc(p.status)} · Dernière mise à jour : ${esc(p.updatedAt || "")}</span></div><div class="row-actions"><button class="action" onclick="performanceEdit=true;renderPerformance()">Modifier</button><button class="secondary" onclick="startPerformanceRdp('${p.id}')">Générer une synthèse RDP</button></div></div></div><div class="grid two">${performanceOverviewSection()}<div class="card"><h2>Activité</h2>${perfMetricBlock("Colis", viewP.activity)}</div><div class="card"><h2>IPO</h2>${perfMetricBlock("IPO total", viewP.ipo.total)}${perfMetricBlock("IPO variable", viewP.ipo.variable)}</div><div class="card full-span"><h2>Productivité par métier</h2>${perfProductivityTable(viewP)}</div><div class="card"><h2>Heures</h2>${perfMetricBlock("Heures totales", viewP.hours.total)}${perfMetricBlock("Heures indirectes", viewP.hours.indirect)}</div><div class="card"><h2>Absentéisme</h2>${perfMetricBlock("Absentéisme total", viewP.absenteeism.total)}</div><div class="card"><h2>Qualité et Gains & Pertes</h2>${perfQualitySummary(viewP)}</div><div class="card"><h2>Hauteur palette</h2>${perfPalletSummary(viewP)}</div><div class="card"><h2>Synthèse DE</h2><p>${esc(p.synthesis || buildPerformanceSynthesis(viewP))}</p></div>${performanceSourceBlock(p)}<div class="card"><h2>Actions liées</h2>${actions.map(a => `<div class="item"><strong>${esc(a.title)}</strong><span class="muted">${esc(a.owner || "")} · ${esc(a.due || "")}</span></div>`).join("") || `<div class="empty">Aucune action liée.</div>`}</div><div class="card"><h2>Décisions liées</h2>${decisions.map(d => `<div class="item clickable" onclick="openDecision('${d.id}')"><strong>${esc(d.title)}</strong><span class="muted">${esc(decisionStatusLabel(d.status))}</span></div>`).join("") || `<div class="empty">Aucune décision liée.</div>`}</div><div class="card full-span"><h2>Documents et comptes rendus liés</h2>${documents.map(d => `<div class="item clickable" onclick="openDocument('${d.id}')"><strong>${esc(d.title || d.name || "Document")}</strong><span class="muted">${esc(d.type || d.category || "")}</span></div>`).join("") || `<div class="empty">Aucun document lié.</div>`}</div></div>`;
  return `<div class="card"><div class="row"><div><h2>${esc(perfPeriodLabel(p))}</h2><span class="muted">Statut : ${esc(p.status)} ? Dernière mise à jour : ${esc(p.updatedAt || "")}</span></div><div class="row-actions"><button class="action" onclick="performanceEdit=true;renderPerformance()">Modifier</button><button class="secondary" onclick="startPerformanceRdp('${p.id}')">Générer une synthèse RDP</button></div></div></div><div class="grid two"><div class="card"><h2>Activité</h2>${perfMetricBlock("Colis", viewP.activity)}</div><div class="card"><h2>IPO</h2>${perfMetricBlock("IPO total", viewP.ipo.total)}${perfMetricBlock("IPO variable", viewP.ipo.variable)}</div><div class="card full-span"><h2>Productivité par métier</h2>${perfProductivityTable(viewP)}</div><div class="card"><h2>Heures</h2>${perfMetricBlock("Heures totales", viewP.hours.total)}${perfMetricBlock("Heures indirectes", viewP.hours.indirect)}</div><div class="card"><h2>Absentéisme</h2>${perfMetricBlock("Absentéisme total", viewP.absenteeism.total)}</div><div class="card"><h2>Qualité et Gains & Pertes</h2>${perfQualitySummary(viewP)}</div><div class="card"><h2>Hauteur palette</h2>${perfPalletSummary(viewP)}</div><div class="card"><h2>Synthèse DE</h2><p>${esc(p.synthesis || buildPerformanceSynthesis(viewP))}</p></div><div class="card full-span"><h2>Historique et tendances</h2>${perfCharts()}</div><div class="card"><h2>Actions liées</h2>${actions.map(a => `<div class="item"><strong>${esc(a.title)}</strong><span class="muted">${esc(a.owner || "")} · ${esc(a.due || "")}</span></div>`).join("") || `<div class="empty">Aucune action liée.</div>`}</div><div class="card"><h2>Décisions liées</h2>${decisions.map(d => `<div class="item clickable" onclick="openDecision('${d.id}')"><strong>${esc(d.title)}</strong><span class="muted">${esc(decisionStatusLabel(d.status))}</span></div>`).join("") || `<div class="empty">Aucune décision liée.</div>`}</div><div class="card full-span"><h2>Documents et comptes rendus liés</h2>${documents.map(d => `<div class="item clickable" onclick="editDocument('${d.id}')"><strong>${esc(d.title)}</strong><span class="muted">${esc(d.type || "")} · ${esc(d.category || "")} · ${esc(d.status || "")}</span></div>`).join("") || `<div class="empty">Aucun document lié.</div>`}</div>${performanceSourceBlock(p)}<div class="card full-span">${performanceImportHistory()}</div></div>`;
}

function performanceSourceBlock(p) {
  const imports = performanceImportsForPeriod(p);
  const legacySources = imports.length ? [] : compactLegacyPerformanceSources(p);
  if (!imports.length && !legacySources.length) return "";
  return `<div class="card full-span"><h2>Sources importées</h2>${imports.map(item => performanceImportSummaryCard(item, p)).join("")}${legacySources.map(item => performanceLegacyImportSummaryCard(item)).join("")}</div>`;
}

function performanceImportsForPeriod(p) {
  const period = performancePeriodKey(p);
  return state.performance_imports.filter(item => importMatchesPeriod(item, period)).sort((a, b) => String(b.importDate || "").localeCompare(String(a.importDate || "")));
}

function performancePeriodKey(p) {
  return `${String(Number(p.month || 0)).padStart(2, "0")}/${p.year}`;
}

function importMatchesPeriod(item, period) {
  const periods = [...ensureArray(item.periods), ...String(item.period || "").split(",").map(x => x.trim()), ...ensureArray(item.indicators).map(x => x.period)].filter(Boolean);
  return periods.includes(period);
}

function performanceImportPeriodTitle(item, p) {
  const period = importMatchesPeriod(item, performancePeriodKey(p)) ? performancePeriodKey(p) : (ensureArray(item.periods)[0] || item.period || "");
  const [month, year] = String(period).split("/").map(Number);
  return month && year ? `${perfMonths[month - 1]} ${year}` : period || perfPeriodLabel(p);
}

function performanceImportSummaryCard(item, p) {
  const period = performancePeriodKey(p);
  const indicators = ensureArray(item.indicators).filter(row => !row.period || row.period === period);
  const imported = Number(item.importedCount ?? indicators.filter(row => row.selected && row.destinationPath).length);
  const detected = ensureArray(item.indicators).length;
  const conflicts = Number(item.conflictCount ?? ensureArray(item.conflicts).length);
  const expanded = expandedPerformanceImportId === item.id;
  const updatedLabels = ensureArray(item.updatedMetricLabels).filter(Boolean);
  const unchangedCount = Math.max(0, detected - imported);
  const importStatusText = imported === 0 && detected > 0 && conflicts === 0
    ? `${detected} indicateur(s) déjà à jour · aucune modification`
    : imported > 0 && conflicts === 0
      ? `${imported} indicateur(s) mis à jour · ${unchangedCount} déjà à jour${updatedLabels.length ? ` · ${updatedLabels.join(", ")}` : ""}`
      : `${imported} indicateur(s) importé(s) · ${detected} détecté(s) · ${conflicts} conflit(s)`;
  return `<div class="item import-summary">
    <div>
      <strong>Source : ${esc(performanceImportSourceLabel(item))} — ${esc(performanceImportPeriodTitle(item, p))}</strong>
      <span class="muted">${esc(importStatusText)}</span>
      <span class="meta">${esc(item.sourceFile || "")}${item.site ? " · Site " + esc(item.site) : ""}${item.importDate ? " · " + esc(item.importDate) : ""}</span>
    </div>
    <div class="row-actions"><button class="secondary" onclick="togglePerformanceImportDetail('${esc(item.id)}')">${expanded ? "Masquer le détail" : "Voir le détail"}</button></div>
    ${expanded ? performanceImportInlineDetail(indicators) : ""}
  </div>`;
}

function performanceImportInlineDetail(indicators) {
  const importedRows = indicators.filter(row => row.selected && row.destinationPath && row.action !== "keep" && row.action !== "ignore");
  const rows = importedRows.map(row => `<tr><td>${esc(row.indicator || "")}</td><td>${esc(row.destinationLabel || "KPI complémentaire — non mappé")}</td><td>${esc(row.value ?? "")}</td><td>${esc(row.period || "")}</td><td>${esc(row.confidence || "")}</td></tr>`).join("");
  return `<div class="import-detail"><table class="perf-table"><thead><tr><th>Indicateur source</th><th>Indicateur DEOS cible</th><th>Valeur importée</th><th>Période</th><th>Confiance</th></tr></thead><tbody>${rows || `<tr><td colspan="5">Aucun détail disponible.</td></tr>`}</tbody></table></div>`;
}

function performanceImportSourceLabel(item) {
  const label = item.sourceType || item.source || "Import";
  return isZGemedSourceLabel(label) ? "Z GEMED" : label;
}

function togglePerformanceImportDetail(id) {
  expandedPerformanceImportId = expandedPerformanceImportId === id ? "" : id;
  renderPerformance();
}

function compactLegacyPerformanceSources(p) {
  const groups = new Map();
  ensureArray(p.importSources).forEach(source => {
    const key = [source.source || "Import", source.file || "", source.importDate || "", source.period || ""].join("|");
    const current = groups.get(key) || { ...source, importedCount: 0, comments: [] };
    current.importedCount += Number(source.importedCount || 1);
    if (source.comment) current.comments.push(source.comment);
    groups.set(key, current);
  });
  return [...groups.values()];
}

function performanceLegacyImportSummaryCard(item) {
  const detailRows = ensureArray(item.comments).map(comment => {
    const [source, target] = String(comment).split("->").map(x => x.trim());
    return `<tr><td>${esc(source || comment)}</td><td>${esc(target || "")}</td><td></td><td>${esc(item.period || "")}</td><td></td></tr>`;
  }).join("");
  const id = `legacy-${perfKey(`${item.source}-${item.file}-${item.importDate}-${item.period}`)}`;
  const expanded = expandedPerformanceImportId === id;
  return `<div class="item import-summary"><div><strong>Source : ${esc(item.source || "Import")} — ${esc(item.period || "")}</strong><span class="muted">${esc(item.importedCount || 0)} indicateur(s) importé(s)</span><span class="meta">${esc(item.file || "")} · ${esc(item.importDate || "")}</span></div><div class="row-actions"><button class="secondary" onclick="togglePerformanceImportDetail('${id}')">${expanded ? "Masquer le détail" : "Voir le détail"}</button></div>${expanded ? `<div class="import-detail"><table class="perf-table"><thead><tr><th>Indicateur source</th><th>Indicateur DEOS cible</th><th>Valeur importée</th><th>Période</th><th>Confiance</th></tr></thead><tbody>${detailRows || `<tr><td colspan="5">Détail non disponible.</td></tr>`}</tbody></table></div>` : ""}</div>`;
}

function perfMetricBlock(label, metric) {
  const rb = perfGap(metric.actual, metric.budget);
  const rh = perfGap(metric.actual, metric.historical);
  return `<div class="performance-metric"><strong>${esc(label)}</strong><span>Historique ${perfFmt(metric.historical)} ? Budget ${perfFmt(metric.budget)} ? Réalisé ${perfFmt(metric.actual)}</span><small>Écart budget ${perfFmt(rb.value)} (${perfFmt(rb.pct, "%")}) ? Écart historique ${perfFmt(rh.value)} (${perfFmt(rh.pct, "%")})</small></div>`;
}

function perfProductivityTable(p) {
  return `<table class="perf-table"><thead><tr><th>Métier</th><th>Historique</th><th>Budget</th><th>Réalisé</th><th>Écart budget</th><th>Écart historique</th><th>Statut</th><th></th></tr></thead><tbody>${perfJobs.map(job => {
    const m = p.productivity[job], rb = perfGap(m.actual, m.budget), rh = perfGap(m.actual, m.historical), st = perfStatus(m);
    return `<tr><td>${esc(job)}</td><td>${perfFmt(m.historical)}</td><td>${perfFmt(m.budget)}</td><td>${perfFmt(m.actual)}</td><td>${perfFmt(rb.value)}</td><td>${perfFmt(rh.value)}</td><td>${badge(st)}</td><td><button class="secondary" onclick="performanceIndicatorAction('${p.id}','Productivité ${esc(job)}')">Créer une action</button><button class="secondary" onclick="performanceIndicatorDecision('${p.id}','Productivité ${esc(job)}')">Créer une décision</button></td></tr>`;
  }).join("")}</tbody></table>`;
}

function perfQualitySummary(p) {
  return Object.entries(p.quality.indicators).map(([k, m]) => perfMetricBlock(k, m)).join("");
}

function perfPalletSummary(p) {
  const gapObjective = perfGap(p.palletHeight.actual, p.palletHeight.objective);
  const gapBudget = perfGap(p.palletHeight.actual, p.palletHeight.budget);
  const gapHistorical = perfGap(p.palletHeight.actual, p.palletHeight.historical);
  return `<div class="performance-metric"><strong>Hauteur palette</strong><span>Historique ${perfFmt(p.palletHeight.historical)} · Budget ${perfFmt(p.palletHeight.budget)} · Réalisé ${perfFmt(p.palletHeight.actual)} · Objectif annuel ${perfFmt(p.palletHeight.objective)}</span><small>Écart budget ${perfFmt(gapBudget.value)} (${perfFmt(gapBudget.pct)}%) · Écart historique ${perfFmt(gapHistorical.value)} (${perfFmt(gapHistorical.pct)}%) · Écart objectif ${perfFmt(gapObjective.value)}</small></div>`;
}

function performanceForm(p) {
  return `<div class="card"><h2>Modifier ${esc(perfPeriodLabel(p))}</h2><div class="form-grid"><input id="pfYear" type="number" value="${p.year}"><select id="pfMonth">${perfMonths.map((m, i) => `<option value="${i + 1}" ${Number(p.month) === i + 1 ? "selected" : ""}>${m}</option>`).join("")}</select><select id="pfStatus"><option ${p.status === "Brouillon" ? "selected" : ""}>Brouillon</option><option ${p.status === "En cours d'analyse" ? "selected" : ""}>En cours d'analyse</option><option ${p.status === "Validé" ? "selected" : ""}>Validé</option><option ${p.status === "Archivé" ? "selected" : ""}>Archivé</option></select></div>${perfMetricForm("Activité colis", "activity", p.activity, ["comment", "highlights", "causes", "projection"])}${perfIpoForm(p)}${perfJobsForm(p)}${perfHoursForm(p)}${perfAbsForm(p)}${perfQualityForm(p)}${perfPalletForm(p)}<div class="card"><h2>Synthèse DE</h2><textarea id="pfSynthesis">${esc(p.synthesis || buildPerformanceSynthesis(viewP))}</textarea></div><div class="grid three manager-links"><div><label>Managers liés</label>${checkboxList("pfManagers", state.managers, p.linkedManagers, m => m.name)}</div><div><label>Projets liés</label>${checkboxList("pfProjects", state.projects, p.linkedProjects, pr => pr.name)}</div><div><label>Dossiers liés</label>${folderSelect("pfFolders", p.linkedFolders)}</div></div><button class="action" onclick="savePerformance('${p.id}')">Enregistrer</button><button class="secondary" onclick="performanceEdit=false;renderPerformance()">Annuler</button></div>`;
}

function perfMetricForm(title, path, m, textFields = []) {
  return `<div class="card"><h2>${esc(title)}</h2><div class="form-grid"><input id="${path}_historical" type="number" value="${esc(m.historical)}" placeholder="Historique"><input id="${path}_budget" type="number" value="${esc(m.budget)}" placeholder="Budget"><input id="${path}_actual" type="number" value="${esc(m.actual)}" placeholder="Réalisé"></div>${textFields.map(f => `<textarea id="${path}_${f}" placeholder="${esc(f)}">${esc(m[f] || "")}</textarea>`).join("")}</div>`;
}

function perfIpoForm(p) {
  return `${perfMetricForm("IPO Total", "ipo_total", p.ipo.total, ["comment", "causes"])}${perfMetricForm("IPO Variable", "ipo_variable", p.ipo.variable, ["comment", "causes"])}<div class="card"><h2>Facteurs explicatifs IPO</h2><div class="form-grid"><input id="ipo_mixEffect" value="${esc(p.ipo.mixEffect)}" placeholder="Effet mix PC / PH"><input id="ipo_directProductivityGap" value="${esc(p.ipo.directProductivityGap)}" placeholder="Écart productivité directe"><input id="ipo_businessMixEffect" value="${esc(p.ipo.businessMixEffect)}" placeholder="Effet indicateur mix métiers"><input id="ipo_indirectHoursGap" value="${esc(p.ipo.indirectHoursGap)}" placeholder="Écart heures indirectes"><input id="ipo_indirectHoursCrush" value="${esc(p.ipo.indirectHoursCrush)}" placeholder="Écrasement heures indirectes"><input id="ipo_ipoPointCost" value="${esc(p.ipo.ipoPointCost)}" placeholder="Coût du point IPO"></div><textarea id="ipo_analysis" placeholder="Analyse">${esc(p.ipo.analysis)}</textarea><textarea id="ipo_rootCauses" placeholder="Causes racines">${esc(p.ipo.rootCauses)}</textarea><textarea id="ipo_trend" placeholder="Tendance">${esc(p.ipo.trend)}</textarea><textarea id="ipo_projection" placeholder="Projection">${esc(p.ipo.projection)}</textarea></div>`;
}

function perfJobsForm(p) {
  return `<div class="card full-span"><h2>Productivité par métier</h2>${perfJobs.map(job => { const m = p.productivity[job], key = `prod_${perfKey(job)}`; return `<h3>${esc(job)}</h3><div class="form-grid"><input id="${key}_historical" type="number" value="${esc(m.historical)}" placeholder="Historique"><input id="${key}_budget" type="number" value="${esc(m.budget)}" placeholder="Budget"><input id="${key}_actual" type="number" value="${esc(m.actual)}" placeholder="Réalisé"><input id="${key}_hoursBudgetGap" type="number" value="${esc(m.hoursBudgetGap)}" placeholder="Heures écart budget"><input id="${key}_hoursHistoricalGap" type="number" value="${esc(m.hoursHistoricalGap)}" placeholder="Heures écart historique"></div>${job === "Préparation" ? `<div class="form-grid"><input id="${key}_cdiProductivity" value="${esc(m.cdiProductivity)}" placeholder="Productivité CDI"><input id="${key}_cddProductivity" value="${esc(m.cddProductivity)}" placeholder="Productivité CDD"><input id="${key}_ettProductivity" value="${esc(m.ettProductivity)}" placeholder="Productivité ETT"><input id="${key}_totalProductivity" value="${esc(m.totalProductivity)}" placeholder="Productivité totale"><input id="${key}_cdiHoursShare" value="${esc(m.cdiHoursShare)}" placeholder="Part heures CDI"><input id="${key}_cddHoursShare" value="${esc(m.cddHoursShare)}" placeholder="Part heures CDD"><input id="${key}_ettHoursShare" value="${esc(m.ettHoursShare)}" placeholder="Part heures ETT"><input id="${key}_bicReference" value="${esc(m.bicReference)}" placeholder="Référence BIC"><input id="${key}_supplyAverage" value="${esc(m.supplyAverage)}" placeholder="Moyenne Supply"></div>` : ""}<textarea id="${key}_comment" placeholder="Commentaire">${esc(m.comment)}</textarea><textarea id="${key}_causes" placeholder="Causes">${esc(m.causes)}</textarea><textarea id="${key}_actions" placeholder="Actions engagées">${esc(m.actions)}</textarea>`; }).join("")}</div>`;
}

function perfHoursForm(p) {
  return `${perfMetricForm("Heures totales", "hours_total", p.hours.total, ["comment", "causes"])}${perfMetricForm("Heures directes", "hours_direct", p.hours.direct)}${perfMetricForm("Heures indirectes", "hours_indirect", p.hours.indirect)}<div class="card"><h2>Heures majorées</h2><div class="form-grid"><input id="hours_overtime" value="${esc(p.hours.overtime)}" placeholder="Heures supplémentaires"><input id="hours_night" value="${esc(p.hours.night)}" placeholder="Heures de nuit"><input id="hours_sundays" value="${esc(p.hours.sundays)}" placeholder="Dimanches travaillés"><input id="hours_holidays" value="${esc(p.hours.holidays)}" placeholder="Jours fériés travaillés"></div><textarea id="hours_analysis" placeholder="Analyse des heures">${esc(p.hours.analysis)}</textarea><textarea id="hours_causes" placeholder="Principales causes">${esc(p.hours.causes)}</textarea><textarea id="hours_levers" placeholder="Leviers de réduction">${esc(p.hours.levers)}</textarea></div>`;
}

function perfAbsForm(p) {
  return `${perfMetricForm("Absentéisme total", "abs_total", p.absenteeism.total, ["comment", "causes"])}<div class="card"><h2>Détail absentéisme</h2>${perfAbsences.map(k => { const m = p.absenteeism.details[k], key = `abs_${perfKey(k)}`; return `<h3>${esc(k)}</h3><div class="form-grid"><input id="${key}_historical" type="number" value="${esc(m.historical)}" placeholder="Historique"><input id="${key}_budget" type="number" value="${esc(m.budget)}" placeholder="Budget"><input id="${key}_actual" type="number" value="${esc(m.actual)}" placeholder="Réalisé"><input id="${key}_hours" type="number" value="${esc(m.hours)}" placeholder="Nombre d'heures"></div>`; }).join("")}<textarea id="abs_impacts" placeholder="Impacts opérationnels">${esc(p.absenteeism.impacts)}</textarea><textarea id="abs_hrActions" placeholder="Actions RH">${esc(p.absenteeism.hrActions)}</textarea><textarea id="abs_projection" placeholder="Projection">${esc(p.absenteeism.projection)}</textarea></div>`;
}

function perfQualityForm(p) {
  return `<div class="card"><h2>Qualité et Gains & Pertes</h2>${perfQuality.map(k => perfMetricForm(k, `qual_${perfKey(k)}`, p.quality.indicators[k], ["comment"])).join("")}<textarea id="qual_highlights" placeholder="Faits marquants">${esc(p.quality.highlights)}</textarea><textarea id="qual_causes" placeholder="Causes">${esc(p.quality.causes)}</textarea><textarea id="qual_correctiveActions" placeholder="Actions correctives">${esc(p.quality.correctiveActions)}</textarea></div>`;
}

function perfPalletForm(p) {
  return `<div class="card"><h2>Hauteur palette</h2><div class="form-grid"><input id="pal_historical" type="number" value="${esc(p.palletHeight.historical)}" placeholder="Historique"><input id="pal_objective" type="number" value="${esc(p.palletHeight.objective)}" placeholder="Objectif"><input id="pal_budget" type="number" value="${esc(p.palletHeight.budget)}" placeholder="Budget"><input id="pal_actual" type="number" value="${esc(p.palletHeight.actual)}" placeholder="Réalisé"><input id="pal_trend" value="${esc(p.palletHeight.trend)}" placeholder="Tendance"></div><textarea id="pal_comment" placeholder="Commentaire">${esc(p.palletHeight.comment)}</textarea><textarea id="pal_causes" placeholder="Causes">${esc(p.palletHeight.causes)}</textarea><textarea id="pal_actions" placeholder="Actions">${esc(p.palletHeight.actions)}</textarea></div>`;
}

function readMetric(path) {
  const g = id => document.getElementById(`${path}_${id}`)?.value.trim() || "";
  return { historical: g("historical"), budget: g("budget"), actual: g("actual"), comment: g("comment"), causes: g("causes"), actions: g("actions"), highlights: g("highlights"), projection: g("projection") };
}

function savePerformance(id) {
  const i = indexById("performance", id);
  if (i < 0) return;
  const p = state.performance[i];
  p.year = Number(document.getElementById("pfYear").value);
  p.month = Number(document.getElementById("pfMonth").value);
  p.status = document.getElementById("pfStatus").value;
  p.activity = { ...p.activity, ...readMetric("activity") };
  p.ipo.total = { ...p.ipo.total, ...readMetric("ipo_total") };
  p.ipo.variable = { ...p.ipo.variable, ...readMetric("ipo_variable") };
  ["mixEffect", "directProductivityGap", "businessMixEffect", "indirectHoursGap", "indirectHoursCrush", "ipoPointCost", "analysis", "rootCauses", "trend", "projection"].forEach(k => p.ipo[k] = document.getElementById(`ipo_${k}`)?.value.trim() || "");
  perfJobs.forEach(job => { const key = `prod_${perfKey(job)}`, m = p.productivity[job]; Object.assign(m, readMetric(key)); ["hoursBudgetGap", "hoursHistoricalGap", "cdiProductivity", "cddProductivity", "ettProductivity", "totalProductivity", "cdiHoursShare", "cddHoursShare", "ettHoursShare", "bicReference", "supplyAverage"].forEach(k => m[k] = document.getElementById(`${key}_${k}`)?.value.trim() || m[k] || ""); m.status = perfStatus(m); });
  p.hours.total = { ...p.hours.total, ...readMetric("hours_total") };
  p.hours.direct = { ...p.hours.direct, ...readMetric("hours_direct") };
  p.hours.indirect = { ...p.hours.indirect, ...readMetric("hours_indirect") };
  ["overtime", "night", "sundays", "holidays", "analysis", "causes", "levers"].forEach(k => p.hours[k] = document.getElementById(`hours_${k}`)?.value.trim() || "");
  p.absenteeism.total = { ...p.absenteeism.total, ...readMetric("abs_total") };
  perfAbsences.forEach(k => { const key = `abs_${perfKey(k)}`; p.absenteeism.details[k] = { ...p.absenteeism.details[k], ...readMetric(key), hours: document.getElementById(`${key}_hours`)?.value.trim() || "" }; });
  ["impacts", "hrActions", "projection"].forEach(k => p.absenteeism[k] = document.getElementById(`abs_${k}`)?.value.trim() || "");
  perfQuality.forEach(k => p.quality.indicators[k] = { ...p.quality.indicators[k], ...readMetric(`qual_${perfKey(k)}`) });
  ["highlights", "causes", "correctiveActions"].forEach(k => p.quality[k] = document.getElementById(`qual_${k}`)?.value.trim() || "");
  p.palletHeight = { historical: document.getElementById("pal_historical").value, objective: document.getElementById("pal_objective").value, budget: document.getElementById("pal_budget").value, actual: document.getElementById("pal_actual").value, trend: document.getElementById("pal_trend").value, comment: document.getElementById("pal_comment").value, causes: document.getElementById("pal_causes").value, actions: document.getElementById("pal_actions").value };
  p.synthesis = document.getElementById("pfSynthesis").value;
  p.linkedManagers = checkedValues("pfManagers"); p.linkedProjects = checkedValues("pfProjects"); p.linkedFolders = checkedValues("pfFolders");
  p.updatedAt = isoToday();
  state.performance[i] = normalizePerformance(p);
  persist("performance");
  addActivity("Performance", perfPeriodLabel(p), "Mise à jour", p.id);
  performanceEdit = false;
  renderPerformance();
}

function buildPerformanceSynthesis(p) {
  const metrics = [
    ["Activité", p.activity], ["IPO total", p.ipo.total], ["IPO variable", p.ipo.variable], ["Heures totales", p.hours.total], ["Absentéisme", p.absenteeism.total], ["Hauteur palette", { historical: p.palletHeight.historical, budget: p.palletHeight.budget, actual: p.palletHeight.actual }]
  ];
  const gaps = metrics.map(([label, m]) => ({ label, pct: perfGap(m.actual, m.budget).pct, comment: m.comment || m.causes || "" })).filter(x => x.pct !== "");
  const positives = gaps.filter(x => x.pct >= 0).slice(0, 3).map(x => `- ${x.label} : ${perfFmt(x.pct, "%")}`).join("\n") || "À compléter";
  const vigilance = gaps.sort((a, b) => Math.abs(b.pct) - Math.abs(a.pct)).slice(0, 3).map(x => `- ${x.label} : ${perfFmt(x.pct, "%")} ${x.comment}`).join("\n") || "À compléter";
  return `Points positifs\n${positives}\n\nPoints de vigilance\n${vigilance}\n\nIndicateurs éloignés du budget\n${vigilance}\n\nActions prioritaires\n${reportActions(state.actions.filter(a => (a.linkedPerformance || []).includes(p.id)))}\n\nDécisions attendues\n${reportDecisions(state.decisions.filter(d => (d.linkedPerformance || []).includes(p.id)))}`;
}

function perfCharts() {
  const series = [["Activité", "activity"], ["IPO Total", "ipo.total"], ["IPO Variable", "ipo.variable"], ["Productivité Préparation", "productivity.Préparation"], ["Heures totales", "hours.total"], ["Heures indirectes", "hours.indirect"], ["Absentéisme", "absenteeism.total"], ["Gains & Pertes", "quality.indicators.Total Gains & Pertes"], ["Hauteur palette", "palletHeight"]];
  return `<div class="perf-charts">${series.map(([label, path]) => perfChart(label, path)).join("")}</div>`;
}

function perfPath(obj, path) {
  return path.split(".").reduce((acc, key) => acc?.[key], obj);
}

function perfChart(label, path) {
  const rows = state.performance.slice().sort((a, b) => a.year - b.year || a.month - b.month).map(p => ({ p, m: perfPath(p, path) })).filter(x => x.m && (perfHas(x.m.historical) || perfHas(x.m.budget) || perfHas(x.m.actual)));
  if (rows.length < 1) return `<div class="perf-chart"><strong>${esc(label)}</strong><div class="empty">Données insuffisantes</div></div>`;
  const max = Math.max(1, ...rows.flatMap(x => [perfNum(x.m.historical), perfNum(x.m.budget), perfNum(x.m.actual)]));
  return `<div class="perf-chart"><strong>${esc(label)}</strong>${rows.map(x => `<div class="perf-bars"><span>${esc(perfMonths[x.p.month - 1].slice(0, 3))}</span><i style="height:${perfNum(x.m.historical) / max * 70}px"></i><i class="budget" style="height:${perfNum(x.m.budget) / max * 70}px"></i><i class="actual" style="height:${perfNum(x.m.actual) / max * 70}px"></i></div>`).join("")}<small>Historique ? Budget ? Réalisé</small></div>`;
}

function performanceIndicatorAction(id, label) {
  const p = byId("performance", id);
  const title = `Performance ${perfPeriodLabel(p)} - ${label}`;
  if (state.actions.some(a => a.title === title)) return;
  state.actions.unshift(normalizeEntity("actions", { id: newId("action"), title, link: label, owner: "", level: "orange", due: "", done: false, linkedFolders: p.linkedFolders, linkedManagers: p.linkedManagers, linkedProjects: p.linkedProjects, linkedPerformance: [id] }));
  persist("actions");
  addActivity("Action", title, "Créée depuis Performance", id);
  renderPerformance();
}

function performanceIndicatorDecision(id, label) {
  const p = byId("performance", id);
  const title = `Décision Performance ${perfPeriodLabel(p)} - ${label}`;
  if (state.decisions.some(d => d.title === title)) return;
  state.decisions.unshift({ id: newId("decision"), title, date: isoToday(), status: "review", importance: "orange", context: `Analyse Performance ${perfPeriodLabel(p)}`, problem: label, decision: "", rationale: "", alternatives: "", impacts: "", risks: "", owner: "", linkedManagers: p.linkedManagers, linkedProjects: p.linkedProjects, linkedActions: [], linkedDocuments: [], linkedFolders: p.linkedFolders, linkedPerformance: [id], reviewDate: "", events: [], directorNotes: [], nextStep: "", tags: ["Performance"] });
  persist("decisions");
  addActivity("Décision", title, "Créée depuis Performance", id);
  renderPerformance();
}

function startPerformanceRdp(id) {
  const p = byId("performance", id);
  if (!p) return;
  startReport("performance", id, "Revue de performance");
}

const performanceImportSources = [
  { key: "gpo", label: "GPO PDF", accept: ".pdf" },
  { key: "guide", label: "Guide performance PDF", accept: ".pdf" },
  { key: "zgemed", label: "Z GEMED Excel", accept: ".xls,.xlsx,.xlsb,.csv" },
  { key: "cgtab", label: "CGTAB", accept: ".xls,.xlsx,.xlsb,.csv,.txt" },
  { key: "ga", label: "GA", accept: ".xls,.xlsx,.xlsb,.csv,.pdf" },
  { key: "tbag", label: "T-Bag", accept: ".xls,.xlsx,.xlsb,.csv,.txt" },
  { key: "litiges", label: "Litiges", accept: ".xls,.xlsx,.csv,.pdf" }
];
const IMPORT_PERIOD_PENDING = "Période à confirmer";

// V5.28A — Référentiel site centralisé pour tous les imports Performance.
const PERFORMANCE_IMPORT_SITE = Object.freeze({
  code: "FRY8MC",
  name: "Saint-Gilles",
  aliases: ["saint gilles", "st gilles", "st-gilles", "saint-gilles"]
});

function performanceImportSiteCode(value = "") {
  return String(value || "").trim().toUpperCase();
}

function performanceImportSiteMatches(value = "") {
  const code = performanceImportSiteCode(value);
  if (code === PERFORMANCE_IMPORT_SITE.code) return true;
  const text = normalizeText(value);
  return PERFORMANCE_IMPORT_SITE.aliases.some(alias => text.includes(normalizeText(alias)));
}

function performanceImportSiteLabel() {
  return `${PERFORMANCE_IMPORT_SITE.name} (${PERFORMANCE_IMPORT_SITE.code})`;
}

function performanceImportDistinctSiteCodes(values = []) {
  return [...new Set(ensureArray(values).map(performanceImportSiteCode).filter(value => /^FR[A-Z0-9]+$/.test(value)))].sort();
}

function detectCompactImportPeriod(value = "") {
  const text = String(value || "");
  const hit = text.match(/(?:^|[^0-9])(0?[1-9]|1[0-2])[-_ ]?(20\d{2})(?:[^0-9]|$)/);
  return hit ? `${String(Number(hit[1])).padStart(2, "0")}/${hit[2]}` : "";
}

function detectGpoPdf(file) {
  return { ...file, source: "GPO PDF", sourceType: "GPO PDF", status: "à confirmer", confidence: "moyenne", period: detectImportPeriod(file.name), message: "analyse réelle disponible après lecture locale PDF.js" };
}
function detectGuidePerformancePdf(file) { return importDetection(file, "Guide performance PDF", "extraction à développer"); }
function detectZGemedExcel(file) {
  const ext = String(file.extension || file.name || "").toLowerCase();
  const name = String(file.name || "").toLowerCase();
  const binary = ext.endsWith("xlsb") || ext === "xlsb";
  const likely = /z[ _-]?gemed|gemed/.test(name) || binary;
  return {
    ...file,
    source: "Z GEMED",
    sourceType: "Z GEMED Excel",
    status: binary ? "à confirmer" : (likely ? "probablement reconnu" : "à confirmer"),
    confidence: binary || likely ? "moyenne" : "faible",
    period: detectImportPeriod(file.name),
    site: /st[-_ ]?gilles|saint[-_ ]?gilles/.test(name) ? "Saint-Gilles" : "",
    message: binary ? "Fichier Z GEMED binaire détecté." : "Analyse locale avec contrôle du site."
  };
}
function detectCgtab(file) {
  const ext = String(file.extension || file.name || "").toLowerCase();
  const isXlsb = ext.endsWith("xlsb") || ext === "xlsb";
  return {
    ...importDetection(file, "CGTAB", "analyse locale agrégée (anonymisée)"),
    source: "CGTAB",
    sourceType: "CGTAB XLSB",
    status: isXlsb ? "à confirmer" : "probablement reconnu",
    confidence: isXlsb ? "moyenne" : "faible",
    message: isXlsb
      ? "Format XLSB détecté. V5.18.6 agrège uniquement des KPI RH anonymisés (aucune donnée nominative persistée)."
      : "Format détecté. Pour V5.18.6, l'extraction validée cible le classeur XLSB CGTAB Saint-Gilles."
  };
}
function detectGa(file) {
  const ext = String(file.extension || file.name || "").toLowerCase();
  const isXlsb = ext.endsWith("xlsb") || ext === "xlsb";
  const isDetail = /detail\s+par\s+salari/i.test(normalizeText(file.name || ""));
  return {
    ...importDetection(file, "GA", isDetail ? "analyse locale agrégée du détail GA nominatif" : "analyse locale dédiée Suivi GA"),
    source: isDetail ? "GA_DETAIL_AGGREGATED" : "SUIVI_GA",
    sourceType: isDetail ? "Suivi GA détail salarié" : "Suivi GA",
    status: isXlsb ? "à confirmer" : "probablement reconnu",
    confidence: isXlsb ? "moyenne" : "faible",
    message: isXlsb
      ? (isDetail
        ? "Format XLSB détecté. Le détail salarié GA sera lu puis agrégé en mémoire, sans aucune persistance nominative."
        : "Format XLSB détecté. Extraction locale activée pour le modèle validé St Gilles.")
      : (isDetail
        ? "Format détecté. Pour V5.18.8, seule une extraction agrégée et anonymisée du détail salarié est autorisée."
        : "Format détecté. Pour V5.18.5, l'extraction validée cible le classeur XLSB St Gilles.")
  };
}
function detectTBag(file) {
  const ext = String(file.extension || file.name || "").toLowerCase();
  const isXlsb = ext.endsWith("xlsb") || ext === "xlsb";
  return {
    ...importDetection(file, "T-Bag", "analyse locale préparation détaillée"),
    source: "T_BAG",
    sourceType: "T-Bag XLSB",
    status: isXlsb ? "à confirmer" : "probablement reconnu",
    confidence: isXlsb ? "moyenne" : "faible",
    message: isXlsb
      ? "Format XLSB détecté. Analyse détaillée Préparation (agrégée, non nominative)."
      : "Format détecté. Pour V5.18.7, l'extraction validée cible le classeur XLSB T-Bag."
  };
}
function detectLitiges(file) { return importDetection(file, "Litiges", "extraction à développer"); }

function importDetection(file, source, message) {
  return { ...file, source, status: file.typeDetected === "non reconnu" ? "non reconnu" : "à confirmer", period: detectImportPeriod(file.name), message };
}

function detectImportType(name = "") {
  const n = name.toLowerCase();
  if (n.includes("gpo") && n.endsWith(".pdf")) return "GPO PDF";
  if ((n.includes("guide") || n.includes("performance")) && n.endsWith(".pdf")) return "Guide performance PDF";
  if (n.includes("z") && n.includes("gemed")) return "Z GEMED Excel";
  if (n.includes("cgtab")) return "CGTAB";
  if (/\bga\b|ga[_ -]/i.test(name)) return "GA";
  if (n.includes("t-bag") || n.includes("tbag")) return "T-Bag";
  if (n.includes("litige")) return "Litiges";
  if (n.endsWith(".pdf")) return "PDF non reconnu";
  if (/\.(xls|xlsx|xlsm|xlsb|csv)$/i.test(name)) return "Excel non reconnu";
  return "non reconnu";
}

function detectImportPeriod(name = "") {
  const month = name.match(/(20\d{2})[-_ ]?(0[1-9]|1[0-2])/);
  if (month) return `${month[2]}/${month[1]}`;
  const fr = name.match(/(janvier|février|fevrier|mars|avril|mai|juin|juillet|août|aout|septembre|octobre|novembre|décembre|decembre)[-_ ]?(20\d{2})/i);
  return fr ? `${fr[1]} ${fr[2]}` : "";
}

function periodMonthFromFrenchLabel(label = "") {
  const monthMap = { janvier: 1, fevrier: 2, mars: 3, avril: 4, mai: 5, juin: 6, juillet: 7, aout: 8, septembre: 9, octobre: 10, novembre: 11, decembre: 12 };
  return monthMap[normalizeText(label)] || 0;
}

function canonicalPerformancePeriod(period = "") {
  const raw = String(period || "").trim();
  if (!raw) return "";
  const mmYyyy = raw.match(/^(0?[1-9]|1[0-2])\/(20\d{2})$/);
  if (mmYyyy) return `${String(Number(mmYyyy[1])).padStart(2, "0")}/${mmYyyy[2]}`;
  const yyyyMm = raw.match(/^(20\d{2})[-\/.](0?[1-9]|1[0-2])$/);
  if (yyyyMm) return `${String(Number(yyyyMm[2])).padStart(2, "0")}/${yyyyMm[1]}`;
  const fr = raw.match(/(janvier|février|fevrier|mars|avril|mai|juin|juillet|août|aout|septembre|octobre|novembre|décembre|decembre)\s*(20\d{2})/i);
  if (fr) {
    const month = periodMonthFromFrenchLabel(fr[1]);
    if (month) return `${String(month).padStart(2, "0")}/${fr[2]}`;
  }
  return "";
}

function parsePerformancePeriod(period = "") {
  const canonical = canonicalPerformancePeriod(period);
  if (!canonical) return null;
  const [month, year] = canonical.split("/").map(Number);
  if (!month || !year) return null;
  return { month, year, key: canonical };
}

function performanceRecordPeriod(record = {}) {
  const month = Number(record.month);
  const year = Number(record.year);
  if (month >= 1 && month <= 12 && year >= 1900) {
    return { month, year, key: `${String(month).padStart(2, "0")}/${year}` };
  }
  return parsePerformancePeriod(record.period || "");
}

function performanceEnsurePeriodIdentity(record = {}) {
  const parsed = performanceRecordPeriod(record);
  if (!parsed) return record;
  const sameMonth = Number(record.month) === parsed.month;
  const sameYear = Number(record.year) === parsed.year;
  const samePeriod = String(record.period || "") === parsed.key;
  if (sameMonth && sameYear && samePeriod) return record;
  return { ...record, month: parsed.month, year: parsed.year, period: parsed.key };
}

function performancePeriodSortStamp(record = {}) {
  const parsed = performanceRecordPeriod(record);
  if (!parsed) return 0;
  return parsed.year * 100 + parsed.month;
}

function detectPerformanceImportFile(file) {
  const base = { id: newId("file"), name: file.name || "Fichier", size: file.size || 0, extension: (String(file.name || "").split(".").pop() || "").toLowerCase(), typeDetected: detectImportType(file.name || "") };
  if (base.typeDetected === "GPO PDF") return detectGpoPdf(base);
  if (base.typeDetected === "Guide performance PDF") return detectGuidePerformancePdf(base);
  if (base.typeDetected === "Z GEMED Excel") return detectZGemedExcel(base);
  if (base.typeDetected === "CGTAB") return detectCgtab(base);
  if (base.typeDetected === "GA") return detectGa(base);
  if (base.typeDetected === "T-Bag") return detectTBag(base);
  if (base.typeDetected === "Litiges") return detectLitiges(base);
  return importDetection(base, "Source à confirmer", "extraction à développer");
}

function sourceKeyForLabel(label = "") {
  const found = performanceImportSources.find(s => s.label === label);
  return found ? found.key : "manual";
}

function startPerformanceImport() {
  performanceImportWizard = { id: newId("perfimport"), step: 1, files: [], preview: [], comments: "", validatedBy: identityName(), status: "brouillon", selectedPeriods: [], errors: [] };
  renderPerformance();
}

function cancelPerformanceImport() {
  performanceImportWizard = null;
  renderPerformance();
}

function performanceImportSteps() {
  return ["Fichiers", "Sources", "Aperçu", "Validation"].map((label, i) => `<span class="${performanceImportWizard.step === i + 1 ? "active-step" : ""}">${i + 1}. ${label}</span>`).join("");
}

function renderPerformanceImportWizard() {
  appHtml(`<div class="card hero report-hero"><button class="secondary" onclick="cancelPerformanceImport()">Retour Performance</button><h2>Importer mes données</h2><p class="muted">Import local préparé pour GPO PDF, Z GEMED et les autres sources Performance.</p><div class="report-steps">${performanceImportSteps()}</div></div>${performanceImportBody()}`);
}

function performanceImportBody() {
  if (performanceImportWizard.step === 1) return performanceImportStepFiles();
  if (performanceImportWizard.step === 2) return performanceImportStepSources();
  if (performanceImportWizard.step === 3) return performanceImportStepPreview();
  return performanceImportStepValidate();
}

function performanceImportStepFiles() {
  const sourceHelp = key => ({
    gpo: "Analyse locale PDF.js · site contrôlé dans le document.",
    zgemed: "Analyse locale XLSX/CSV · filtre Saint-Gilles si plusieurs sites sont présents.",
    ga: "Analyse locale XLSB générique · onglet/ligne Saint-Gilles détecté par FRY8MC.",
    tbag: "Analyse locale XLSB · lignes filtrées sur AL = FRY8MC.",
    cgtab: "Analyse locale XLSB agrégée/anonymisée · salariés filtrés sur AL = FRY8MC.",
    guide: "PDF performance complémentaire.",
    litiges: "Source complémentaire à cartographier."
  }[key] || "Analyse locale.");
  return `<div class="card"><h2>Sélection des fichiers</h2><div class="item alert-blue"><strong>Site cible de l'import : ${esc(performanceImportSiteLabel())}</strong><span class="muted">Un fichier peut contenir plusieurs sites ou plusieurs onglets. DEOS ne retient que Saint-Gilles et signale les autres sites détectés.</span></div><div class="grid two">${performanceImportSources.map(s => `<div class="item"><strong>${esc(s.label)}</strong><input type="file" accept="${esc(s.accept)}" onchange="addPerformanceImportFiles('${s.key}',this.files)"><span class="muted">${esc(sourceHelp(s.key))}</span></div>`).join("")}</div>${performanceImportFilesList()}<div class="row-actions"><button class="secondary" onclick="cancelPerformanceImport()">Annuler</button><button class="action" onclick="setPerformanceImportStep(2)">Suivant</button></div></div>`;
}

function performanceImportFilesList() {
  return `<div class="card"><h2>Fichiers sélectionnés</h2>${performanceImportWizard.files.map(f => {
    const detectedSites = performanceImportDistinctSiteCodes(f.detectedSiteCodes || []);
    const siteMeta = detectedSites.length ? ` · Codes détectés : ${detectedSites.join(", ")}` : "";
    return `<div class="item"><strong>${esc(f.name)}</strong><span class="muted">${esc(f.typeDetected)} · ${esc(f.source)} · ${esc(f.period || f.periods?.join(", ") || "Période à confirmer")} · Confiance ${esc(f.confidence || "moyenne")}</span><span class="meta">Site retenu : ${esc(f.site || "à confirmer")}${f.siteCode ? ` (${esc(f.siteCode)})` : ""}${esc(siteMeta)}</span><span class="meta">${esc(f.status)} · ${esc(f.message || "")}</span></div>`;
  }).join("") || `<div class="empty">Aucun fichier ajouté.</div>`}${performanceImportWizard.errors.map(e => `<div class="item alert-red"><strong>${esc(e.title)}</strong><span class="muted">${esc(e.detail)}</span></div>`).join("")}</div>`;
}

async function addPerformanceImportFiles(sourceKey, fileList) {
  const source = performanceImportSources.find(s => s.key === sourceKey);
  for (const file of [...fileList]) {
    const detected = await analyzePerformanceImportFile(file, sourceKey);
    detected.source = source?.label || detected.source;
    performanceImportWizard.files.push(detected);
  }
  buildPerformanceImportPreview();
  renderPerformanceImportWizard();
}

function addFakePerformanceImportFile() {
  const source = performanceImportSources.find(s => s.key === document.getElementById("piFakeSource").value);
  const name = document.getElementById("piFakeName").value.trim() || "fichier_test.pdf";
  const detected = detectPerformanceImportFile({ name, size: 0 });
  detected.source = source?.label || detected.source;
  performanceImportWizard.files.push(detected);
  buildPerformanceImportPreview();
  renderPerformanceImportWizard();
}

function setPerformanceImportStep(step) {
  if (step >= 3) buildPerformanceImportPreview();
  performanceImportWizard.step = step;
  renderPerformanceImportWizard();
}

function performanceImportStepSources() {
  return `<div class="card"><h2>Identification de la source</h2>${performanceImportWizard.files.map(file => `<div class="item"><strong>${esc(file.name)}</strong><span class="muted">Type détecté : ${esc(file.typeDetected)} · Source supposée : ${esc(file.source)} · Statut : ${esc(file.status || "à confirmer")} · Confiance ${esc(file.confidence || "moyenne")}</span><span class="meta">Site retenu : ${esc(file.site || "à confirmer")}${file.siteCode ? ` (${esc(file.siteCode)})` : ""} · Périodes : ${esc(ensureArray(file.periods).join(", ") || file.period || "à confirmer")} · Onglets : ${esc(ensureArray(file.sheets).join(", ") || "non disponible")}</span>${ensureArray(file.periods).length ? `<div class="manager-links">${file.periods.map(p => `<label style="display:grid;grid-template-columns:22px minmax(90px,160px);align-items:center;gap:10px;width:max-content;margin:6px 0"><input type="checkbox" checked onchange="toggleImportPeriod('${esc(file.id)}','${esc(p)}',this.checked)"><span>${esc(p)}</span></label>`).join("")}</div>` : ""}${file.message ? `<span class="meta">${esc(file.message)}</span>` : ""}</div>`).join("") || `<div class="empty">Aucun fichier à identifier.</div>`}<div class="row-actions"><button class="secondary" onclick="setPerformanceImportStep(1)">Retour</button><button class="secondary" onclick="cancelPerformanceImport()">Annuler</button><button class="action" onclick="setPerformanceImportStep(3)">Créer l'aperçu</button></div></div>`;
}

function buildPerformanceImportPreview() {
  performanceImportWizard.preview = performanceImportWizard.files.flatMap(file => {
    const rawRows = performanceImportRawIndicators(file);
    const rows = normalizePerformanceImportIndicators(rawRows, file);
    file.detectedIndicators = rows;
    const selected = ensureArray(file.selectedPeriods || file.periods).map(period => normalizeImportPeriod(period) || String(period || "").trim()).filter(Boolean);
    const selectedSet = new Set(selected);
    const filtered = selectedSet.size ? rows.filter(row => {
      if (!row.period || row.period === IMPORT_PERIOD_PENDING) return true;
      const rowPeriod = normalizeImportPeriod(row.period) || String(row.period || "").trim();
      return selectedSet.has(rowPeriod) || selectedSet.has(String(row.period || "").trim());
    }) : rows;
    return filtered.map(row => decoratePerformancePreviewRow(row, file));
  });
}

function gaDetailComparisonPreviewCards() {
  const files = ensureArray(performanceImportWizard?.files).filter(file => ensureArray(file.comparisonSummary).length);
  if (!files.length) return "";
  const fmt = value => value === null || value === undefined || value === "" ? "" : perfFmt(value);
  const fmtMaybe = value => value === null || value === undefined || value === "" ? "—" : perfFmt(value);
  return files.map(file => {
    const sections = ensureArray(file.comparisonSummary).map(summary => {
      const legacyRows = [
        { axis: "Direct", data: summary.legacyCurrent?.direct || {} },
        { axis: "Indirect", data: summary.legacyCurrent?.indirect || {} }
      ];
      const legacyTable = `<table class="perf-table import-preview-table"><thead><tr><th>Axe</th><th>metricKey</th><th>Centres détectés</th><th>Scopes détectés</th><th>Lignes complémentaires</th><th>Nb valeurs agrégées</th><th>Formule actuelle</th><th>Valeur actuelle</th></tr></thead><tbody>${legacyRows.map(item => `<tr><td>${esc(item.axis)}</td><td>${esc(item.data.metricKey || "")}</td><td>${esc(ensureArray(item.data.costCenters).join(", ") || "-")}</td><td>${esc(ensureArray(item.data.scopes).join(", ") || "-")}</td><td>${esc(item.data.complementaryRowsSummary || "-")}</td><td>${esc(item.data.aggregatedValueCount ?? 0)}</td><td>${esc(item.data.formula || "")}</td><td>${esc(fmt(item.data.value) || "0")}</td></tr>`).join("")}</tbody></table>`;
      const centerRows = ensureArray(summary.requestedCenterComparisons || []).map(row => `<tr><td>${esc(row.costCenter || "")}</td><td>${esc(fmtMaybe(row.detailDirect))}</td><td>${esc(fmtMaybe(row.suiviDirect))}</td><td>${esc(fmtMaybe(row.directDelta))}</td><td>${esc(fmtMaybe(row.detailIndirect))}</td><td>${esc(fmtMaybe(row.suiviIndirect))}</td><td>${esc(fmtMaybe(row.indirectDelta))}</td><td>${esc(row.directStatus || "")}</td><td>${esc(row.indirectStatus || "")}</td></tr>`).join("");
      const onlyDetail = ensureArray(summary.singleSourceCenters?.detailOnly || []);
      const onlySuivi = ensureArray(summary.singleSourceCenters?.consolidatedOnly || []);
      const perimeterWarning = summary.flags?.perimetersEquivalent
        ? ""
        : `<div class="item alert-orange"><strong>Périmètres différents</strong><span class="muted">L'écart global n'est pas interprétable comme rapprochement fiable hors périmètre commun.</span></div>`;
      return `<div class="item"><strong>Période ${esc(summary.period || "")}</strong>${perimeterWarning}<div class="meta">DIRECT — Total GA détail tous centres: ${esc(fmt(summary.detailTotals?.allCenters?.direct) || "0")} · Total GA détail centres comparables Direct: ${esc(fmt(summary.detailTotals?.comparableDirect?.direct) || "0")} · Total Suivi GA centres comparables Direct: ${esc(fmt(summary.consolidatedTotals?.comparableDirect?.direct) || "0")} · Écart: ${esc(fmt(summary.axisCommon?.direct?.delta) || "0")}</div><div class="meta">DIRECT — Centres comparables: ${esc(ensureArray(summary.axisCommon?.direct?.comparableCenters).join(", ") || "aucun")}</div><div class="meta">DIRECT — Centres non comparables: ${esc(ensureArray(summary.axisCommon?.direct?.nonComparableCenters).join(", ") || "aucun")}</div><div class="meta">INDIRECT — Total GA détail tous centres: ${esc(fmt(summary.detailTotals?.allCenters?.indirect) || "0")} · Total GA détail centres comparables Indirect: ${esc(fmt(summary.detailTotals?.comparableIndirect?.indirect) || "0")} · Total Suivi GA centres comparables Indirect: ${esc(fmt(summary.consolidatedTotals?.comparableIndirect?.indirect) || "0")} · Écart: ${esc(fmt(summary.axisCommon?.indirect?.delta) || "0")}</div><div class="meta">INDIRECT — Centres comparables: ${esc(ensureArray(summary.axisCommon?.indirect?.comparableCenters).join(", ") || "aucun")}</div><div class="meta">INDIRECT — Centres non comparables: ${esc(ensureArray(summary.axisCommon?.indirect?.nonComparableCenters).join(", ") || "aucun")}</div><div class="meta">4. Centres présents dans une seule source: GA détail uniquement = ${esc(onlyDetail.join(", ") || "aucun")}; Suivi GA uniquement = ${esc(onlySuivi.join(", ") || "aucun")}</div><div class="meta">5. Règle anti-doublon: ${esc(summary.antiDoubleCountRule || "")}</div>${legacyTable}<table class="perf-table import-preview-table"><thead><tr><th>Centre de coûts</th><th>Direct GA détail</th><th>Direct Suivi GA</th><th>Écart Direct</th><th>Indirect GA détail</th><th>Indirect Suivi GA</th><th>Écart Indirect</th><th>Statut Direct</th><th>Statut Indirect</th></tr></thead><tbody>${centerRows || `<tr><td colspan="9">Aucun centre commun disponible.</td></tr>`}</tbody></table></div>`;
    }).join("");
    return `<div class="card"><h3>Synthèse rapprochement GA détail vs Suivi GA consolidé</h3><div class="muted">${esc(file.name || "")}</div>${sections}</div>`;
  }).join("");
}

function performanceImportStepPreview() {
  const periodSelector = performanceImportPeriodSelector();
  const targetOptions = performanceImportTargetOptions();
  const mappedRows = performanceImportWizard.preview.filter(row => row.destinationPath);
  const unmappedRows = performanceImportWizard.preview.filter(row => !row.destinationPath && row.targetType !== "ignore");
  const hasAggregatedPrivacyRows = performanceImportWizard.preview.some(row => String(row.privacyLevel || "") === "aggregated" || /CGTAB/i.test(String(row.source || row.sourceType || "")));
  const hasTbagRows = performanceImportWizard.preview.some(row => /T_BAG|T-Bag/i.test(String(row.source || row.sourceType || "")));
  const hasGaDetailRows = performanceImportWizard.preview.some(row => /GA_DETAIL_AGGREGATED|détail salarié/i.test(String(row.source || row.sourceType || "")));
  const privacyBanner = hasAggregatedPrivacyRows ? `<div class="item alert-blue"><strong>Données individuelles non conservées — import agrégé uniquement</strong><span class="muted">Aucun nom, matricule ou ligne salarié n'est persisté. Seules des sommes/comptages agrégés sont proposés.</span></div>` : "";
  const tbagPrivacyBanner = hasTbagRows ? `<div class="item alert-blue"><strong>Données agrégées Préparation — aucune donnée individuelle conservée</strong><span class="muted">Les informations T-Bag sont normalisées en agrégats par période, population et bannière.</span></div>` : "";
  const gaDetailPrivacyBanner = hasGaDetailRows ? `<div class="item alert-blue"><strong>Analyse agrégée et anonymisée — aucun détail individuel conservé</strong><span class="muted">Les groupes à moins de 5 salariés sont masqués ou exclus de l'aperçu importable.</span></div>` : "";
  const gaDetailComparisonCards = gaDetailComparisonPreviewCards();
  const maskedGroups = performanceImportWizard.files.flatMap(file => ensureArray(file.maskedGroups || []).map(item => ({ ...item, fileName: file.name || "" })));
  const typeLabel = row => row.periodType === "cumulative" ? "Cumul" : "Mensuel";
  const categoryLabel = row => ({
    activity: "Activité",
    hours_direct: "Heures directes",
    hours_indirect: "Heures indirectes — total",
    hours_indirect_detail: "Heures indirectes — détail"
  })[String(row.category || "")] || row.category || "";
  const gaRoleLabel = row => {
    if (!/SUIVI_GA/i.test(String(row.source || row.sourceType || ""))) return "";
    if (String(row.category || "") === "hours_indirect_detail") return "Détail analytique — non additionné au total";
    if (String(row.category || "") === "hours_indirect") return "Total centre — valeur consolidée";
    if (String(row.category || "") === "hours_direct") return "Heures directes du centre";
    if (String(row.category || "") === "activity") return "Activité du site";
    return "";
  };
  const formatImportNumber = value => {
    if (value === null || value === undefined || value === "") return "";
    const numeric = normalizeImportNullableNumericValue(value);
    return typeof numeric === "number" && Number.isFinite(numeric) ? perfFmt(numeric) : value;
  };
  const deltaLabel = (value, percent) => {
    const base = value === null || value === undefined || value === "" ? "" : perfFmt(value);
    const pct = percent === null || percent === undefined || percent === "" ? "" : `${perfFmt(percent)}%`;
    return [base, pct].filter(Boolean).join(" · ") || "";
  };
  const formatImportActualDisplay = row => {
    const value = row.actual ?? row.value ?? "";
    const numeric = normalizeImportNullableNumericValue(value);
    if (row.unit === "%" && typeof numeric === "number" && Number.isFinite(numeric) && numeric >= 0 && numeric <= 1) {
      return `${new Intl.NumberFormat("fr-FR", { minimumFractionDigits: 1, maximumFractionDigits: 1 }).format(numeric * 100)} %`;
    }
    return formatImportNumber(value);
  };
  const plannedActionLabel = row => {
    const currentValueExists = row.currentValue !== "" && row.currentValue !== null && row.currentValue !== undefined;
    if (row.status === "Identique") return "Identique";
    if (!currentValueExists && row.action !== "ignore") return "Ajouter";
    if (row.action === "keep" || row.action === "ignore") return "Conserver";
    if ((row.status === "Conflit" || row.status === "Différente") && row.recommendedSourceReplacement) return "Remplacer (GPO recommandé)";
    if (row.status === "Conflit" || row.status === "Différente") return "Remplacer";
    return row.action === "use" ? "Ajouter" : "Conserver";
  };
  const rows = mappedRows.map(row => {
    const currentTargetId = row.targetId || row.destinationId || (performanceImportTargetFromPath(row.destinationPath)?.id || "");
    const statusText = row.status || performanceImportStatusLabel(row.status);
    const selectable = row.targetType !== "ignore";
    const roleHint = gaRoleLabel(row);
    const targetHint = row.targetType === "complementary" ? "KPI complémentaire · À vérifier" : row.targetType === "existing" ? "KPI DEOS existant" : "À vérifier";
    const catalogHasCurrentTarget = targetOptions.some(target => target.id === currentTargetId);
    const dynamicTargetOption = currentTargetId && !catalogHasCurrentTarget
      ? `<option value="${esc(currentTargetId)}" selected>${esc(row.destinationLabel || row.label || row.indicator || currentTargetId)}</option>`
      : "";
    const selectHtml = dynamicTargetOption + targetOptions.map(target => `<option value="${esc(target.id)}" ${currentTargetId === target.id ? "selected" : ""}>${esc(target.label)}</option>`).join("");
    const explicitGpoMapping = performanceSourceKey(row.source || row.sourceType || "") === "GPO" && Boolean(currentTargetId) && Boolean(row.destinationPath);
    const destinationHtml = explicitGpoMapping
      ? `<div class="import-target-select"><strong>${esc(row.destinationLabel || row.label || row.indicator || currentTargetId)}</strong><small class="muted">Mapping GPO explicite${row.confidenceText ? ` · confiance ${esc(row.confidenceText)}` : ""}</small></div>`
      : `<div class="import-target-select"><select onchange="setImportPreviewTarget('${row.id}', this.value)">${selectHtml}</select><small class="muted">${esc(targetHint)}${row.confidenceText ? ` · confiance ${esc(row.confidenceText)}` : ""}</small></div>`;
    return `<tr class="import-${esc(row.tone)}"><td><input type="checkbox" ${row.selected ? "checked" : ""} onchange="toggleImportPreviewRow('${row.id}',this.checked)" ${selectable ? "" : "disabled"}></td><td>${esc(row.period || "à confirmer")}</td><td>${esc(typeLabel(row))}</td><td>${esc(categoryLabel(row))}${roleHint ? `<br><small class="muted">${esc(roleHint)}</small>` : ""}</td><td>${esc(row.population || "")}</td><td>${esc(row.banner || "")}</td><td>${esc(row.costCenter || "")}</td><td>${esc(row.directness || "")}</td><td>${esc(row.label || row.indicator)}</td><td>${esc(formatImportActualDisplay(row))}</td><td>${esc(formatImportNumber(row.budget))}</td><td>${esc(formatImportNumber(row.historical))}</td><td>${esc(deltaLabel(row.deltaBudget, row.deltaBudgetPercent))}</td><td>${esc(deltaLabel(row.deltaHistorical, row.deltaHistoricalPercent))}</td><td>${esc(row.unit || "")}</td><td>${esc(row.aggregationType || "")}</td><td>${esc(row.employeeCount ?? "")}</td><td>${esc(row.privacyRule || "")}</td><td>${esc(row.sourceColumns || "")}</td><td>${esc(row.privacyLevel || "")}</td><td>${esc(row.sourceSheet || row.sourcePage || "")}</td><td>${esc(row.sourceCell || row.pageSource || row.sourceRef || "")}</td><td>${destinationHtml}</td><td>${esc(row.currentValue === "" || row.currentValue === null || row.currentValue === undefined ? "" : perfFmt(row.currentValue))}</td><td>${esc(row.confidenceText || "")}</td><td><strong>${esc(plannedActionLabel(row))}</strong><br><small>${esc(statusText)}</small>${row.status === "Conflit" || row.status === "Différente" ? `<select onchange="setImportPreviewAction('${row.id}',this.value)"><option value="keep" ${row.action === "keep" ? "selected" : ""}>Conserver DEOS</option><option value="use" ${row.action === "use" ? "selected" : ""}>Remplacer</option><option value="ignore" ${row.action === "ignore" ? "selected" : ""}>Ne pas importer</option></select>` : `<select onchange="setImportPreviewAction('${row.id}',this.value)"><option value="use" ${row.action === "use" ? "selected" : ""}>Utiliser source</option><option value="ignore" ${row.action === "ignore" ? "selected" : ""}>Ne pas importer</option></select>`}</td></tr>`;
  }).join("");
  const unmappedTable = unmappedRows.length ? `<div class="card"><h3>Indicateurs détectés mais non mappés</h3><table class="perf-table import-preview-table"><thead><tr><th>Période</th><th>Type</th><th>Catégorie</th><th>Population</th><th>Bannière</th><th>Centre de coûts</th><th>Direct.</th><th>Indicateur source</th><th>Réel</th><th>Budget</th><th>Historique</th><th>Écart Budget</th><th>Écart Historique</th><th>Unité</th><th>Agrégation</th><th>Contributeurs</th><th>Règle confidentialité</th><th>Colonnes source</th><th>Niveau privacy</th><th>Feuille</th><th>Cellule</th><th>Confiance</th><th>Destination</th></tr></thead><tbody>${unmappedRows.map(row => `<tr class="import-orange"><td>${esc(row.period || "à confirmer")}</td><td>${esc(typeLabel(row))}</td><td>${esc(row.category || "")}</td><td>${esc(row.population || "")}</td><td>${esc(row.banner || "")}</td><td>${esc(row.costCenter || "")}</td><td>${esc(row.directness || "")}</td><td>${esc(row.label || row.indicator)}</td><td>${esc(formatImportActualDisplay(row))}</td><td>${esc(row.budget ?? "")}</td><td>${esc(row.historical ?? "")}</td><td>${esc(deltaLabel(row.deltaBudget, row.deltaBudgetPercent))}</td><td>${esc(deltaLabel(row.deltaHistorical, row.deltaHistoricalPercent))}</td><td>${esc(row.unit || "")}</td><td>${esc(row.aggregationType || "")}</td><td>${esc(row.employeeCount ?? "")}</td><td>${esc(row.privacyRule || "")}</td><td>${esc(row.sourceColumns || "")}</td><td>${esc(row.privacyLevel || "")}</td><td>${esc(row.sourceSheet || row.sourcePage || "")}</td><td>${esc(row.sourceCell || row.pageSource || row.sourceRef || "")}</td><td>${esc(row.confidenceText || "")}</td><td><select onchange="setImportPreviewTarget('${row.id}', this.value)">${targetOptions.map(target => `<option value="${esc(target.id)}" ${(row.targetId || row.destinationId || "ignore") === target.id ? "selected" : ""}>${esc(target.label)}</option>`).join("")}</select></td></tr>`).join("")}</tbody></table></div>` : "";
  const maskedGroupsTable = maskedGroups.length ? `<div class="card"><h3>Groupes masqués pour confidentialité</h3><table class="perf-table import-preview-table"><thead><tr><th>Période</th><th>Type</th><th>Valeur</th><th>Contributeurs</th><th>Règle</th><th>Feuille</th></tr></thead><tbody>${maskedGroups.map(row => `<tr class="import-gray"><td>${esc(row.period || "")}</td><td>${esc(row.groupType || "")}</td><td>${esc(row.label || row.value || "")}</td><td>${esc(row.employeeCount || "")}</td><td>${esc(row.rule || "")}</td><td>${esc(row.sourceSheet || "")}</td></tr>`).join("")}</tbody></table></div>` : "";
  const emptyDiagnostic = performanceImportEmptyDiagnostic();
  return `<div class="card"><h2>Aperçu avant import</h2><p class="muted">Aucune donnée Performance existante ne sera écrasée silencieusement. Les correspondances sont proposées, révisables et mémorisées uniquement si vous les validez.</p><div class="item alert-blue"><strong>Règle V5.28O</strong><span class="muted">Les 21 KPI GPO reconnus utilisent désormais un mapping explicite. Les anciennes valeurs DEOS restent comparées, mais les destinations GPO ne sont plus proposées via une liste générique. Vous gardez la validation finale.</span></div>${privacyBanner}${tbagPrivacyBanner}${gaDetailPrivacyBanner}${gaDetailComparisonCards}${periodSelector}<table class="perf-table import-preview-table"><thead><tr><th></th><th>Période</th><th>Type</th><th>Catégorie</th><th>Population</th><th>Bannière</th><th>Centre de coûts</th><th>Direct.</th><th>KPI</th><th>Réel</th><th>Budget</th><th>Historique</th><th>Écart Budget</th><th>Écart Historique</th><th>Unité</th><th>Agrégation</th><th>Contributeurs</th><th>Règle confidentialité</th><th>Colonnes source</th><th>Niveau privacy</th><th>Feuille</th><th>Cellule</th><th>Destination DEOS</th><th>Valeur DEOS</th><th>Confiance</th><th>Action prévue</th></tr></thead><tbody>${rows || `<tr><td colspan="26">${emptyDiagnostic}</td></tr>`}</tbody></table>${maskedGroupsTable}${unmappedTable}<div class="row-actions"><button class="secondary" onclick="setPerformanceImportStep(2)">Retour</button><button class="secondary" onclick="cancelPerformanceImport()">Annuler</button><button class="action" onclick="setPerformanceImportStep(4)">Valider l'aperçu</button></div></div>`;
}

function performanceImportRawIndicators(file) {
  return ensureArray(file.detectedIndicators || file.indicators || file.kpis || file.kpi || file.metrics || file.rows);
}

function firstImportValue(source, keys) {
  for (const key of keys) {
    const value = source?.[key];
    if (value !== null && value !== undefined && String(value).trim() !== "") return value;
  }
  return "";
}

function normalizeImportNumericValue(value) {
  if (typeof value === "number") return Number.isFinite(value) ? value : "";
  const parsed = parseZGemedNumber(value);
  return parsed !== "" ? parsed : String(value ?? "").trim();
}

function normalizeImportNullableNumericValue(value) {
  if (value === null || value === undefined || String(value).trim() === "") return null;
  if (typeof value === "number") return Number.isFinite(value) ? value : null;
  const parsed = parseZGemedNumber(value);
  return parsed !== "" ? parsed : String(value ?? "").trim();
}

function normalizeImportDestination(path = "", destinationField = "") {
  const rawPath = String(path || "").trim();
  const rawField = String(destinationField || "").trim();
  if (!rawPath) return { path: "", field: rawField };
  if (rawField) return { path: rawPath, field: rawField };
  const leafMatch = rawPath.match(/^(.*)\.(actual|budget|historical|totalShare)$/);
  if (!leafMatch) return { path: rawPath, field: rawField };
  return { path: leafMatch[1], field: leafMatch[2] };
}

function isIpoMetricDescriptor({ metricKey = "", destinationPath = "", targetId = "", label = "", category = "" } = {}) {
  const key = String(metricKey || "").toLowerCase();
  const path = String(destinationPath || "").toLowerCase();
  const target = String(targetId || "").toLowerCase();
  const text = normalizeText(label || "");
  const cat = normalizeText(category || "");
  return key.startsWith("ipo.")
    || path.startsWith("ipo.")
    || target.startsWith("ipo.")
    || text.includes("ipo")
    || cat === "ipo";
}

function normalizePerformanceImportIndicators(rows, file) {
  return ensureArray(rows).map(raw => {
    const indicator = firstImportValue(raw, ["indicator", "label", "name", "title", "kpi", "sourceIndicator", "indicateur"]);
    const rawValue = firstImportValue(raw, ["value", "currentValue", "actual", "real", "reel", "detectedValue", "valeur"]);
    if (!indicator) return null;
    const destinationPath = firstImportValue(raw, ["destinationPath", "path", "targetPath", "deosPath"]);
    const destinationLabel = firstImportValue(raw, ["destinationLabel", "destination", "target", "deosIndicator"]) || (destinationPath ? indicator : "KPI complémentaire");
    const targetFromPath = performanceImportTargetFromPath(destinationPath);
    const sourceType = raw.sourceType || file.sourceType || file.source || "";
    const explicitTargetId = firstImportValue(raw, ["targetId", "destinationId"]);
    const explicitTargetType = firstImportValue(raw, ["targetType"]);
    const hasExplicitTargetType = Object.prototype.hasOwnProperty.call(raw, "targetType") && String(explicitTargetType).trim() !== "";
    let targetFromLabel = hasExplicitTargetType
      ? null
      : (isZGemedSourceLabel(sourceType)
        ? (explicitTargetId ? performanceImportTargetById(explicitTargetId) : null)
        : performanceImportDestinationFromRow({ indicator, unit: firstImportValue(raw, ["unit", "unite"]) || "" }));
    if (/gpo/i.test(sourceType) && targetFromLabel?.id === "complementary.generic" && !destinationPath) targetFromLabel = null;
    const target = hasExplicitTargetType
      ? (explicitTargetId ? performanceImportTargetById(explicitTargetId) : null)
      : (targetFromPath || targetFromLabel);
    const targetType = explicitTargetType || (target ? target.type : (destinationPath ? "existing" : "complementary"));
    const targetId = explicitTargetId || (target ? target.id : "");
    const mappedPathRaw = destinationPath || (hasExplicitTargetType ? "" : (target ? target.path : ""));
    const normalizedDestination = normalizeImportDestination(mappedPathRaw, raw.destinationField || "");
    const mappedLabel = firstImportValue(raw, ["destinationLabel", "destination", "target", "deosIndicator"]) || (target ? target.label : "KPI complémentaire");
    const sourceConfidenceScore = Number.isFinite(Number(raw.sourceConfidenceScore)) ? Number(raw.sourceConfidenceScore) : null;
    const confidenceMeta = performanceImportConfidenceMeta(sourceConfidenceScore ?? (targetType === "existing" ? 92 : targetType === "complementary" ? (targetId === "complementary.generic" ? 62 : 74) : 40));
    const selected = raw.selected !== undefined ? Boolean(raw.selected) : targetType !== "ignore";
    const period = normalizeImportPeriod(raw.period || raw.date || file.period || ensureArray(file.periods)[0]) || IMPORT_PERIOD_PENDING;
    const source = /gpo/i.test(sourceType) ? "GPO" : (isZGemedSourceLabel(raw.source || file.source || file.sourceType || "") ? "Z_GEMED" : (raw.source || file.source || file.sourceType || "Import"));
    const population = firstImportValue(raw, ["population", "populationType"]) || "";
    const banner = firstImportValue(raw, ["banner", "brand"]) || "";
    const actual = normalizeImportNullableNumericValue(rawValue);
    const budget = normalizeImportNullableNumericValue(firstImportValue(raw, ["budget", "target", "objective", "objectif"]));
    const historical = normalizeImportNullableNumericValue(firstImportValue(raw, ["historical", "histo", "history"]));
    const rawUnit = firstImportValue(raw, ["unit", "unite"]) || "";
    const metricKey = firstImportValue(raw, ["metricKey", "metric", "metric_key"]) || normalizePerformanceLabel(indicator).replace(/\s+/g, "_");
    const unit = isIpoMetricDescriptor({ metricKey, destinationPath: normalizedDestination.path, targetId, label: indicator, category: firstImportValue(raw, ["category", "group"]) || "" }) ? IPO_UNIT : rawUnit;
    const sourcePage = firstImportValue(raw, ["sourcePage", "pageSource", "page", "sourceRef"]);
    const explicitActionProvided = Object.prototype.hasOwnProperty.call(raw, "action");
    const action = explicitActionProvided ? String(raw.action || "") : (targetType === "ignore" ? "ignore" : "use");
    return {
      ...raw,
      id: raw.id || newId("preview"),
      period,
      periodType: firstImportValue(raw, ["periodType"]) || "monthly",
      indicator: String(indicator).trim(),
      label: String(firstImportValue(raw, ["label", "displayLabel"]) || indicator).trim(),
      metricKey,
      category: firstImportValue(raw, ["category", "group"]) || "Autre",
      scope: firstImportValue(raw, ["scope"]) || "global",
      population,
      banner,
      actual,
      value: actual,
      budget,
      historical,
      deltaBudget: normalizeImportNullableNumericValue(firstImportValue(raw, ["deltaBudget", "budgetGap"])),
      deltaHistorical: normalizeImportNullableNumericValue(firstImportValue(raw, ["deltaHistorical", "historicalGap"])),
      deltaBudgetPercent: normalizeImportNullableNumericValue(firstImportValue(raw, ["deltaBudgetPercent", "budgetGapPercent"])),
      deltaHistoricalPercent: normalizeImportNullableNumericValue(firstImportValue(raw, ["deltaHistoricalPercent", "historicalGapPercent"])),
      objective: normalizeImportNullableNumericValue(firstImportValue(raw, ["objective", "target", "objectif"])),
      aggregationType: firstImportValue(raw, ["aggregationType"]) || "",
      employeeCount: normalizeImportNullableNumericValue(firstImportValue(raw, ["employeeCount", "contributors"])),
      privacyRule: firstImportValue(raw, ["privacyRule", "confidentialityRule"]) || "",
      sourceColumns: firstImportValue(raw, ["sourceColumns"]) || "",
      privacyLevel: firstImportValue(raw, ["privacyLevel"]) || "",
      unit,
      source,
      sourceType,
      sourcePage,
      sourceSheet: firstImportValue(raw, ["sourceSheet", "sheet", "worksheet"]) || "",
      sourceCell: firstImportValue(raw, ["sourceCell", "cell", "sourceCells"]) || "",
      pageSource: raw.pageSource || raw.sourcePage || raw.page || raw.sourceRef || sourcePage || "",
      sourceRef: raw.sourceRef || raw.pageSource || raw.sourcePage || raw.page || "",
      destinationPath: normalizedDestination.path,
      destinationLabel: mappedLabel,
      destinationField: normalizedDestination.field,
      destinationId: targetId,
      targetId,
      targetType,
      confidence: raw.confidence || confidenceMeta.label,
      sourceConfidenceScore: sourceConfidenceScore ?? undefined,
      validationWarning: raw.validationWarning || "",
      confidenceScore: confidenceMeta.score,
      confidenceLabel: confidenceMeta.label,
      confidenceText: confidenceMeta.text,
      selected,
      action
    };
  }).filter(row => {
    if (!row || !row.indicator) return false;
    return [row.actual, row.value, row.budget, row.historical, row.deltaBudget, row.deltaHistorical, row.deltaBudgetPercent, row.deltaHistoricalPercent]
      .some(value => value !== null && value !== undefined && String(value).trim() !== "");
  });
}


function performanceImportPeriodSelector() {
  const needsPeriod = performanceImportWizard.preview.some(row => row.period === IMPORT_PERIOD_PENDING || !row.period);
  if (!needsPeriod) return "";
  const years = [new Date().getFullYear() - 1, new Date().getFullYear(), new Date().getFullYear() + 1];
  const months = ["01 - Janvier", "02 - Février", "03 - Mars", "04 - Avril", "05 - Mai", "06 - Juin", "07 - Juillet", "08 - Août", "09 - Septembre", "10 - Octobre", "11 - Novembre", "12 - Décembre"];
  const selectedMonth = performanceImportWizard.manualMonth || "06";
  const selectedYear = performanceImportWizard.manualYear || String(new Date().getFullYear());
  return `<div class="item alert-orange"><strong>Période à confirmer</strong><span class="muted">Les KPI restent visibles. Sélectionner le mois et l'année avant validation si la période n'a pas été détectée automatiquement.</span><div class="row-actions"><select id="piManualMonth" onchange="setPendingImportPeriod()">${months.map(m => `<option value="${m.slice(0, 2)}" ${m.startsWith(selectedMonth) ? "selected" : ""}>${m}</option>`).join("")}</select><select id="piManualYear" onchange="setPendingImportPeriod()">${years.map(y => `<option value="${y}" ${String(y) === String(selectedYear) ? "selected" : ""}>${y}</option>`).join("")}</select><button class="secondary" onclick="setPendingImportPeriod()">Appliquer la période</button></div></div>`;
}

function performanceImportEmptyDiagnostic() {
  const extracted = performanceImportWizard.files.reduce((sum, file) => sum + performanceImportRawIndicators(file).length, 0);
  const normalized = performanceImportWizard.files.reduce((sum, file) => sum + normalizePerformanceImportIndicators(performanceImportRawIndicators(file), file).length, 0);
  const selected = performanceImportWizard.files.map(file => ensureArray(file.selectedPeriods || file.periods).join(", ") || "aucune").join(" · ");
  return extracted ? `${extracted} KPI extrait(s), ${normalized} KPI normalisé(s), 0 transmis à l'aperçu. Périodes sélectionnées : ${esc(selected)}.` : "Aucun indicateur exploitable détecté.";
}

function setPendingImportPeriod() {
  const month = document.getElementById("piManualMonth")?.value || "06";
  const year = document.getElementById("piManualYear")?.value || String(new Date().getFullYear());
  const period = `${month}/${year}`;
  performanceImportWizard.manualMonth = month;
  performanceImportWizard.manualYear = year;
  performanceImportWizard.files.forEach(file => {
    file.detectedIndicators = ensureArray(file.detectedIndicators).map(row => (!row.period || row.period === IMPORT_PERIOD_PENDING) ? { ...row, period } : row);
    file.period = file.period && file.period !== IMPORT_PERIOD_PENDING ? file.period : period;
    file.periods = ensureArray(file.periods).map(p => p === IMPORT_PERIOD_PENDING ? period : p);
    if (!file.periods.length) file.periods = [period];
    file.selectedPeriods = ensureArray(file.selectedPeriods).map(p => p === IMPORT_PERIOD_PENDING ? period : p);
    if (!file.selectedPeriods.length) file.selectedPeriods = [period];
  });
  buildPerformanceImportPreview();
  renderPerformanceImportWizard();
}

function setImportPreviewAction(id, action) {
  const row = performanceImportWizard.preview.find(x => x.id === id);
  if (row) {
    row.action = action;
    row.selected = action === "use";
    if (action === "use" && (row.targetId || row.destinationId)) performanceImportRememberMapping(row.indicator, row.targetId || row.destinationId);
    if (action === "ignore") row.selected = false;
    Object.assign(row, decoratePerformancePreviewRow(row));
    renderPerformanceImportWizard();
  }
}

function performanceImportStepValidate() {
  const selected = performanceImportWizard.preview.filter(x => x.selected && x.destinationPath);
  const conflicts = performanceImportWizard.preview.filter(x => x.status === "Conflit" || x.status === "Différente");
  const validationError = performanceImportWizard.validationError
    ? `<div class="item alert-red"><strong>Import non enregistré</strong><span class="muted">${esc(performanceImportWizard.validationError)}</span></div>`
    : "";
  return `<div class="card"><h2>Validation</h2><p>La validation alimente réellement Performance uniquement avec les lignes cochées. Les lignes en conflit restent conservées côté DEOS sauf choix « Utiliser source ».</p>${validationError}<div class="form-grid"><input id="piValidatedBy" value="${esc(performanceImportWizard.validatedBy || identityName())}" placeholder="Utilisateur ayant validé"><select id="piStatus"><option value="validé">validé</option><option value="brouillon">brouillon</option><option value="rejeté">rejeté</option></select><textarea id="piComments" class="full" placeholder="Commentaires">${esc(performanceImportWizard.comments || "")}</textarea></div><div class="item"><strong>${selected.length} indicateur(s) importable(s)</strong><span class="muted">${conflicts.length} conflit(s) ou différence(s) · ${performanceImportWizard.files.length} fichier(s) source(s)</span></div><div class="row-actions"><button class="secondary" onclick="setPerformanceImportStep(3)">Retour</button><button class="secondary" onclick="cancelPerformanceImport()">Annuler</button><button class="action" onclick="validatePerformanceImport()">Valider l'import</button></div></div>`;
}

function compactPerformanceImportIndicator(row = {}) {
  // V5.28P : l'historique d'import reste compact, mais conserve les champs
  // indispensables à l'analyse Réel / Budget / Historique et au matching KPI.
  return {
    period: row.period || "",
    periodType: row.periodType || "monthly",
    source: row.source || row.sourceType || "",
    indicator: row.indicator || row.label || "",
    metricKey: row.metricKey || "",
    actual: row.actual ?? row.value ?? "",
    value: row.value ?? row.actual ?? "",
    budget: row.budget ?? null,
    historical: row.historical ?? null,
    objective: row.objective ?? null,
    unit: row.unit || "",
    destinationLabel: row.destinationLabel || "",
    destinationPath: row.destinationPath || "",
    targetId: row.targetId || row.destinationId || "",
    targetType: row.targetType || "",
    status: row.status || "",
    confidence: row.confidence || row.confidenceText || "",
    action: row.action || ""
  };
}

function compactPerformanceImportPayload(item = {}) {
  const sourceRows = ensureArray(item.indicators).length ? ensureArray(item.indicators) : ensureArray(item.preview);
  const sourceFile = String(item.sourceFile || ensureArray(item.files).map(file => file?.name || "").filter(Boolean).join(", ")).trim();
  return normalizeEntity("performance_imports", {
    id: item.id || newId("perfimport"),
    importDate: item.importDate || "",
    sourceFile,
    sourceType: item.sourceType || "Source à confirmer",
    period: item.period || "",
    site: item.site || "",
    indicators: sourceRows.map(compactPerformanceImportIndicator),
    detectedCount: Number(item.detectedCount ?? sourceRows.length),
    status: item.status || "brouillon",
    validatedBy: item.validatedBy || "",
    comments: item.comments || "",
    importedCount: Number(item.importedCount || 0),
    ignoredCount: Number(item.ignoredCount || 0),
    conflictCount: Number(item.conflictCount ?? ensureArray(item.conflicts).length),
    periods: ensureArray(item.periods),
    updatedMetricLabels: ensureArray(item.updatedMetricLabels).filter(Boolean),
    privacyAudit: item.privacyAudit || undefined
  });
}

function compactPerformanceImportHistoryForStorage() {
  state.performance_imports = ensureArray(state.performance_imports).map(compactPerformanceImportPayload);
  persist("performance_imports");
}

function performanceImportQuotaMessage(error) {
  const code = String(error?.code || "").toUpperCase();
  const name = String(error?.name || error?.originalError?.name || "").toUpperCase();
  if (code === "STORAGE_QUOTA_EXCEEDED" || name.includes("QUOTA")) {
    return "Le stockage local du navigateur est saturé. DEOS a compacté l'historique des imports Performance, mais l'import reste trop volumineux. Exportez une sauvegarde puis contactez l'administrateur DEOS avant de supprimer des données.";
  }
  return error?.message || "La validation de l'import Performance a échoué.";
}

function validatePerformanceImport() {
  const first = performanceImportWizard.files[0] || {};
  const selectedRows = performanceImportWizard.preview.filter(row => row.selected && row.destinationPath && row.action !== "keep" && row.action !== "ignore");
  const importDate = new Date().toLocaleString("fr-FR");
  const previousPerformance = JSON.stringify(state.performance || []);
  const status = document.getElementById("piStatus")?.value || "validé";
  const validatedBy = document.getElementById("piValidatedBy")?.value?.trim() || "";
  const comments = document.getElementById("piComments")?.value?.trim() || "";
  performanceImportWizard.validationError = "";

  try {
    // V5.21H : libère d'abord l'espace occupé par les anciennes copies redondantes
    // (files / preview / conflicts) avant d'écrire le nouvel état Performance.
    compactPerformanceImportHistoryForStorage();

    const imported = applyPerformanceImportRows(selectedRows, first, importDate);
    persist("performance");

    const conflictRows = performanceImportWizard.preview.filter(x => x.status === "Conflit" || x.status === "Différente");
    const payload = compactPerformanceImportPayload({
      id: performanceImportWizard.id,
      importDate,
      sourceFile: performanceImportWizard.files.map(f => f.name).join(", "),
      sourceType: first.source || first.typeDetected || "Source à confirmer",
      period: [...new Set(performanceImportWizard.preview.map(x => x.period).filter(Boolean))].join(", "),
      site: first.site || "",
      indicators: performanceImportWizard.preview,
      detectedCount: performanceImportWizard.preview.length,
      status,
      validatedBy,
      comments,
      importedCount: imported.importedCount,
      ignoredCount: performanceImportWizard.preview.length - imported.importedCount,
      conflictCount: conflictRows.length,
      periods: imported.periods,
      updatedMetricLabels: imported.updatedMetricLabels
    });
    const containsCgtab = performanceImportWizard.preview.some(row => /CGTAB/i.test(String(row.source || row.sourceType || "")));
    if (containsCgtab) payload.privacyAudit = performancePrivacyAuditForSensitiveData();
    state.performance_imports.unshift(payload);
    persist("performance_imports");
    addActivity("Performance", "Import de données", `${payload.status} · ${payload.sourceFile}`, payload.id);
    performanceImportWizard = null;
    renderPerformance();
  } catch (error) {
    try {
      state.performance = JSON.parse(previousPerformance);
      persist("performance");
    } catch (rollbackError) {
      console.error("[DEOS][Performance] Rollback impossible", rollbackError);
    }
    console.error("[DEOS][Performance] Validation import impossible", error);
    performanceImportWizard.validationError = performanceImportQuotaMessage(error);
    renderPerformanceImportWizard();
  }
}

function performancePrivacyAuditForSensitiveData() {
  const patterns = [/matricule/i, /nomprenom/i, /date.?nai/i, /matr\.?\s*baps/i, /code\s*sal/i, /salari[ée]/i];
  const matchSensitive = value => patterns.some(regex => regex.test(String(value || "")));
  const scan = value => {
    if (value === null || value === undefined) return false;
    if (typeof value === "string" || typeof value === "number" || typeof value === "boolean") return matchSensitive(value);
    if (Array.isArray(value)) return value.some(scan);
    return Object.entries(value).some(([key, val]) => matchSensitive(key) || scan(val));
  };
  const perfLeak = scan(state.performance || []);
  const importsLeak = scan(state.performance_imports || []);
  const localPerf = deosDataService.loadRaw("performance", "") || "";
  const localImports = deosDataService.loadRaw("performance_imports", "") || "";
  const localLeak = patterns.some(regex => regex.test(localPerf) || regex.test(localImports));
  return {
    checkedAt: new Date().toISOString(),
    leaked: Boolean(perfLeak || importsLeak || localLeak),
    checks: {
      statePerformance: !perfLeak,
      statePerformanceImports: !importsLeak,
      localStoragePerformance: !localLeak
    }
  };
}

function performanceImportHistory() {
  const rows = state.performance_imports.map(item => `<tr class="clickable" onclick="openPerformanceImportDetail('${esc(item.id)}')"><td>${esc(item.importDate || "")}</td><td>${esc(item.sourceFile || "")}</td><td>${esc(item.sourceType || "")}</td><td>${esc(item.site || "")}</td><td>${esc(item.period || "à confirmer")}</td><td>${esc(item.detectedCount ?? ensureArray(item.indicators).length)}</td><td>${esc(item.importedCount ?? "")}</td><td>${esc(item.conflictCount ?? ensureArray(item.conflicts).length)}</td><td>${esc(item.status || "brouillon")}</td></tr>`).join("");
  return `<h2>Historique des imports</h2><table class="perf-table"><thead><tr><th>Date</th><th>Fichier</th><th>Source</th><th>Site</th><th>Période</th><th>Détectés</th><th>Importés</th><th>Conflits</th><th>Statut</th></tr></thead><tbody>${rows || `<tr><td colspan="9">Aucun import enregistré.</td></tr>`}</tbody></table>`;
}

function openPerformanceImportDetail(id) {
  const item = byId("performance_imports", id);
  if (!item) return renderPerformance();
  const rows = ensureArray(item.indicators).slice(0, 80).map(row => `<tr><td>${esc(row.period || "")}</td><td>${esc(row.indicator || "")}</td><td>${esc(row.value || "")}</td><td>${esc(row.destinationLabel || row.destination || "KPI complémentaire")}</td><td>${esc(row.confidence || "")}</td><td>${esc(row.status || "")}</td></tr>`).join("");
  appHtml(`<div class="card hero report-hero"><button class="secondary" onclick="renderPerformance()">Retour Performance</button><h2>Détail import Performance</h2><p>${esc(item.sourceType || "")} · ${esc(item.sourceFile || "")} · ${esc(item.importDate || "")}</p><span class="meta">Site ${esc(item.site || "à confirmer")} · Période(s) ${esc(item.period || "")} · Validé par ${esc(item.validatedBy || "")}</span></div><div class="card"><h2>Indicateurs détectés</h2><table class="perf-table"><thead><tr><th>Période</th><th>Indicateur</th><th>Valeur</th><th>Destination</th><th>Confiance</th><th>Statut</th></tr></thead><tbody>${rows || `<tr><td colspan="6">Aucun détail disponible.</td></tr>`}</tbody></table></div>`);
}

async function analyzePerformanceImportFile(file, sourceKey) {
  const detected = detectPerformanceImportFile(file);
  detected.selectedPeriods = ensureArray(detected.periods).length ? ensureArray(detected.periods) : (detected.period ? [detected.period] : []);
  const shouldAnalyzeGpo = sourceKey === "gpo" || (sourceKey === "guide" && (detected.extension || "").toLowerCase() === "pdf");
  if (shouldAnalyzeGpo) {
    try {
      return await analyzeGpoPdfFile(file, detected);
    } catch (error) {
      performanceImportWizard.errors.push({ title: "Analyse GPO PDF impossible", detail: error.message || String(error) });
      return { ...detected, status: "non reconnu", confidence: "faible", message: error.message || "PDF non exploitable" };
    }
  }
  if (sourceKey === "ga") {
    try {
      return isGaDetailFileName(file.name || detected.name || "")
        ? await analyzeGaDetailAggregatedFile(file, detected)
        : await analyzeSuiviGaFile(file, detected);
    } catch (error) {
      performanceImportWizard.errors.push({ title: "Analyse Suivi GA impossible", detail: error.message || String(error) });
      return { ...detected, status: "non reconnu", confidence: "faible", message: error.message || "fichier GA non exploitable" };
    }
  }
  if (sourceKey === "cgtab") {
    try {
      return await analyzeCgtabFile(file, detected);
    } catch (error) {
      performanceImportWizard.errors.push({ title: "Analyse CGTAB impossible", detail: error.message || String(error) });
      return { ...detected, status: "non reconnu", confidence: "faible", message: error.message || "fichier CGTAB non exploitable" };
    }
  }
  if (sourceKey === "tbag") {
    try {
      return await analyzeTBagFile(file, detected);
    } catch (error) {
      performanceImportWizard.errors.push({ title: "Analyse T-Bag impossible", detail: error.message || String(error) });
      return { ...detected, status: "non reconnu", confidence: "faible", message: error.message || "fichier T-Bag non exploitable" };
    }
  }
  if (sourceKey !== "zgemed") return detected;
  try {
    return await analyzeZGemedFile(file, detected);
  } catch (error) {
    performanceImportWizard.errors.push({ title: "Analyse Z GEMED impossible", detail: error.message || String(error) });
    return { ...detected, status: "non reconnu", confidence: "faible", message: error.message || "fichier non exploitable" };
  }
}

function gpoIsSiteSectionPage(page = {}) {
  const text = normalizeText(String(page.text || ""));
  return /(?:^|\s)\d{1,2}\s+(?:entrepot|site)\s+(?:de\s+)?[a-z0-9][a-z0-9 '\-]+/i.test(text);
}

function gpoIsSaintGillesSectionPage(page = {}) {
  const text = normalizeText(String(page.text || ""));
  return /(?:^|\s)\d{1,2}\s+(?:entrepot|site)\s+(?:de\s+)?(?:saint|st)[\s\-]*gilles\b/i.test(text)
    || /\b(?:entrepot|site)\s+(?:de\s+)?(?:saint|st)[\s\-]*gilles\b/i.test(text);
}

function gpoScopeSaintGillesPages(pages = []) {
  const allPages = ensureArray(pages);
  const startIndex = allPages.findIndex(gpoIsSaintGillesSectionPage);

  if (startIndex >= 0) {
    let endIndex = allPages.length;
    for (let i = startIndex + 1; i < allPages.length; i++) {
      if (gpoIsSiteSectionPage(allPages[i]) && !gpoIsSaintGillesSectionPage(allPages[i])) {
        endIndex = i;
        break;
      }
    }
    return {
      status: "ok",
      pages: allPages.slice(startIndex, endIndex),
      startPage: allPages[startIndex]?.page || "",
      endPage: allPages[endIndex - 1]?.page || allPages[startIndex]?.page || "",
      mode: "regional-section"
    };
  }

  const fullText = allPages.map(page => page.text || "").join("\n");
  if (/\b(?:SAINT|ST)[\s\-]*GILLES\b/i.test(fullText) && allPages.length <= 40) {
    return {
      status: "ok",
      pages: allPages,
      startPage: allPages[0]?.page || 1,
      endPage: allPages[allPages.length - 1]?.page || allPages.length,
      mode: "single-site"
    };
  }

  return { status: "missing", pages: [], startPage: "", endPage: "", mode: "blocked" };
}

async function analyzeGpoPdfFile(file, detected) {
  if ((detected.extension || "").toLowerCase() !== "pdf") {
    return { ...detected, status: "non reconnu", confidence: "faible", message: "Format non supporté pour GPO PDF." };
  }

  const pages = await readPdfPages(file);
  const allText = pages.map(p => p.text).join("\n");
  const detectedPeriod = detectGpoPeriod(allText, file.name);
  const period = detectedPeriod || IMPORT_PERIOD_PENDING;
  const scoped = gpoScopeSaintGillesPages(pages);

  if (scoped.status !== "ok" || !scoped.pages.length) {
    return {
      ...detected,
      source: "GPO PDF",
      sourceType: "GPO PDF",
      status: "non reconnu",
      confidence: "faible",
      site: "",
      period,
      periods: [period],
      selectedPeriods: [period],
      sheets: [],
      detectedIndicators: [],
      message: "Import bloqué : section Saint-Gilles non détectée de manière fiable dans le GPO."
    };
  }

  const scopedText = scoped.pages.map(p => p.text).join("\n");
  const markers = ["Passage IPO total","Passage IPO Variable","Mensu IPO","Performance mensuelle","Evolution HEURES","Absentéisme","Gains & Pertes","HAUTEUR PALETTE"];
  const hitCount = markers.filter(marker => normalizeText(scopedText).includes(normalizeText(marker))).length;
  const indicators = extractGpoIndicators(scoped.pages, period);

  return {
    ...detected,
    source: "GPO PDF",
    sourceType: "GPO PDF régional",
    status: hitCount >= 4 && indicators.length ? "reconnu" : indicators.length ? "probablement reconnu" : "non reconnu",
    confidence: hitCount >= 4 && indicators.length ? "élevée" : indicators.length ? "moyenne" : "faible",
    site: "Saint-Gilles",
    scope: "FRY8MC",
    period,
    periods: [period],
    selectedPeriods: [period],
    sheets: scoped.pages.map(p => `page ${p.page}`).slice(0, 6),
    detectedIndicators: indicators,
    message: `${indicators.length} KPI GPO extrait(s) après isolement strict Saint-Gilles / FRY8MC · pages ${scoped.startPage} à ${scoped.endPage} sur ${pages.length} page(s).`
  };
}

function pdfLayoutTextFromItems(items = []) {
  const positioned = ensureArray(items).map((item, index) => ({
    text: String(item?.str || "").trim(),
    x: Number(item?.transform?.[4] || 0),
    y: Number(item?.transform?.[5] || 0),
    index
  })).filter(item => item.text);
  if (!positioned.length) return "";

  // Les GPO sont des pages très graphiques. L'ordre natif de getTextContent()
  // suit souvent l'ordre interne du PDF et non l'ordre visuel. On reconstruit
  // donc des lignes par coordonnée Y, puis on trie de gauche à droite.
  const lines = [];
  const yTolerance = 2.8;
  positioned.sort((a, b) => (b.y - a.y) || (a.x - b.x) || (a.index - b.index));
  positioned.forEach(item => {
    let line = lines.find(candidate => Math.abs(candidate.y - item.y) <= yTolerance);
    if (!line) {
      line = { y: item.y, items: [] };
      lines.push(line);
    }
    line.items.push(item);
  });
  lines.sort((a, b) => b.y - a.y);
  return lines.map(line => line.items
    .sort((a, b) => (a.x - b.x) || (a.index - b.index))
    .map(item => item.text)
    .join(" ")
    .replace(/\s+/g, " ")
    .trim())
    .filter(Boolean)
    .join("\n");
}

async function readPdfPages(file) {
  if (!window.pdfjsLib) {
    const pdfjs = await import("./libs/pdf.min.mjs");
    window.pdfjsLib = pdfjs;
    pdfjs.GlobalWorkerOptions.workerSrc = "./libs/pdf.worker.min.mjs";
  }
  const bytes = await readFileArrayBuffer(file);
  const pdf = await window.pdfjsLib.getDocument({ data: bytes }).promise;
  const pages = [];
  for (let pageNo = 1; pageNo <= pdf.numPages; pageNo++) {
    const page = await pdf.getPage(pageNo);
    const content = await page.getTextContent();
    const rawText = content.items.map(item => item.str || "").join(" ");
    const layoutText = pdfLayoutTextFromItems(content.items);
    const viewport = page.getViewport({ scale: 1 });
    const layoutItems = ensureArray(content.items).map((item, index) => ({
      text: String(item?.str || "").trim(),
      x: Number(item?.transform?.[4] || 0),
      yTop: Number(viewport.height || 0) - Number(item?.transform?.[5] || 0),
      index
    })).filter(item => item.text);
    pages.push({ page: pageNo, text: `${rawText}\n${layoutText}`.trim() || rawText, rawText, layoutText, layoutItems, width: viewport.width, height: viewport.height });
  }
  return pages;
}

function detectGpoPeriod(text, fileName = "") {
  const source = `${text}\n${fileName}`;
  const numeric = source.match(/\b(0?[1-9]|1[0-2])\s*[\/.-]\s*(20\d{2})\b/);
  if (numeric) return `${String(Number(numeric[1])).padStart(2, "0")}/${numeric[2]}`;
  const hit = source.match(/\b(janvier|février|fevrier|mars|avril|mai|juin|juillet|août|aout|septembre|octobre|novembre|décembre|decembre)\s*(20\d{2})\b/i);
  if (!hit) {
    const fromName = detectImportPeriod(fileName);
    return normalizeImportPeriod(fromName);
  }
  const idx = ["janvier", "février", "fevrier", "mars", "avril", "mai", "juin", "juillet", "août", "aout", "septembre", "octobre", "novembre", "décembre", "decembre"].findIndex(m => normalizeText(m) === normalizeText(hit[1]));
  const monthMap = { janvier: 1, fevrier: 2, mars: 3, avril: 4, mai: 5, juin: 6, juillet: 7, aout: 8, septembre: 9, octobre: 10, novembre: 11, decembre: 12 };
  const month = monthMap[normalizeText(hit[1])] || (idx + 1);
  return `${String(month).padStart(2, "0")}/${hit[2]}`;
}

function normalizeImportPeriod(period = "") {
  if (!period) return "";
  return canonicalPerformancePeriod(period) || period;
}

function gpoIndicatorRow(period, metric, values, sourcePage, confidence = "moyenne") {
  if (!metric || !values || values.actual === "" || values.actual === null || values.actual === undefined) return null;
  const target = performanceImportTargetById(metric.targetId);
  const destination = normalizeImportDestination(target?.path || "", metric.destinationField || "");
  return {
    id: newId("preview"),
    period,
    source: "GPO",
    sourceType: "GPO PDF",
    category: metric.category,
    scope: metric.scope || "global",
    metricKey: metric.metricKey,
    indicator: metric.label,
    label: metric.label,
    actual: values.actual,
    value: values.actual,
    budget: values.budget ?? null,
    historical: values.historical ?? null,
    unit: metric.unit,
    sourcePage,
    pageSource: sourcePage,
    sourceRef: sourcePage ? `PDF ${sourcePage}` : "",
    destinationPath: destination.path,
    destinationLabel: target?.label || metric.label,
    destinationField: destination.field,
    targetId: target?.id || "",
    destinationId: target?.id || "",
    targetType: target?.type || "ignore",
    confidence,
    selected: Boolean(target?.path),
    action: target?.path ? "" : "ignore"
  };
}


function gpoLayoutNumbers(page, { xMin = -Infinity, xMax = Infinity, yMin = -Infinity, yMax = Infinity } = {}) {
  return ensureArray(page?.layoutItems).map(item => ({
    ...item,
    value: parseZGemedNumber(item.text)
  })).filter(item => item.value !== "" && Number.isFinite(Number(item.value)) && item.x >= xMin && item.x <= xMax && item.yTop >= yMin && item.yTop <= yMax);
}

function gpoLayoutNearestNumber(page, x, y, { xTolerance = 28, yTolerance = 18, min = -Infinity, max = Infinity } = {}) {
  const candidates = gpoLayoutNumbers(page, { xMin: x - xTolerance, xMax: x + xTolerance, yMin: y - yTolerance, yMax: y + yTolerance })
    .filter(item => Number(item.value) >= min && Number(item.value) <= max)
    .sort((a, b) => (Math.abs(a.x - x) + Math.abs(a.yTop - y) * 1.8) - (Math.abs(b.x - x) + Math.abs(b.yTop - y) * 1.8));
  return candidates[0]?.value ?? "";
}

function gpoLayoutTriple(page, coords, range = {}) {
  return {
    historical: gpoLayoutNearestNumber(page, coords[0][0], coords[0][1], range),
    budget: gpoLayoutNearestNumber(page, coords[1][0], coords[1][1], range),
    actual: gpoLayoutNearestNumber(page, coords[2][0], coords[2][1], range)
  };
}

function gpoPlausibility(metricKey, values) {
  const rules = {
    "productivity.preparation": [50, 200],
    "productivity.reception": [5, 50],
    "productivity.manutention": [5, 50],
    "productivity.chargement": [5, 60],
    "productivity.transit": [0, 100],
    "hours.total": [10000, 1000000],
    "hours.direct": [10000, 1000000],
    "hours.indirect": [1000, 500000],
    "hours.indirect.share": [0, 100],
    "absenteeism.total": [0, 100],
    "absenteeism.maladie": [0, 100],
    "absenteeism.accident_travail": [0, 100],
    "absenteeism.formation": [0, 100],
    "absenteeism.conges": [0, 100],
    "absenteeism.autres": [0, 100],
    "quality.total_gains_pertes": [-10000, 10000],
    "pallet.height": [70, 130]
  };
  const rule = rules[metricKey];
  if (!rule) return { ok: true, score: 82 };
  const present = [values?.historical, values?.budget, values?.actual].filter(value => value !== "" && value !== null && value !== undefined).map(Number).filter(Number.isFinite);
  if (!present.length) return { ok: false, score: 25 };
  const ok = present.every(value => value >= rule[0] && value <= rule[1]);
  return { ok, score: ok ? 94 : 25 };
}

function gpoMetricConfidence(metricKey, values, layoutBased = false) {
  const check = gpoPlausibility(metricKey, values);
  if (!check.ok) return { label: "faible", score: 25, selected: false, action: "ignore", warning: "Valeur incohérente avec la plage métier" };
  const score = layoutBased ? 96 : Math.min(88, check.score);
  return { label: performanceImportConfidenceMeta(score).label, score, selected: true, action: "" };
}

function extractGpoSaintGillesLayout(page) {
  const text = String(page?.layoutText || page?.text || "");
  if (!ensureArray(page?.layoutItems).length) return null;
  const out = {};
  if (/Performance mensuelle/i.test(text)) {
    out.productivity_preparation = gpoLayoutTriple(page, [[179, 187], [202, 176], [225, 229]], { xTolerance: 24, yTolerance: 15, min: 50, max: 200 });
    out.productivity_reception = gpoLayoutTriple(page, [[270, 217], [293, 236], [316, 204]], { xTolerance: 24, yTolerance: 15, min: 5, max: 50 });
    out.productivity_manutention = gpoLayoutTriple(page, [[359, 224], [382, 219], [405, 209]], { xTolerance: 24, yTolerance: 15, min: 5, max: 50 });
    out.productivity_chargement = gpoLayoutTriple(page, [[449, 224], [472, 239], [495, 209]], { xTolerance: 24, yTolerance: 15, min: 5, max: 60 });
  }
  if (/Evolution HEURES/i.test(text)) {
    out.hours_total = gpoLayoutTriple(page, [[660, 166], [676, 181], [692, 147]], { xTolerance: 28, yTolerance: 16, min: 10000, max: 1000000 });
    out.hours_indirect = gpoLayoutTriple(page, [[660, 257], [676, 287], [692, 271]], { xTolerance: 28, yTolerance: 16, min: 1000, max: 500000 });
    if ([out.hours_total.historical, out.hours_total.budget, out.hours_total.actual, out.hours_indirect.historical, out.hours_indirect.budget, out.hours_indirect.actual].every(v => v !== "")) {
      out.hours_direct = {
        historical: Number(out.hours_total.historical) - Number(out.hours_indirect.historical),
        budget: Number(out.hours_total.budget) - Number(out.hours_indirect.budget),
        actual: Number(out.hours_total.actual) - Number(out.hours_indirect.actual)
      };
      out.hours_indirect_share = {
        historical: +(Number(out.hours_indirect.historical) / Number(out.hours_total.historical) * 100).toFixed(1),
        budget: +(Number(out.hours_indirect.budget) / Number(out.hours_total.budget) * 100).toFixed(1),
        actual: +(Number(out.hours_indirect.actual) / Number(out.hours_total.actual) * 100).toFixed(1)
      };
    }
  }
  if (/TAUX\s+D.?ABSENCE|Absentéisme|Absenteisme/i.test(text)) {
    out.absenteeism_total = gpoLayoutTriple(page, [[672, 127], [673, 173], [672, 224]], { xTolerance: 24, yTolerance: 14, min: 0, max: 100 });
    out.absenteeism_conges = gpoLayoutTriple(page, [[108, 173], [136, 173], [163, 173]], { xTolerance: 22, yTolerance: 12, min: 0, max: 100 });
    out.absenteeism_maladie = gpoLayoutTriple(page, [[214, 233], [241, 240], [269, 230]], { xTolerance: 22, yTolerance: 14, min: 0, max: 100 });
    out.absenteeism_accident_travail = gpoLayoutTriple(page, [[318, 239], [345, 242], [373, 231]], { xTolerance: 22, yTolerance: 14, min: 0, max: 100 });
    out.absenteeism_formation = gpoLayoutTriple(page, [[422, 253], [449, 253], [477, 252]], { xTolerance: 24, yTolerance: 12, min: 0, max: 100 });
    out.absenteeism_autres = gpoLayoutTriple(page, [[526, 248], [553, 243], [581, 244]], { xTolerance: 22, yTolerance: 14, min: 0, max: 100 });
  }
  if (/Gains\s*&\s*Pertes|G&P/i.test(text)) {
    out.gains_pertes = gpoLayoutTriple(page, [[66, 201], [96, 243], [331, 169]], { xTolerance: 32, yTolerance: 20, min: -10000, max: 10000 });
  }
  if (/HAUTEUR PALETTE|Hauteur Palette/i.test(text)) {
    out.pallet_height = gpoLayoutTriple(page, [[651, 353], [664, 340], [683, 333]], { xTolerance: 28, yTolerance: 16, min: 70, max: 130 });
    out.pallet_height.objective = gpoLayoutNearestNumber(page, 40, 337, { xTolerance: 24, yTolerance: 18, min: 70, max: 130 });
  }
  return Object.keys(out).length ? out : null;
}

function extractGpoIndicators(pages, period) {
  const rows = [];
  const gpoMetrics = {
    ipo_total: { metricKey: "ipo.total", label: "IPO total", targetId: "ipo.total", category: "IPO", unit: IPO_UNIT },
    ipo_variable: { metricKey: "ipo.variable", label: "IPO variable", targetId: "ipo.variable", category: "IPO", unit: IPO_UNIT },
    productivity_preparation: { metricKey: "productivity.preparation", label: "Productivité Préparation", targetId: "productivity.preparation", category: "Productivité", unit: "colis/h" },
    productivity_reception: { metricKey: "productivity.reception", label: "Productivité Réception", targetId: "productivity.reception", category: "Productivité", unit: "palettes/h" },
    productivity_manutention: { metricKey: "productivity.manutention", label: "Productivité Manutention", targetId: "productivity.manutention", category: "Productivité", unit: "palettes/h" },
    productivity_chargement: { metricKey: "productivity.chargement", label: "Productivité Chargement", targetId: "productivity.chargement", category: "Productivité", unit: "palettes/h" },
    productivity_transit: { metricKey: "productivity.transit", label: "Productivité Transit", targetId: "productivity.transit", category: "Productivité", unit: "palettes/h" },
    hours_total: { metricKey: "hours.total", label: "Heures totales", targetId: "hours.total", category: "Heures", unit: "heures" },
    hours_direct: { metricKey: "hours.direct", label: "Heures directes", targetId: "hours.direct", category: "Heures", unit: "heures" },
    hours_indirect: { metricKey: "hours.indirect", label: "Heures indirectes", targetId: "hours.indirect", category: "Heures", unit: "heures" },
    hours_indirect_share: { metricKey: "hours.indirect.share", label: "Poids heures indirectes", targetId: "hours.indirect_share", category: "Heures", unit: "pourcentage", destinationField: "totalShare" },
    absenteeism_total: { metricKey: "absenteeism.total", label: "Absentéisme total", targetId: "absenteeism.total", category: "Absentéisme", unit: "pourcentage" },
    absenteeism_maladie: { metricKey: "absenteeism.maladie", label: "Absentéisme maladie", targetId: "absenteeism.maladie", category: "Absentéisme", unit: "pourcentage" },
    absenteeism_accident_travail: { metricKey: "absenteeism.accident_travail", label: "Absentéisme accidents du travail", targetId: "absenteeism.accident_travail", category: "Absentéisme", unit: "pourcentage" },
    absenteeism_formation: { metricKey: "absenteeism.formation", label: "Absentéisme formation", targetId: "absenteeism.formation", category: "Absentéisme", unit: "pourcentage" },
    absenteeism_conges: { metricKey: "absenteeism.conges", label: "Absentéisme congés", targetId: "absenteeism.conges", category: "Absentéisme", unit: "pourcentage" },
    absenteeism_autres: { metricKey: "absenteeism.autres", label: "Absentéisme autres", targetId: "absenteeism.autres", category: "Absentéisme", unit: "pourcentage" },
    hours_gap_budget: { metricKey: "hours.total.budget_gap", label: "Écart heures vs Budget", targetId: "gpo.hours_gap_budget", category: "Heures", unit: "heures" },
    hours_gap_historical: { metricKey: "hours.total.historical_gap", label: "Écart heures vs Historique", targetId: "gpo.hours_gap_historical", category: "Heures", unit: "heures" }
  };
  const pushMetric = (page, metricId, values, confidence = "moyenne", layoutBased = false) => {
    const metric = gpoMetrics[metricId];
    const check = gpoMetricConfidence(metric?.metricKey || metricId, values, layoutBased);
    const row = gpoIndicatorRow(period, metric, values, `page ${page.page}`, check.label || confidence);
    if (row) {
      row.sourceConfidenceScore = check.score;
      row.validationWarning = check.warning || "";
      row.selected = check.selected;
      row.action = check.action;
      rows.push(row);
    }
  };
  pages.forEach(page => {
    const text = page.text;
    const layout = extractGpoSaintGillesLayout(page) || {};
    if (/Passage IPO total/i.test(text)) pushMetric(page, "ipo_total", extractGpoIpoValues(extractGpoSection(text, "Passage\\s+IPO\\s+total", 240)), "élevée");
    if (/Passage IPO Variable/i.test(text)) pushMetric(page, "ipo_variable", extractGpoIpoValues(extractGpoSection(text, "Passage\\s+IPO\\s+Variable", 240)), "élevée");
    if (/Performance mensuelle/i.test(text)) {
      pushMetric(page, "productivity_preparation", layout.productivity_preparation || extractGpoTripleAround(extractGpoSection(text, "PRÉPARATION|PREPARATION", 180), "PRÉPARATION|PREPARATION", { preferDecimal: true }), "moyenne", Boolean(layout.productivity_preparation));
      pushMetric(page, "productivity_reception", layout.productivity_reception || extractGpoTripleAround(extractGpoSection(text, "RÉCEPTION|RECEPTION", 180), "RÉCEPTION|RECEPTION", { preferDecimal: true }), "moyenne", Boolean(layout.productivity_reception));
      pushMetric(page, "productivity_manutention", layout.productivity_manutention || extractGpoTripleAround(extractGpoSection(text, "MANUTENTION", 180), "MANUTENTION", { preferDecimal: true }), "moyenne", Boolean(layout.productivity_manutention));
      pushMetric(page, "productivity_chargement", layout.productivity_chargement || extractGpoTripleAround(extractGpoSection(text, "CHARGEMENT", 180), "CHARGEMENT", { preferDecimal: true }), "moyenne", Boolean(layout.productivity_chargement));
      if (/TRANSIT|TRANSPORT/i.test(text)) pushMetric(page, "productivity_transit", extractGpoTripleAround(extractGpoSection(text, "TRANSIT|TRANSPORT", 180), "TRANSIT|TRANSPORT", { preferDecimal: true }), "faible");
    }
    if (/Evolution HEURES/i.test(text)) {
      const hoursValues = extractGpoHoursValues(text);
      const totalValues = layout.hours_total || hoursValues.total;
      const directValues = layout.hours_direct || hoursValues.direct;
      const indirectValues = layout.hours_indirect || hoursValues.indirect;
      pushMetric(page, "hours_total", totalValues, "moyenne", Boolean(layout.hours_total));
      pushMetric(page, "hours_direct", directValues, "moyenne", Boolean(layout.hours_direct));
      pushMetric(page, "hours_indirect", indirectValues, "moyenne", Boolean(layout.hours_indirect));
      if (totalValues.actual !== "" && totalValues.budget !== "") pushMetric(page, "hours_gap_budget", { actual: Number(totalValues.actual) - Number(totalValues.budget), budget: null, historical: null }, "faible");
      if (totalValues.actual !== "" && totalValues.historical !== "") pushMetric(page, "hours_gap_historical", { actual: Number(totalValues.actual) - Number(totalValues.historical), budget: null, historical: null }, "faible");
      const pctValues = layout.hours_indirect_share || null;
      if (pctValues) pushMetric(page, "hours_indirect_share", pctValues, "moyenne", true);
      else { const pct = extractGpoIndirectPercent(text); if (pct !== "") pushMetric(page, "hours_indirect_share", { actual: pct, budget: null, historical: null }, "faible"); }
    }
    if (/TAUX\s+D.?ABSENCE|Absentéisme|Absenteisme/i.test(text)) {
      pushMetric(page, "absenteeism_total", layout.absenteeism_total || extractGpoAbsTotal(text), "moyenne", Boolean(layout.absenteeism_total));
      pushMetric(page, "absenteeism_maladie", layout.absenteeism_maladie || extractGpoAbsDetail(text, "MALADIE"), "faible", Boolean(layout.absenteeism_maladie));
      pushMetric(page, "absenteeism_accident_travail", layout.absenteeism_accident_travail || extractGpoAbsDetail(text, "ACCIDENT(?:S)?\s+DU\s+TRAVAIL|AT"), "faible", Boolean(layout.absenteeism_accident_travail));
      pushMetric(page, "absenteeism_formation", layout.absenteeism_formation || extractGpoAbsDetail(text, "FORMATION"), "faible", Boolean(layout.absenteeism_formation));
      pushMetric(page, "absenteeism_conges", layout.absenteeism_conges || extractGpoAbsDetail(text, "CONGE|CONGÉ"), "faible", Boolean(layout.absenteeism_conges));
      pushMetric(page, "absenteeism_autres", layout.absenteeism_autres || extractGpoAbsDetail(text, "AUTRES?"), "faible", Boolean(layout.absenteeism_autres));
    }
    if (/Heures majorées|Heures majorees/i.test(text)) {
      const major = extractGpoMajorHours(text);
      ["night", "overtime", "sundays"].forEach(key => {
        if (major[key] !== "") {
          const targetId = ({ night: "hours.night", overtime: "hours.overtime", sundays: "hours.sundays" })[key];
          const target = performanceImportTargetById(targetId);
          rows.push({ id: newId("preview"), period, indicator: ({ night: "Heures de nuit cumul", overtime: "Heures supplémentaires cumul", sundays: "Dimanches / fériés cumul" })[key], label: ({ night: "Heures de nuit cumul", overtime: "Heures supplémentaires cumul", sundays: "Dimanches / fériés cumul" })[key], metricKey: targetId, category: "Heures", value: major[key], actual: major[key], unit: "h", source: "GPO", sourceType: "GPO PDF", pageSource: `page ${page.page}`, sourceRef: `PDF page ${page.page}`, destinationPath: target?.path || "hours", destinationLabel: target?.label || ({ night: "Heures de nuit cumul", overtime: "Heures supplémentaires cumul", sundays: "Dimanches / fériés cumul" })[key], destinationField: target?.destinationField || key, targetId, destinationId: targetId, targetType: "existing", confidence: "moyenne", selected: true, action: "" });
        }
      });
    }
    if (/Gains\s*&\s*Pertes|G&P/i.test(text)) {
      const gp = layout.gains_pertes || extractGpoGpValues(text);
      const check = gpoMetricConfidence("quality.total_gains_pertes", gp, Boolean(layout.gains_pertes));
      rows.push({ id: newId("preview"), period, indicator: "Total Gains & Pertes", label: "Total Gains & Pertes", metricKey: "quality.total_gains_pertes", category: "Qualité", actual: gp.actual, value: gp.actual, budget: gp.budget ?? null, historical: gp.historical ?? null, unit: "k€", scope: "global", source: "GPO", sourceType: "GPO PDF", sourcePage: `page ${page.page}`, pageSource: `page ${page.page}`, sourceRef: `PDF page ${page.page}`, destinationPath: "quality.indicators.Total Gains & Pertes.actual", destinationLabel: "Total Gains & Pertes", confidence: check.label, sourceConfidenceScore: check.score, validationWarning: check.warning || "", selected: check.selected, action: check.action });
    }
    if (/HAUTEUR PALETTE|Hauteur Palette/i.test(text)) {
      const values = layout.pallet_height || extractGpoPalletValues(text);
      const check = gpoMetricConfidence("pallet.height", values, Boolean(layout.pallet_height));
      if (values.actual !== "") rows.push({ id: newId("preview"), period, indicator: "Hauteur Palette", label: "Hauteur palette", metricKey: "pallet.height", category: "Hauteur palette", actual: values.actual, value: values.actual, budget: values.budget ?? null, historical: values.historical ?? null, objective: values.objective ?? null, unit: "", scope: "global", source: "GPO", sourceType: "GPO PDF", sourcePage: `page ${page.page}`, pageSource: `page ${page.page}`, sourceRef: `PDF page ${page.page}`, destinationPath: "palletHeight.actual", destinationLabel: "Hauteur palette", confidence: check.label, sourceConfidenceScore: check.score, validationWarning: check.warning || "", selected: check.selected, action: check.action });
    }
  });
  return dedupeImportRows(rows);
}

function extractGpoSection(text, markerPattern, span = 260) {
  const source = String(text || "");
  const regex = new RegExp(markerPattern, "i");
  const match = regex.exec(source);
  if (!match) return source;
  return source.slice(Math.max(0, match.index), Math.min(source.length, match.index + span));
}

function gpoNumbers(text) {
  const tokens = [...String(text || "").matchAll(/[+-]?\s?\d+(?:[,.]\d+)?/g)].map(m => m[0]);
  const values = [];
  for (let i = 0; i < tokens.length; i++) {
    const current = tokens[i];
    const next = tokens[i + 1] || "";
    const currentDigits = current.replace(/[^\d]/g, "");
    const nextDigits = next.replace(/[^\d]/g, "");
    const isDecimal = /[,.]\d+/.test(current);
    if (!isDecimal && currentDigits.length <= 3 && nextDigits.length === 3 && !/[,.]\d+/.test(next)) {
      values.push(parseZGemedNumber(`${current}${nextDigits}`));
      i += 1;
    } else {
      values.push(parseZGemedNumber(current));
    }
  }
  return values;
}

function extractGpoIpoValues(text) {
  // Sur le GPO Saint-Gilles, les valeurs des trois barres sont visuellement
  // placées AU-DESSUS des libellés IPO BUDGET / RÉALISÉ / HISTO.
  // Le fallback "after" reste utile si le modèle PDF évolue.
  const around = regex => {
    const before = matchNumberBefore(text, regex);
    return before !== "" ? before : matchNumberAfter(text, regex);
  };
  const h = around(/IPO\s*HISTO/i);
  const b = around(/IPO\s*BUDGET/i);
  const r = around(/IPO\s*R[ÉE]ALIS[ÉE]/i);
  return { historical: h, budget: b, actual: r };
}

function extractGpoTripleNear(text, labelPattern) {
  const re = new RegExp(`(${labelPattern})([\\s\\S]{0,160})`, "i");
  const after = (text.match(re) || [])[2] || "";
  const nums = gpoNumbers(after).filter(v => v !== "");
  return { historical: nums[0] ?? "", budget: nums[1] ?? "", actual: nums[2] ?? "" };
}

function extractGpoTripleAround(text, labelPattern, options = {}) {
  const re = new RegExp(labelPattern, "i");
  const source = String(text);
  const matches = [...source.matchAll(new RegExp(labelPattern, "ig"))];
  const candidates = matches.length ? matches : [];
  const match = candidates.find(item => {
    if (!options.preferDecimal) return true;
    const beforeNums = gpoNumbers(source.slice(Math.max(0, item.index - 90), item.index)).filter(v => v !== "");
    const nums = beforeNums.slice(-3);
    return nums.length >= 3 && nums.every(v => Math.abs(Number(v)) < 1000) && nums.filter(v => !Number.isInteger(Number(v))).length >= 2;
  }) || candidates[0];
  if (!match) return { historical: "", budget: "", actual: "" };
  const before = source.slice(Math.max(0, match.index - 90), match.index);
  const after = source.slice(match.index + match[0].length, match.index + match[0].length + 90);
  const beforeNums = gpoNumbers(before).filter(v => v !== "");
  if (beforeNums.length >= 3) {
    const nums = beforeNums.slice(-3);
    return { historical: nums[0], budget: nums[1], actual: nums[2] };
  }
  const afterNums = gpoNumbers(after).filter(v => v !== "");
  return { historical: afterNums[0] ?? "", budget: afterNums[1] ?? "", actual: afterNums[2] ?? "" };
}

function extractGpoHoursValues(text) {
  const idx = String(text).search(/HEURES\s+TOTALES/i);
  if (idx < 0) return { total: { historical: "", budget: "", actual: "" }, direct: { historical: "", budget: "", actual: "" }, indirect: { historical: "", budget: "", actual: "" } };
  const segment = String(text).slice(Math.max(0, idx - 240), idx);
  const nums = [...segment.matchAll(/[+-]?\s?\d{1,3}\s\d{3}/g)].map(match => parseZGemedNumber(match[0])).filter(v => v !== "").slice(-9);
  const groups = nums.length >= 9 ? [nums.slice(0, 3), nums.slice(3, 6), nums.slice(6, 9)] : [];
  const toValues = values => ({ historical: values?.[0] ?? "", budget: values?.[1] ?? "", actual: values?.[2] ?? "" });
  return { total: toValues(groups[0]), direct: toValues(groups[1]), indirect: toValues(groups[2]) };
}

function extractGpoAbsDetail(text, labelPattern) {
  const re = new RegExp(`${labelPattern}([\\s\\S]{0,180})`, "i");
  const segment = (String(text).match(re) || [])[1] || "";
  const nums = gpoNumbers(segment).filter(v => v !== "").slice(0, 3);
  if (!nums.length) return { historical: "", budget: "", actual: "" };
  return { historical: nums[0] ?? "", budget: nums[1] ?? "", actual: nums[2] ?? nums[0] ?? "" };
}

function extractGpoTripleAfter(text, labelPattern) {
  const re = new RegExp(`${labelPattern}([\\s\\S]{0,260})HISTO\\s+BUD\\s+REEL([\\s\\S]{0,160})`, "i");
  const target = (text.match(re) || [])[2] || (text.match(new RegExp(`${labelPattern}([\\s\\S]{0,260})`, "i")) || [])[1] || "";
  const nums = gpoNumbers(target).filter(v => v !== "");
  return { historical: nums[0] ?? "", budget: nums[1] ?? "", actual: nums[2] ?? "" };
}

function extractGpoAbsTotal(text) {
  const segment = (text.match(/TAUX\s+D.?ABSENCE([\s\S]{0,220})HISTO\s+BUDGET\s+REEL/i) || [])[1] || text;
  const nums = gpoNumbers(segment).filter(v => v !== "");
  return { historical: nums[0] ?? "", budget: nums[1] ?? "", actual: nums[2] ?? "" };
}

function extractGpoGpValues(text) {
  // La page Gains & Pertes place les valeurs au-dessus des libellés G&P H/B/R.
  // On préfère donc le nombre précédent et on conserve un fallback arrière.
  const around = regex => {
    const before = matchNumberBefore(text, regex);
    return before !== "" ? before : matchNumberAfter(text, regex);
  };
  const h = around(/G&P\s*H/i);
  const b = around(/G&P\s*B/i);
  const r = around(/G&P\s*R/i);
  return { historical: h, budget: b, actual: r };
}

function extractGpoPalletValues(text) {
  const objective = matchNumberAfter(text, /Objectif annuel/i);
  const idx = text.search(/HISTO\s+BUD\s+REEL/i);
  const segment = idx >= 0 ? text.slice(Math.max(0, idx - 160), idx) : text;
  const nums = gpoNumbers(segment).filter(v => v !== "").slice(-3);
  return { historical: nums[0] ?? "", budget: nums[1] ?? "", actual: nums[2] ?? "", objective };
}

function extractGpoIndirectPercent(text) {
  const segment = (text.match(/% HEURES\s+INDIRECTES\s+TOTALES([\s\S]{0,220})Cumul/i) || [])[1] || "";
  const nums = gpoNumbers(segment).filter(v => v !== "");
  return nums.length ? nums[nums.length - 1] : "";
}

function extractGpoMajorHours(text) {
  const blocks = [...String(text).matchAll(/Cumul\s+à\s+date\s+([+-]?\s?\d+(?:\s\d{3})?)\s+([+-]?\s?\d+(?:\s\d{3})?)/gi)];
  const actual = index => blocks[index] ? parseZGemedNumber(blocks[index][2]) : "";
  return { night: actual(0), overtime: actual(1), sundays: actual(2) };
}

function matchNumberAfter(text, regex) {
  const idx = String(text).search(regex);
  if (idx < 0) return "";
  const nums = gpoNumbers(String(text).slice(idx, idx + 120)).filter(v => v !== "");
  return nums[0] ?? "";
}

function matchNumberBefore(text, regex) {
  const match = regex.exec(String(text));
  if (!match) return "";
  const nums = gpoNumbers(String(text).slice(Math.max(0, match.index - 70), match.index)).filter(v => v !== "");
  return nums[nums.length - 1] ?? "";
}

function matchNumberAround(text, regex) {
  const match = regex.exec(String(text));
  if (!match) return "";
  const before = gpoNumbers(String(text).slice(Math.max(0, match.index - 50), match.index)).filter(v => v !== "");
  if (before.length) return before[before.length - 1];
  const after = gpoNumbers(String(text).slice(match.index, match.index + 120)).filter(v => v !== "");
  return after[0] ?? "";
}

const CGTAB_ST_GILLES_KNOWN_SHA256 = "6001F182CDE70C9D14EC3438E6941D22F59E129C4639501E03738DCEDAAA6BE7";
const CGTAB_EXCLUDED_NOMINATIVE_COLUMNS = ["Matricule", "NomPrenom", "DateNai", "Matr.BAPS", "Code Sal."];
const TBAG_SENSITIVE_MARKERS = ["Matricule", "NomPrenom", "DateNai", "Matr.BAPS", "Code Sal.", "Identifiant salarié"];

function tbagSlug(value = "") {
  const normalized = normalizePerformanceLabel(String(value || "")).replace(/[^a-z0-9]+/g, "_").replace(/^_+|_+$/g, "");
  return normalized || "unknown";
}

function tbagReadCell(sheet, row1Based, col1Based) {
  const ref = window.XLSX.utils.encode_cell({ r: row1Based - 1, c: col1Based - 1 });
  return sheet[ref] || null;
}

function tbagCellText(sheet, row1Based, col1Based) {
  const cell = tbagReadCell(sheet, row1Based, col1Based);
  if (!cell) return "";
  const value = cell.w ?? cell.v ?? "";
  return String(value || "").trim();
}

function tbagCellNumber(sheet, row1Based, col1Based) {
  const cell = tbagReadCell(sheet, row1Based, col1Based);
  if (!cell) return null;
  const numeric = normalizeImportNullableNumericValue(cell.v);
  return typeof numeric === "number" && Number.isFinite(numeric) ? numeric : null;
}

function tbagCellFormula(sheet, row1Based, col1Based) {
  const cell = tbagReadCell(sheet, row1Based, col1Based);
  return cell?.f ? `=${cell.f}` : "";
}

function tbagCanonicalPeriod(mmToken = "", year = "") {
  const hit = String(mmToken || "").match(/MM[-_ ]?(\d{1,2})/i);
  if (!hit) return "";
  const mm = String(Number(hit[1])).padStart(2, "0");
  const yyyy = String(year || "").trim();
  if (!/^(20\d{2})$/.test(yyyy)) return "";
  return `${mm}/${yyyy}`;
}

function tbagDestinationPath(metricKey = "", population = "", banner = "") {
  const metricPart = normalizePerformanceLabel(metricKey).replace(/\s+/g, "_") || "metric";
  const popPart = population ? `.pop_${tbagSlug(population)}` : "";
  const bannerPart = banner ? `.banner_${tbagSlug(banner)}` : "";
  return `complementary.tbag.${metricPart}${popPart}${bannerPart}`;
}

function tbagIdentityKey(population = "", banner = "") {
  const pop = population ? `pop:${tbagSlug(population)}` : "pop:all";
  const ban = banner ? `banner:${tbagSlug(banner)}` : "banner:all";
  return `${pop}|${ban}`;
}

function tbagBuildRow({ period, metricKey, label, value, unit, population = "", banner = "", aggregationType = "sum", confidence = "élevée", sourceSheet, sourceCell, sourceColumns, sourceFormula = "" }) {
  const isTotalScope = String(population || "").trim().toUpperCase() === "TOTAL"
    && String(banner || "").trim().toUpperCase() === "TOTAL BANNIERE";
  const isNativeProductivityTotal = metricKey === "preparation.productivity.total" && isTotalScope;
  const isBannerHoursDetail = metricKey === "preparation.banner.hours";
  const destinationPath = isNativeProductivityTotal
    ? "productivity.Préparation.actual"
    : tbagDestinationPath(metricKey, population, banner);
  const destinationLabel = isNativeProductivityTotal
    ? "Productivité Préparation"
    : `${label} · Préparation`;
  const targetId = isNativeProductivityTotal
    ? "productivity.preparation"
    : destinationPath;
  const targetType = isNativeProductivityTotal ? "existing" : "complementary";
  const category = metricKey.includes("productivity") ? "preparation_productivity" : metricKey.includes("volume") ? "preparation_volume" : "preparation_hours";
  return {
    id: newId("preview"),
    period,
    periodType: "monthly",
    source: "T_BAG",
    sourceType: "T-Bag XLSB",
    category,
    metricKey,
    indicator: label,
    label,
    actual: normalizeImportNullableNumericValue(value),
    value: normalizeImportNullableNumericValue(value),
    budget: null,
    historical: null,
    unit,
    scope: "Préparation",
    population,
    banner,
    directness: banner || "",
    costCenter: tbagIdentityKey(population, banner),
    aggregationType,
    employeeCount: null,
    sourceColumns,
    sourceFormula,
    privacyLevel: "aggregated",
    confidence,
    sourceSheet,
    sourceCell,
    sourceRef: `${sourceSheet} · ${sourceCell}`,
    destinationPath,
    destinationLabel,
    destinationId: targetId,
    targetId,
    targetType,
    analyticalRole: isBannerHoursDetail ? "detail" : (isTotalScope ? "total" : "analytic"),
    analysisOnly: isBannerHoursDetail,
    selected: true,
    action: ""
  };
}

function tbagFindPrimarySheet(workbook) {
  const names = ensureArray(workbook?.SheetNames || []);
  for (const name of names) {
    const sheet = workbook.Sheets?.[name];
    if (!sheet || !sheet["!ref"]) continue;
    for (let r = 1; r <= 8; r++) {
      const a = tbagCellText(sheet, r, 1).toUpperCase();
      const b = tbagCellText(sheet, r, 2).toUpperCase();
      const c = tbagCellText(sheet, r, 3).toUpperCase();
      const d = tbagCellText(sheet, r, 4).toUpperCase();
      const e = tbagCellText(sheet, r, 5).toUpperCase();
      if (a === "AL" && b === "HYBRIDE" && c === "BANNIERE" && d === "NATURE" && /^MM[-_ ]?\d+/.test(e)) {
        return { sheetName: name, headerRow: r };
      }
    }
  }
  return null;
}

function tbagExtractYear(sheet) {
  for (let r = 1; r <= 6; r++) {
    for (let c = 1; c <= 4; c++) {
      const text = tbagCellText(sheet, r, c);
      const hit = text.match(/(20\d{2})/);
      if (hit) return hit[1];
    }
  }
  return "";
}

function tbagMonthColumns(sheet, headerRow, range) {
  const cols = [];
  for (let c = 5; c <= range.e.c + 1; c++) {
    const token = tbagCellText(sheet, headerRow, c);
    if (/^MM[-_ ]?\d{1,2}$/i.test(token)) cols.push({ col: c, token });
  }
  return cols;
}

function tbagPopulationFromNature(nature = "") {
  const n = normalizeText(nature);
  if (/\bcdi\b/.test(n)) return "CDI";
  if (/\bcdd\b/.test(n)) return "CDD";
  if (/\bett\b|interim/.test(n)) return "ETT";
  return "";
}

function tbagIsSensitiveText(value = "") {
  const text = normalizeText(value);
  return /matricule|nomprenom|prenom|date.?nai|baps|code.?sal|identifiant|badge/.test(text);
}

function tbagNormalizeBanner(value = "") {
  return String(value || "").trim().replace(/\s+/g, " ");
}

function tbagAnalyzeRows(sheet, sheetName, headerRow, year, monthCols, range, targetSiteCode = PERFORMANCE_IMPORT_SITE.code) {
  const rows = [];
  const populations = new Set();
  const banners = new Set();
  const periods = new Set();
  const excludedSensitiveHits = [];

  const totalsByPeriod = {};
  const volumeByPopPeriod = {};

  for (let r = headerRow + 1; r <= range.e.r + 1; r++) {
    const rowSiteCode = performanceImportSiteCode(tbagCellText(sheet, r, 1));
    if (rowSiteCode && rowSiteCode !== performanceImportSiteCode(targetSiteCode)) continue;
    const hybrid = tbagCellText(sheet, r, 2);
    const bannerRaw = tbagCellText(sheet, r, 3);
    const nature = tbagCellText(sheet, r, 4);
    if (!nature) continue;
    if (tbagIsSensitiveText(`${hybrid} ${bannerRaw} ${nature}`)) {
      if (excludedSensitiveHits.length < 25) excludedSensitiveHits.push(`row ${r}`);
      continue;
    }
    const banner = tbagNormalizeBanner(bannerRaw);
    const normalizedNature = normalizeText(nature);
    const isPrepDirect = normalizedNature === normalizeText("PREP HEURES DIRECTES");
    const pop = tbagPopulationFromNature(nature);
    const isVolumePop = /^colis\s+/i.test(nature) && Boolean(pop);
    const isHoursPop = /^heures\s+/i.test(nature) && /prepa|prépa|preparation|préparation/i.test(nature) && Boolean(pop);
    const isProdPop = /^prod\s+/i.test(nature) && Boolean(pop);

    if (!isPrepDirect && !isVolumePop && !isHoursPop && !isProdPop) continue;

    if (pop) populations.add(pop);
    if (isPrepDirect && banner && normalizeText(banner) !== normalizeText("TOTAL BANNIERE")) banners.add(banner);

    for (const monthCol of monthCols) {
      const period = tbagCanonicalPeriod(monthCol.token, year);
      if (!period) continue;
      const value = tbagCellNumber(sheet, r, monthCol.col);
      if (value === null) continue;
      periods.add(period);
      const sourceCell = `${cgtabColLetter(monthCol.col)}${r}`;
      const sourceFormula = tbagCellFormula(sheet, r, monthCol.col);

      if (isPrepDirect && normalizeText(banner) === normalizeText("TOTAL BANNIERE")) {
        totalsByPeriod[period] = totalsByPeriod[period] || {};
        totalsByPeriod[period].hours = value;
        rows.push(tbagBuildRow({ period, metricKey: "preparation.hours.total", label: "Préparation - Heures directes", value, unit: "h", population: "TOTAL", banner: "TOTAL BANNIERE", aggregationType: "sum", confidence: "élevée", sourceSheet: sheetName, sourceCell, sourceColumns: "NATURE=PREP HEURES DIRECTES|BANNIERE=TOTAL BANNIERE", sourceFormula }));
      }

      if (isPrepDirect && banner && normalizeText(banner) !== normalizeText("TOTAL BANNIERE")) {
        rows.push(tbagBuildRow({ period, metricKey: "preparation.banner.hours", label: "Préparation - Heures directes bannière", value, unit: "h", population: "TOTAL", banner, aggregationType: "sum", confidence: "élevée", sourceSheet: sheetName, sourceCell, sourceColumns: "NATURE=PREP HEURES DIRECTES", sourceFormula }));
      }

      if (isVolumePop && pop) {
        volumeByPopPeriod[period] = volumeByPopPeriod[period] || {};
        volumeByPopPeriod[period][pop] = value;
        rows.push(tbagBuildRow({ period, metricKey: `preparation.volume.${pop.toLowerCase()}`, label: `Préparation - Volume ${pop}`, value, unit: "colis", population: pop, banner: "TOTAL BANNIERE", aggregationType: "sum", confidence: "élevée", sourceSheet: sheetName, sourceCell, sourceColumns: `NATURE=${nature}`, sourceFormula }));
      }

      if (isHoursPop && pop) {
        rows.push(tbagBuildRow({ period, metricKey: `preparation.hours.${pop.toLowerCase()}`, label: `Préparation - Heures ${pop}`, value, unit: "h", population: pop, banner: "TOTAL BANNIERE", aggregationType: "sum", confidence: "élevée", sourceSheet: sheetName, sourceCell, sourceColumns: `NATURE=${nature}`, sourceFormula }));
      }

      if (isProdPop && pop) {
        rows.push(tbagBuildRow({ period, metricKey: `preparation.productivity.${pop.toLowerCase()}`, label: `Préparation - Productivité ${pop}`, value, unit: "colis/h", population: pop, banner: "TOTAL BANNIERE", aggregationType: "ratio", confidence: sourceFormula ? "élevée" : "moyenne", sourceSheet: sheetName, sourceCell, sourceColumns: `NATURE=${nature}`, sourceFormula }));
      }
    }
  }

  for (const period of periods) {
    const popVolumes = volumeByPopPeriod[period] || {};
    const totalVolume = ["CDI", "CDD", "ETT"].reduce((sum, key) => sum + (Number(popVolumes[key]) || 0), 0);
    if (totalVolume > 0) {
      rows.push(tbagBuildRow({ period, metricKey: "preparation.volume.total", label: "Préparation - Volume total", value: Number(totalVolume.toFixed(2)), unit: "colis", population: "TOTAL", banner: "TOTAL BANNIERE", aggregationType: "sum", confidence: "moyenne", sourceSheet: sheetName, sourceCell: "derived", sourceColumns: "Colis CDI|Colis CDD|Colis ETT", sourceFormula: "sum(populations)" }));
    }
    const totalHours = Number((totalsByPeriod[period] || {}).hours);
    if (totalVolume > 0 && Number.isFinite(totalHours) && totalHours > 0) {
      rows.push(tbagBuildRow({ period, metricKey: "preparation.productivity.total", label: "Préparation - Productivité globale", value: Number((totalVolume / totalHours).toFixed(2)), unit: "colis/h", population: "TOTAL", banner: "TOTAL BANNIERE", aggregationType: "ratio", confidence: "moyenne", sourceSheet: sheetName, sourceCell: "derived", sourceColumns: "Volume total / Heures directes total", sourceFormula: "(Colis CDI+CDD+ETT)/PREP HEURES DIRECTES" }));
    }
  }

  return {
    rows: dedupeImportRows(rows),
    periods: [...periods].sort(),
    populations: [...populations].sort(),
    banners: [...banners].sort(),
    excludedSensitiveHits
  };
}

async function analyzeTBagFile(file, detected) {
  const ext = (detected.extension || "").toLowerCase();
  if (ext !== "xlsb" && !String(file.name || "").toLowerCase().endsWith(".xlsb")) {
    return {
      ...detected,
      source: "T_BAG",
      sourceType: "T-Bag XLSB",
      status: "non reconnu",
      confidence: "faible",
      message: "V5.18.7 cible le classeur XLSB T-Bag validé."
    };
  }
  if (!window.XLSX?.read || !window.XLSX?.utils?.decode_range) {
    throw new Error("Bibliothèque XLSX indisponible pour lire le classeur T-Bag.");
  }
  const buffer = await readFileArrayBuffer(file);
  const workbook = window.XLSX.read(buffer, { type: "array", cellFormula: true, cellText: false, raw: true });
  const primary = tbagFindPrimarySheet(workbook);
  if (!primary) throw new Error("Structure T-Bag non reconnue (en-tête AL/HYBRIDE/BANNIERE/NATURE/MM-xx introuvable).");
  const sheet = workbook.Sheets[primary.sheetName];
  const range = window.XLSX.utils.decode_range(sheet["!ref"]);
  const year = tbagExtractYear(sheet) || "2026";
  const monthCols = tbagMonthColumns(sheet, primary.headerRow, range);
  if (!monthCols.length) throw new Error("Aucune colonne mensuelle MM-xx détectée dans T-Bag.");
    const detectedSiteCodes = performanceImportDistinctSiteCodes(Array.from({ length: Math.max(0, range.e.r - primary.headerRow + 1) }, (_, index) => tbagCellText(sheet, primary.headerRow + 1 + index, 1)));
  if (detectedSiteCodes.length && !detectedSiteCodes.includes(PERFORMANCE_IMPORT_SITE.code)) {
    return { ...detected, source: "T_BAG", sourceType: "T-Bag XLSB", status: "non reconnu", confidence: "faible", detectedSiteCodes, message: `Le fichier T-Bag ne contient pas le site ${performanceImportSiteLabel()}.` };
  }
  const analyzed = tbagAnalyzeRows(sheet, primary.sheetName, primary.headerRow, year, monthCols, range, PERFORMANCE_IMPORT_SITE.code);
  return {
    ...detected,
    source: "T_BAG",
    sourceType: "T-Bag XLSB",
    status: analyzed.rows.length ? "reconnu" : "probablement reconnu",
    confidence: analyzed.rows.length ? "élevée" : "moyenne",
    site: PERFORMANCE_IMPORT_SITE.name,
    siteCode: PERFORMANCE_IMPORT_SITE.code,
    detectedSiteCodes,
    scope: "Préparation",
    period: analyzed.periods[0] || "",
    periods: analyzed.periods,
    selectedPeriods: analyzed.periods,
    sheets: ensureArray(workbook.SheetNames || []),
    selectedSheet: primary.sheetName,
    detectedIndicators: analyzed.rows,
    excludedNominativeColumns: TBAG_SENSITIVE_MARKERS,
    message: `${analyzed.rows.length} indicateur(s) Préparation agrégé(s) extrait(s) depuis ${primary.sheetName}. Populations: ${analyzed.populations.join(", ") || "aucune"}. Bannières: ${analyzed.banners.join(", ") || "aucune"}.`
  };
}

