    enabled: false,
    state: DEOS_LINKS_SYNC_STATUS.LOCAL_ONLY,
    queue: [],
    metaByClientId: {},
    remoteCount: 0,
    pendingCount: 0,
    syncedCount: 0,
    conflictCount: 0,
    lastSyncAt: "",
    lastError: "",
    lastAnalysisAt: "",
    lastAnalysis: null,
    currentDevice: detectLinksSyncDeviceLabel(),
    syncing: false,
    ...overrides
