  deosLinksSyncPreviewDialog = {
    open: false,
    busy: false,
    mode: "preview",
    selectedClientIds: [],
    error: "",
    analysis: null,
    message: ""
  };
  deosLinksSyncMergeDialog = {
    open: false,
    clientId: "",
    error: "",
    local: null,
    remote: null
  };
